export type UserRole = 'BORROWER' | 'ADMIN' | 'DEVELOPER';
export type CollateralType = 'LAPTOP' | 'PHONE' | 'CAR' | 'APPLIANCE' | 'NONE';

export interface User {
  id: string;
  name: string;
  email: string;
  nrc: string;
  phone: string;
  address: string;
  operator: MobileOperator;
  role: UserRole;
  joinedAt: string;
  walletBalance?: number;
  trustScore?: number; // 0-100
}

export interface Transaction {
  id: string;
  loanId?: string;
  userId?: string;
  userName?: string;
  amount: number;
  type: 'DISBURSEMENT' | 'REPAYMENT' | 'FEE' | 'WALLET_WITHDRAW' | 'WALLET_DEPOSIT';
  timestamp: string;
  status: 'SUCCESS' | 'FAILED' | 'PENDING' | 'CONFIRMED_BY_MANAGEMENT';
  operator?: MobileOperator;
}

export interface AuditLog {
  id: string;
  userId: string;
  userName: string;
  action: string;
  category: 'SECURITY' | 'FINANCE' | 'SYSTEM';
  details: string;
  timestamp: string;
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
}

