  async disburse(loanId: string): Promise<{ status: number; transactionId?: string; error?: string }> {
    const loan = this.loans.find(l => l.id === loanId);
    if (!loan) return { status: 404 };

    const user = this.users.find(u => u.id === loan.userId);
    if (!user) return { status: 404 };

    const txId = `MANUAL-TX-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;
    loan.status = 'DISBURSED';
    loan.disbursedAt = new Date().toISOString();
    loan.transactionId = txId;

