import React, { useState, useRef, useMemo, useEffect } from 'react';
import { CollateralType } from '../types';
import { analyzeSafetyPhoto, extractNRCData } from '../services/geminiService';
import { formatCurrency } from '../utils/loanCalculator';

interface LoanFormProps {
  onSubmit: (loanData: { 
    principal: number; 
    purpose: string; 
    collateral: File | null;
    collateralType: CollateralType;
    collateralValue: number;
  }) => void;
  isLoading: boolean;
}

const MAX_SYSTEM_LOAN = 20000;
const MAX_LTV_RATIO = 0.7;

const COLLATERAL_OPTIONS = [
  { id: 'PHONE', label: 'Phone', icon: 'fa-mobile-screen', min: 1500, max: 15000 },
  { id: 'LAPTOP', label: 'Laptop', icon: 'fa-laptop', min: 4000, max: 25000 },
  { id: 'APPLIANCE', label: 'Home App', icon: 'fa-plug', min: 2000, max: 30000 },
  { id: 'CAR', label: 'Vehicle', icon: 'fa-car', min: 60000, max: 800000 },
] as const;

const LoanForm: React.FC<LoanFormProps> = ({ onSubmit, isLoading }) => {
  const [amount, setAmount] = useState<string>('');
  const [purpose, setPurpose] = useState<string>('');
  const [photo, setPhoto] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [isScanningNRC, setIsScanningNRC] = useState(false);
  const [lastSaved, setLastSaved] = useState<string | null>(null);

  const [selectedCollateral, setSelectedCollateral] = useState<CollateralType>('NONE');
  const [itemDetails, setItemDetails] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const nrcInputRef = useRef<HTMLInputElement>(null);

  // Restore Draft on Mount
  useEffect(() => {
    const draft = localStorage.getItem('kwachatime_loan_draft');
    if (draft) {
      try {
        const parsed = JSON.parse(draft);
        if (parsed.amount) setAmount(parsed.amount);
        if (parsed.purpose) setPurpose(parsed.purpose);
        if (parsed.selectedCollateral) setSelectedCollateral(parsed.selectedCollateral);
        if (parsed.itemDetails) setItemDetails(parsed.itemDetails);
      } catch (e) {
        console.error("Failed to load loan draft", e);
      }
    }
  }, []);

  // Auto-save every 30 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      const draft = {
        amount,
        purpose,
        selectedCollateral,
        itemDetails,
        timestamp: new Date().toISOString()
      };
      localStorage.setItem('kwachatime_loan_draft', JSON.stringify(draft));
      setLastSaved(new Date().toLocaleTimeString());
    }, 30000);
    return () => clearInterval(interval);
  }, [amount, purpose, selectedCollateral, itemDetails]);

  const estimatedWorth = useMemo(() => {
    if (selectedCollateral === 'NONE') return 0;
    const opt = COLLATERAL_OPTIONS.find(o => o.id === selectedCollateral);
    if (!opt) return 0;
    let baseline = (opt.min + opt.max) / 2;
    const details = itemDetails.toLowerCase();
    if (details.includes('pro') || details.includes('max')) baseline *= 1.3;
    if (details.includes('old') || details.includes('cracked')) baseline *= 0.5;
    return Math.min(baseline, opt.max);
  }, [selectedCollateral, itemDetails]);

  const maxBorrowable = useMemo(() => estimatedWorth * MAX_LTV_RATIO, [estimatedWorth]);
  const isWorthInsufficient = parseFloat(amount) > maxBorrowable;

  const handleNRCScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsScanningNRC(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        const data = await extractNRCData(base64);
        if (data) {
          alert(`NRC Identified: ${data.name}. Details have been synced.`);
          console.log("OCR Data:", data);
        }
        setIsScanningNRC(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || !photo || selectedCollateral === 'NONE') {
      alert("Missing required fields.");
      return;
    };
    if (isWorthInsufficient) {
      alert("Amount exceeds asset credit limit.");
      return;
    }

    // Clear draft on successful submission
    localStorage.removeItem('kwachatime_loan_draft');

    onSubmit({ 
      principal: parseFloat(amount), 
      purpose, 
      collateral: photo,
      collateralType: selectedCollateral,
      collateralValue: estimatedWorth
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsAnalyzing(true);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        const result = await analyzeSafetyPhoto(base64);
        if (!result.isValid) {
          setAnalysisError(result.reason);
          setPhoto(null);
        } else {
          setPhoto(file);
