const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('theme') === 'dark');

  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'LOGS' | 'USERS' | 'SIMULATE' | 'LIVE'>('MONITOR');

  // Theme Toggle Effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  // Borrower Live Tracking Logic
  useEffect(() => {
    if (!currentUser || currentUser.role !== 'BORROWER') return;

    const activeTravelLoan = allLoans.find(l => l.userId === currentUser.id && l.isTravelingToSite);
    if (!activeTravelLoan) return;

    const watchId = navigator.geolocation.watchPosition(
      (pos) => {
        apiService.updateLocation(currentUser.id, {
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          timestamp: new Date().toISOString()
        });
      },
      (err) => console.error("Tracking failed", err),
      { enableHighAccuracy: true }
    );

    return () => navigator.geolocation.clearWatch(watchId);
  }, [currentUser, allLoans]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const upcomingDues = useMemo(() => {
    const now = new Date();
    return allLoans.filter(l => {
      if (l.status !== 'DISBURSED') return false;
      const dueDate = new Date(l.dueDate);
      const diffMs = dueDate.getTime() - now.getTime();
      const diffHrs = diffMs / (1000 * 60 * 60);
      return diffHrs > 0 && diffHrs <= 24;
    });
  }, [allLoans]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
