import React, { useState, useRef, useMemo, useEffect } from 'react';
import { CollateralType } from '../types';
import { analyzeSafetyPhoto, extractNRCData } from '../services/geminiService';
import { formatCurrency } from '../utils/loanCalculator';

interface LoanFormProps {
  onSubmit: (loanData: { 
    principal: number; 
    purpose: string; 
    collateral: File | null;
    collateralType: CollateralType;
    collateralValue: number;
  }) => void;
  isLoading: boolean;
}

const MAX_LTV_RATIO = 0.7;

const COLLATERAL_OPTIONS = [
  { id: 'PHONE', label: 'Phone', icon: 'fa-mobile-screen', min: 1500, max: 15000 },
  { id: 'LAPTOP', label: 'Laptop', icon: 'fa-laptop', min: 4000, max: 25000 },
  { id: 'APPLIANCE', label: 'Home App', icon: 'fa-plug', min: 2000, max: 30000 },
  { id: 'CAR', label: 'Vehicle', icon: 'fa-car', min: 60000, max: 800000 },
] as const;

const LoanForm: React.FC<LoanFormProps> = ({ onSubmit, isLoading }) => {
  const [amount, setAmount] = useState<string>('');
  const [purpose, setPurpose] = useState<string>('');
  const [photo, setPhoto] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [selectedCollateral, setSelectedCollateral] = useState<CollateralType>('NONE');
  const [itemDetails, setItemDetails] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const draft = localStorage.getItem('kwachatime_loan_draft');
    if (draft) {
      try {
        const parsed = JSON.parse(draft);
        if (parsed.amount) setAmount(parsed.amount);
        if (parsed.purpose) setPurpose(parsed.purpose);
        if (parsed.selectedCollateral) setSelectedCollateral(parsed.selectedCollateral);
      } catch (e) {}
    }
  }, []);

  const estimatedWorth = useMemo(() => {
    if (selectedCollateral === 'NONE') return 0;
    const opt = COLLATERAL_OPTIONS.find(o => o.id === selectedCollateral);
    if (!opt) return 0;
    return (opt.min + opt.max) / 2;
  }, [selectedCollateral]);

  const maxBorrowable = useMemo(() => estimatedWorth * MAX_LTV_RATIO, [estimatedWorth]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || selectedCollateral === 'NONE') return;
    onSubmit({ 
      principal: parseFloat(amount), 
      purpose, 
      collateral: photo,
      collateralType: selectedCollateral,
      collateralValue: estimatedWorth
    });
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl p-8 border border-gray-100 dark:border-slate-700 max-w-md mx-auto animate-fadeIn relative transition-colors">
      <h2 className="text-2xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter mb-8">Fast Kwacha</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400">1. Select Collateral</label>
          <div className="grid grid-cols-4 gap-3">
            {COLLATERAL_OPTIONS.map(opt => (
              <button key={opt.id} type="button" onClick={() => setSelectedCollateral(opt.id as CollateralType)} className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all ${selectedCollateral === opt.id ? 'bg-emerald-800 border-emerald-800 text-white shadow-lg' : 'bg-gray-50 dark:bg-slate-900 border-gray-100 dark:border-slate-700 text-gray-400'}`}>
                <i className={`fas ${opt.icon} text-xl mb-2`}></i>
                <span className="text-[8px] font-black uppercase">{opt.label}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400">2. Loan Information</label>
          <div className="space-y-3">
            <div className="relative">
              <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-emerald-800 dark:text-emerald-400">K</span>
              <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} className="w-full bg-gray-50 dark:bg-slate-900 dark:text-white border-2 border-gray-100 dark:border-slate-700 p-5 pl-10 rounded-2xl text-xl font-black outline-none focus:border-emerald-500" placeholder="0.00" />
            </div>
            <input type="text" value={purpose} onChange={(e) => setPurpose(e.target.value)} className="w-full bg-gray-50 dark:bg-slate-900 dark:text-white border-2 border-gray-100 dark:border-slate-700 p-5 rounded-2xl text-xs font-bold outline-none focus:border-emerald-500" placeholder="Purpose of loan" />
          </div>
        </div>

        <button type="submit" disabled={isLoading} className="w-full bg-emerald-800 text-white py-6 rounded-[1.8rem] font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 disabled:opacity-50">
          {isLoading ? "Submitting..." : "Apply Now"}
        </button>
      </form>
    </div>
  );
};

