import { User, Loan, Transaction, AppNotification, MobileOperator, AuditLog, Location, TravelMode } from './types';

class VirtualBackend {
  private users: User[] = [];
  private loans: Loan[] = [];
  private transactions: Transaction[] = [];
  private auditLogs: AuditLog[] = [];
  private notifications: AppNotification[] = [];
  private vaultBalance: number = 750000;

  constructor() {
    this.loadFromStorage();
    setInterval(() => this.saveToStorage(), 5000);
  }

  private loadFromStorage() {
    const data = localStorage.getItem('kwachatime_db');
    if (data) {
      const parsed = JSON.parse(data);
      this.users = parsed.users || [];
      this.loans = parsed.loans || [];
      this.transactions = parsed.transactions || [];
      this.auditLogs = parsed.auditLogs || [];
      this.notifications = parsed.notifications || [];
      this.vaultBalance = parsed.vaultBalance ?? 750000;
    }
  }

  private saveToStorage() {
    const data = {
      users: this.users,
      loans: this.loans,
      transactions: this.transactions,
      auditLogs: this.auditLogs,
      notifications: this.notifications,
      vaultBalance: this.vaultBalance
    };
    localStorage.setItem('kwachatime_db', JSON.stringify(data));
  }

  public createAuditLog(userId: string, userName: string, action: string, category: AuditLog['category'], details: string, severity: AuditLog['severity'] = 'LOW') {
    const log: AuditLog = {
      id: `LOG-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      userId,
      userName,
      action,
      category,
      details,
      timestamp: new Date().toISOString(),
      severity,
      deviceInfo: navigator.userAgent.slice(0, 50)
    };
    this.auditLogs.unshift(log);
    if (this.auditLogs.length > 500) this.auditLogs.pop();
  }

  async adjustVault(amount: number, reason: string): Promise<{ status: number }> {
    this.vaultBalance += amount;
    this.createAuditLog('SYSTEM', 'MANAGEMENT', 'Capital Adjustment', 'FINANCE', `Vault adjusted by ZMW ${amount}. Reason: ${reason}`, 'MEDIUM');
    this.transactions.unshift({
      id: `ADJ-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      amount: amount,
      type: amount > 0 ? 'WALLET_DEPOSIT' : 'WALLET_WITHDRAW',
      timestamp: new Date().toISOString(),
      status: 'SUCCESS',
      userName: 'MANAGEMENT'
    });
    return { status: 200 };
  }

  async updateLocation(userId: string, location: Location): Promise<{ status: number }> {
    const user = this.users.find(u => u.id === userId);
    if (user) {
      user.currentLocation = location;
    }
    return { status: 200 };
  }

  async setTravelStatus(loanId: string, status: boolean, mode?: TravelMode, eta?: string): Promise<{ status: number }> {
    const loan = this.loans.find(l => l.id === loanId);
    if (loan) {
      loan.isTravelingToSite = status;
      if (mode) loan.travelMode = mode;
      if (eta) loan.estimatedArrival = eta;
    }
    return { status: 200 };
  }

  async login(email: string): Promise<{ status: number; user?: User; error?: string }> {
    let user = this.users.find(u => u.email === email);
    if (user) {
      this.createAuditLog(user.id, user.name, 'Session Initiated', 'SECURITY', `Successful login via ${email}`, 'LOW');
    }
    return { status: 200, user };
  }

  async register(userData: User): Promise<{ status: number; user: User }> {
    const existingIndex = this.users.findIndex(u => u.email === userData.email);
    const userToSave = { ...userData, walletBalance: userData.walletBalance ?? 0, trustScore: 50 };
    if (existingIndex > -1) {
      this.users[existingIndex] = { ...this.users[existingIndex], ...userToSave };
      return { status: 200, user: this.users[existingIndex] };
    }
    this.users.push(userToSave);
    return { status: 201, user: userToSave };
  }

  async submitLoan(loan: Loan): Promise<{ status: number; loan: Loan }> {
    this.loans.push(loan);
    return { status: 201, loan };
  }

  async simulateLoan(data: { name: string, principal: number, disbursedDate: string, dueDate: string }): Promise<{ status: number }> {
    const userId = `SIM-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;
    const loanId = `SIM-REQ-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;

    const newLoan: Loan = {
      id: loanId,
      userId: userId,
      userName: data.name,
      principal: data.principal,
      purpose: "Simulation/Manual Entry",
      status: 'DISBURSED',
      createdAt: data.disbursedDate,
      disbursedAt: data.disbursedDate,
      dueDate: data.dueDate,
    };

    this.loans.push(newLoan);
    this.vaultBalance -= data.principal;
    return { status: 200 };
  }

  async disburse(loanId: string): Promise<{ status: number; transactionId?: string; error?: string }> {
    const loan = this.loans.find(l => l.id === loanId);
    if (!loan) return { status: 404 };

    const user = this.users.find(u => u.id === loan.userId);
    if (!user) return { status: 404 };

    const txId = `MANUAL-TX-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;
    loan.status = 'DISBURSED';
    loan.disbursedAt = new Date().toISOString();
    loan.transactionId = txId;
    loan.isTravelingToSite = false;

    this.vaultBalance -= loan.principal;
    user.walletBalance = (user.walletBalance || 0) + loan.principal;

    this.transactions.unshift({
      id: txId,
      loanId: loan.id,
      userId: user.id,
      userName: user.name,
      amount: -loan.principal,
      type: 'DISBURSEMENT',
      timestamp: loan.disbursedAt,
      status: 'CONFIRMED_BY_MANAGEMENT'
    });

    return { status: 200, transactionId: txId };
  }

  // Fix: Implemented missing withdrawToMoMo method
  async withdrawToMoMo(userId: string, amount: number, operator: MobileOperator): Promise<{ status: number }> {
    const user = this.users.find(u => u.id === userId);
    if (user && (user.walletBalance || 0) >= amount) {
      user.walletBalance = (user.walletBalance || 0) - amount;
      this.createAuditLog(userId, user.name, 'MoMo Withdrawal', 'FINANCE', `Withdrew ZMW ${amount} via ${operator}`, 'LOW');
      this.transactions.unshift({
        id: `WDL-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        userId,
        userName: user.name,
        amount: -amount,
        type: 'WALLET_WITHDRAW',
        timestamp: new Date().toISOString(),
        status: 'SUCCESS',
        operator
      });
    }
    return { status: 200 };
  }

  // Fix: Implemented missing depositFromMoMo method
  async depositFromMoMo(userId: string, amount: number): Promise<{ status: number }> {
    const user = this.users.find(u => u.id === userId);
    if (user) {
      user.walletBalance = (user.walletBalance || 0) + amount;
      this.vaultBalance += amount;
      this.createAuditLog(userId, user.name, 'MoMo Deposit', 'FINANCE', `Deposited ZMW ${amount}`, 'LOW');
      this.transactions.unshift({
        id: `DEP-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        userId,
        userName: user.name,
        amount: amount,
        type: 'WALLET_DEPOSIT',
        timestamp: new Date().toISOString(),
        status: 'SUCCESS'
      });
    }
    return { status: 200 };
  }

  async repay(loanId: string, userId: string, amount: number): Promise<{ status: number; error?: string }> {
    const loan = this.loans.find(l => l.id === loanId);
    const user = this.users.find(u => u.id === userId);

    if (loan) loan.status = 'REPAID';
    if (user) user.walletBalance = (user.walletBalance || 0) - amount;
    this.vaultBalance += amount;

    return { status: 200 };
  }

  getDashboardStats() {
    return {
      vaultBalance: this.vaultBalance,
      activeLoansCount: this.loans.filter(l => l.status === 'DISBURSED').length,
      pendingRequestsCount: this.loans.filter(l => l.status === 'PENDING').length,
      totalUsersCount: this.users.length,
      loans: this.loans,
      users: this.users,
      transactions: this.transactions,
      auditLogs: this.auditLogs
    };
  }
}

export const backend = new VirtualBackend();

