              { id: 'PENDING', icon: 'fa-hourglass-half', label: 'Approvals' },
              { id: 'LIVE', icon: 'fa-satellite-dish', label: 'Live Tracking' },
              { id: 'USERS', icon: 'fa-user-group', label: 'Ledger' }
            ].map(tab => (
              <button key={tab.id} onClick={() => setActiveAdminTab(tab.id as any)} className={`flex-1 flex items-center justify-center gap-3 px-6 py-4 rounded-2xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white shadow-lg scale-105' : 'text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-700'}`}>
                <i className={`fas ${tab.icon} text-sm`}></i>
                <span className="hidden sm:inline">{tab.label}</span>
              </button>
            ))}
          </div>

          <div className="min-h-[60vh]">
            {activeAdminTab === 'LIVE' && (
              <div className="bg-white dark:bg-slate-800 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-700">
                <div className="flex justify-between items-center mb-8">
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tighter">Incoming Borrowers</h3>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Real-time GPS Tracking</p>
                  </div>
                  <div className="w-12 h-12 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-2xl flex items-center justify-center animate-pulse"><i className="fas fa-tower-broadcast"></i></div>
                </div>

                <div className="space-y-6">
                  {allLoans.filter(l => l.isTravelingToSite).map(loan => {
                    const user = allUsers.find(u => u.id === loan.userId);
                    return (
                      <div key={loan.id} className="p-6 bg-gray-50 dark:bg-slate-900 rounded-[2.5rem] border-2 border-emerald-500/20 flex flex-col md:flex-row items-center justify-between gap-6">
                        <div className="flex items-center gap-4 w-full">
                          <div className="w-16 h-16 bg-emerald-800 text-white rounded-2xl flex items-center justify-center text-2xl font-black">{loan.userName[0]}</div>
                          <div>
                            <h4 className="font-black text-lg">{loan.userName}</h4>
                            <div className="flex gap-3 text-[10px] font-black uppercase text-emerald-600">
                              <span><i className={`fas ${loan.travelMode === 'driving' ? 'fa-car' : loan.travelMode === 'cycling' ? 'fa-bicycle' : 'fa-person-walking'} mr-2`}></i>{loan.travelMode}</span>
                              <span className="text-orange-500"><i className="fas fa-clock mr-2"></i>ETA: {loan.estimatedArrival}</span>
                            </div>
                          </div>
                        </div>
                        <div className="w-full md:w-auto text-center md:text-right bg-emerald-500/10 p-4 rounded-2xl border border-emerald-500/20">
                          <p className="text-[9px] font-black text-emerald-600 uppercase mb-1">Live Coordinates</p>
                          <p className="text-[11px] font-mono text-slate-500">{user?.currentLocation ? `${user.currentLocation.lat.toFixed(5)}, ${user.currentLocation.lng.toFixed(5)}` : 'Awaiting Ping...'}</p>
                        </div>
                      </div>
                    );
                  })}
                  {allLoans.filter(l => l.isTravelingToSite).length === 0 && (
                    <div className="py-20 text-center opacity-30">
                       <i className="fas fa-satellite text-4xl mb-4"></i>
                       <p className="text-[10px] font-black uppercase">No active tracking sessions</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeAdminTab === 'MONITOR' && (
              <div className="bg-white dark:bg-slate-800 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-700">
                 <h3 className="text-xl font-black uppercase tracking-tighter mb-8">Active Portfolio</h3>
                 <div className="space-y-4">
                    {allLoans.filter(l => l.status === 'DISBURSED').map(loan => (
                      <div key={loan.id} className="p-6 bg-gray-50 dark:bg-slate-900 rounded-[2.5rem] flex items-center justify-between border border-transparent hover:border-emerald-500/50 transition-all">
                        <div className="flex items-center gap-4">
                           <div className="w-12 h-12 bg-slate-900 text-white rounded-xl flex items-center justify-center font-black">{loan.userName[0]}</div>
                           <div>
                              <p className="font-black">{loan.userName}</p>
                              <p className="text-[9px] font-black uppercase text-gray-400">Due: {new Date(loan.dueDate).toLocaleDateString()}</p>
                           </div>
                        </div>
                        <p className="text-xl font-black">{formatCurrency(loan.principal)}</p>
                      </div>
                    ))}
                 </div>
              </div>
            )}

            {activeAdminTab === 'PENDING' && (
              <div className="space-y-4">
                {allLoans.filter(l => l.status === 'PENDING').map(loan => (
                  <div key={loan.id} className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-xl border border-gray-100 dark:border-slate-700 flex flex-col md:flex-row items-center justify-between gap-8">
                    <div className="flex items-center gap-6 w-full">
                      <div className="w-16 h-16 bg-gray-100 dark:bg-slate-900 rounded-2xl flex items-center justify-center font-black text-2xl">
                        {loan.userName[0]}
