                      <div>
                        <h4 className="text-xl font-black">{loan.userName}</h4>
                        <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">{loan.purpose}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-6 w-full md:w-auto justify-between md:justify-end">
                      <p className="text-2xl font-black text-emerald-800 dark:text-emerald-400">{formatCurrency(loan.principal)}</p>
                      <button onClick={() => handleManualDisbursementConfirm(loan.id)} className="px-8 py-4 bg-emerald-800 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg">Confirm</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      ) : (
        /* Borrower View */
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-12 animate-fadeIn text-slate-900 dark:text-white transition-colors">
           <div className="lg:col-span-1 space-y-8 order-2 lg:order-1">
              <Roadmap />
              <OfficeLocator />
           </div>

           <div className="lg:col-span-2 space-y-8 order-1 lg:order-2">
              <div className="bg-emerald-950 text-white p-8 md:p-12 rounded-[3.5rem] shadow-2xl border-4 border-emerald-900 relative overflow-hidden group">
                <div className="relative z-10">
                   <p className="text-[10px] font-black uppercase text-emerald-500 mb-2 tracking-[0.3em]">Current Available Capital</p>
                   <p className="text-4xl md:text-6xl font-black mb-10 tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                   <div className="grid grid-cols-2 gap-4">
                      <button className="bg-white/10 p-5 rounded-3xl text-[9px] font-black uppercase flex flex-col items-center gap-3"><i className="fas fa-plus-circle text-xl"></i> Fund Ledger</button>
                      <button className="bg-emerald-600 p-5 rounded-3xl text-[9px] font-black uppercase shadow-xl flex flex-col items-center gap-3"><i className="fas fa-paper-plane text-xl"></i> Payout MoMo</button>
                   </div>
                </div>
              </div>

              {allLoans.filter(l => l.status === 'PENDING').length > 0 && (
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] border-2 border-emerald-500/20 shadow-xl">
                  <div className="flex justify-between items-center mb-6">
                    <div>
                      <h4 className="text-lg font-black uppercase tracking-tighter">Approved & Ready</h4>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Select transport to calculate PTA</p>
                    </div>
                    <div className="w-10 h-10 bg-emerald-50 text-white rounded-xl flex items-center justify-center"><i className="fas fa-map-location-dot"></i></div>
                  </div>

                  <div className="grid grid-cols-3 gap-4 mb-8">
                    {(['walking', 'cycling', 'driving'] as TravelMode[]).map(m => (
                      <button key={m} onClick={() => handleStartTravel(allLoans.find(l => l.status === 'PENDING')!.id, m)} className="bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl flex flex-col items-center gap-3 border-2 border-transparent hover:border-emerald-500 transition-all active:scale-95">
                        <i className={`fas ${m === 'driving' ? 'fa-car' : m === 'cycling' ? 'fa-bicycle' : 'fa-person-walking'} text-2xl text-emerald-600`}></i>
                        <span className="text-[9px] font-black uppercase">{m}</span>
                      </button>
                    ))}
                  </div>

                  {allLoans.some(l => l.isTravelingToSite) && (
                    <div className="bg-emerald-800 text-white p-6 rounded-3xl flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center animate-pulse"><i className="fas fa-satellite-dish"></i></div>
                        <div>
                          <p className="text-[10px] font-black uppercase opacity-60">Traveling Mode Active</p>
                          <p className="text-sm font-bold">ETA: {allLoans.find(l => l.isTravelingToSite)?.estimatedArrival}</p>
                        </div>
                      </div>
                      <button onClick={() => apiService.setTravelStatus(allLoans.find(l => l.isTravelingToSite)!.id, false)} className="text-[10px] font-black uppercase bg-white/10 px-4 py-2 rounded-xl">Cancel</button>
                    </div>
                  )}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <LoanForm onSubmit={async (data) => {
                    const loan: Loan = {
                       id: `REQ-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
                       userId: currentUser.id,
                       userName: currentUser.name,
                       principal: data.principal,
                       purpose: data.purpose,
                       status: 'PENDING',
                       createdAt: new Date().toISOString(),
                       dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
                       collateralType: data.collateralType,
                       collateralValue: data.collateralValue
                    };
                    await apiService.submitLoanRequest(loan);
                    refreshData();
                  }} isLoading={false} />

                  <div className="bg-white dark:bg-slate-800 rounded-[3rem] p-8 shadow-xl border border-gray-100 dark:border-slate-700">
                    <h3 className="text-[10px] font-black uppercase text-gray-400 mb-8 tracking-widest">Your Ledger</h3>
                    <div className="space-y-4">
                       {allLoans.map(l => (
                         <div key={l.id} className="p-6 bg-gray-50 dark:bg-slate-900 rounded-[2.5rem] border border-gray-100 dark:border-slate-700">
                            <p className="text-2xl font-black">{formatCurrency(l.principal)}</p>
                            <span className={`px-2 py-0.5 rounded text-[7px] font-black uppercase ${l.status === 'DISBURSED' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>{l.status}</span>
                         </div>
                       ))}
                    </div>
                  </div>
              </div>
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole } from '../types';

interface TourStep {
  title: string;
  description: string;
  icon: string;
}

interface OnboardingTourProps {
  role: UserRole;
  onComplete: () => void;
}

const OnboardingTour: React.FC<OnboardingTourProps> = ({ role, onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);

  const borrowerSteps: TourStep[] = [
    {
      title: "Welcome to KwachaTime",
      description: "Your premier partner for fast, secure micro-loans in Zambia. Let's show you how to secure your capital.",
      icon: "fa-hand-holding-dollar"
    },
    {
      title: "Your Digital Ledger",
      description: "Monitor your available wallet balance. You can fund your ledger at any branch or withdraw via MoMo instantly.",
      icon: "fa-wallet"
    },
    {
      title: "Fast Applications",
      description: "Choose your collateral, provide details, and snap a secure identity selfie to submit your request in seconds.",
      icon: "fa-bolt"
    },
    {
      title: "Navigation & PTA",
      description: "Once approved, use the map to find our office. Choose your transport mode to get an Estimated Arrival time.",
      icon: "fa-map-location-dot"
    }
  ];

  const adminSteps: TourStep[] = [
    {
      title: "Management Console",
      description: "Welcome to the Ops Terminal. Here you monitor vault liquidity, portfolio risk, and capital adjustments.",
      icon: "fa-terminal"
    },
    {
      title: "Approval Workflow",
      description: "Review incoming loan requests. Verify identity photos and collateral value before confirming physical payouts.",
      icon: "fa-hourglass-half"
    },
    {
      title: "Live GPS Tracking",
      description: "Monitor approved borrowers traveling to your site in real-time. Coordinate staff for incoming arrivals.",
      icon: "fa-satellite-dish"
    },
    {
      title: "Legal Ledger",
      description: "Access the master registry to manage user records and export professional PDF legal reports for audit.",
      icon: "fa-file-contract"
    }
  ];

  const steps = role === 'ADMIN' || role === 'DEVELOPER' ? adminSteps : borrowerSteps;

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onComplete();
    }
  };

  return (
    <div className="fixed inset-0 z-[6000] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-fadeIn">
      <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[3.5rem] overflow-hidden shadow-2xl border border-white/20 dark:border-slate-800 transition-all">
        <div className="p-8 md:p-12">
          <div className="flex justify-between items-center mb-10">
            <div className="flex gap-1">
              {steps.map((_, i) => (
                <div 
                  key={i} 
                  className={`h-1 rounded-full transition-all duration-500 ${i === currentStep ? 'w-8 bg-emerald-500' : 'w-2 bg-gray-200 dark:bg-slate-800'}`}
                />
              ))}
            </div>
            <button 
              onClick={onComplete}
              className="text-[10px] font-black uppercase text-gray-400 hover:text-red-500 transition-colors tracking-widest"
            >
              Skip
            </button>
          </div>

          <div className="text-center space-y-6 animate-slideUp" key={currentStep}>
            <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-3xl flex items-center justify-center mx-auto shadow-sm">
              <i className={`fas ${steps[currentStep].icon} text-3xl`}></i>
            </div>

            <div className="space-y-2">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tighter">
                {steps[currentStep].title}
              </h3>
              <p className="text-sm font-medium text-gray-500 dark:text-gray-400 leading-relaxed">
                {steps[currentStep].description}
              </p>
            </div>
          </div>

          <div className="mt-12">
            <button 
              onClick={handleNext}
              className="w-full py-6 bg-emerald-800 text-white rounded-3xl font-black uppercase tracking-widest shadow-xl hover:bg-emerald-950 transition-all active:scale-95 flex items-center justify-center gap-3"
            >
              {currentStep === steps.length - 1 ? 'Start Banking' : 'Continue'}
              <i className={`fas ${currentStep === steps.length - 1 ? 'fa-check' : 'fa-arrow-right'} text-sm`}></i>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default OnboardingTour;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { User, Loan, MobileOperator, UserRole, Transaction, AuditLog, TravelMode } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import { calculateInterest, formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('theme') === 'dark');
  const [showTour, setShowTour] = useState(false);

  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'LOGS' | 'USERS' | 'SIMULATE' | 'LIVE'>('MONITOR');

  // Theme Toggle Effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  // Check for tour completion on login
  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) {
        setShowTour(true);
      }
    }
  }, [currentUser]);

  // Borrower Live Tracking Logic
  useEffect(() => {
    if (!currentUser || currentUser.role !== 'BORROWER') return;

    const activeTravelLoan = allLoans.find(l => l.userId === currentUser.id && l.isTravelingToSite);
    if (!activeTravelLoan) return;

    const watchId = navigator.geolocation.watchPosition(
      (pos) => {
        apiService.updateLocation(currentUser.id, {
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          timestamp: new Date().toISOString()
        });
      },
      (err) => console.error("Tracking failed", err),
      { enableHighAccuracy: true }
    );

    return () => navigator.geolocation.clearWatch(watchId);
  }, [currentUser, allLoans]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const upcomingDues = useMemo(() => {
    const now = new Date();
    return allLoans.filter(l => {
      if (l.status !== 'DISBURSED') return false;
      const dueDate = new Date(l.dueDate);
      const diffMs = dueDate.getTime() - now.getTime();
      const diffHrs = diffMs / (1000 * 60 * 60);
      return diffHrs > 0 && diffHrs <= 24;
    });
  }, [allLoans]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Data sync failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleManualDisbursementConfirm = async (loanId: string) => {
    setIsProcessing(true);
    try {
      await apiService.disburseLoan(loanId);
      await refreshData();
    } catch (e) {
      console.error("Manual disbursement confirmation failed", e);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setIsLoggingIn(true);
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
    const response = await apiService.authenticate(email);
    if (response.status !== 200) {
      setLoginError(response.error || "Access Denied.");
      setIsLoggingIn(false);
      return;
    }
    let role: UserRole = 'BORROWER';
    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    if (adminEmails.includes(email)) role = 'ADMIN';
    const user: User = {
      ...(response.user || {
        id: Math.random().toString(36).substr(2, 9),
        name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
        email: email,
        nrc: (formData.get('nrc') as string) || 'N/A',
        phone: (formData.get('phone') as string) || 'N/A',
        address: (formData.get('address') as string) || 'N/A',
        operator: 'Airtel',
        role: role,
        joinedAt: new Date().toISOString(),
        walletBalance: 0
      })
    };
    const sync = await apiService.syncUser(user);
    setCurrentUser(sync.user);
    localStorage.setItem('kwachatime_user', JSON.stringify(sync.user));
    setIsLoggingIn(false);
  };

  const handleStartTravel = async (loanId: string, mode: TravelMode) => {
    setIsProcessing(true);
    // PTA Calculation (Simulated logic using Gemini-backed service ideally, but hardcoded ETA for now)
    const eta = mode === 'walking' ? '35 mins' : mode === 'cycling' ? '15 mins' : '10 mins';
    await apiService.setTravelStatus(loanId, true, mode, eta);
    refreshData();
    setIsProcessing(false);
  };

  const completeTour = () => {
    if (currentUser) {
      localStorage.setItem(`kwachatime_tour_done_${currentUser.id}`, 'true');
      setShowTour(false);
    }
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[70vh] p-4 bg-gray-50 dark:bg-slate-900 transition-colors">
          <div className="w-full max-w-md animate-fadeIn">
            <div className="bg-white dark:bg-slate-800 p-8 md:p-12 rounded-[3rem] shadow-2xl border border-gray-100 dark:border-slate-700 relative overflow-hidden">
              <div className="absolute top-0 left-0 p-8">
                <button onClick={() => setIsDarkMode(!isDarkMode)} className="w-10 h-10 bg-gray-100 dark:bg-slate-700 rounded-xl flex items-center justify-center text-slate-600 dark:text-slate-300">
                  <i className={`fas ${isDarkMode ? 'fa-sun' : 'fa-moon'}`}></i>
                </button>
              </div>
              <div className="text-center mb-10 mt-6">
                 <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-3xl flex items-center justify-center mx-auto mb-4 shadow-sm">
                    <i className="fas fa-landmark text-2xl"></i>
                 </div>
                 <h2 className="text-2xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Kwacha Gate</h2>
                 <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Identify Yourself</p>
              </div>
              <form onSubmit={handleInitialLogin} className="space-y-4">
                <input name="email" type="email" placeholder="Email Address" required className="w-full bg-gray-50 dark:bg-slate-900 dark:text-white p-5 rounded-2xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-medium" />
                <input name="name" placeholder="Full Legal Name" className="w-full bg-gray-50 dark:bg-slate-900 dark:text-white p-5 rounded-2xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-medium" />
                {loginError && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{loginError}</p>}
                <button className="w-full py-6 bg-emerald-800 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-emerald-950 shadow-xl transition-all">Authenticate</button>
              </form>
            </div>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}>
      <CurrencyConverter />

      {showTour && <OnboardingTour role={currentUser.role} onComplete={completeTour} />}

      {isProcessing && (
        <div className="fixed inset-0 z-[5000] flex items-center justify-center bg-emerald-950/90 backdrop-blur-xl">
           <div className="text-center">
              <div className="w-16 h-16 border-4 border-emerald-500 border-t-white rounded-full animate-spin mx-auto mb-4"></div>
              <p className="text-white font-black uppercase text-xs tracking-[0.2em]">Updating Ledger...</p>
           </div>
        </div>
      )}

      {isAdmin ? (
        <div className="space-y-6 md:space-y-10 animate-fadeIn text-slate-900 dark:text-white">
          <div className="bg-slate-900 dark:bg-emerald-950/30 text-white p-6 md:p-10 rounded-[3rem] shadow-2xl relative overflow-hidden border-4 border-slate-800 dark:border-emerald-900">
            <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
              <div className="text-center md:text-left">
                <p className="text-emerald-400 text-[10px] font-black uppercase tracking-[0.4em] mb-2">Management Command Center</p>
                <h2 className="text-3xl md:text-5xl font-black uppercase tracking-tighter">Ops Terminal</h2>
              </div>
              <div className="flex gap-4 w-full md:w-auto overflow-x-auto no-scrollbar pb-2 md:pb-0">
                <div className="px-6 py-4 bg-white/5 rounded-3xl border border-white/10 shrink-0 relative">
                  <p className="text-[8px] font-black uppercase text-emerald-400 mb-1">Vault Liquidity</p>
                  <p className="text-xl font-black">{formatCurrency(vaultBalance)}</p>
                </div>
                <div className="px-6 py-4 bg-white/5 rounded-3xl border border-white/10 shrink-0">
                  <p className="text-[8px] font-black uppercase text-orange-400 mb-1">Portfolio Exposure</p>
                  <p className="text-xl font-black">{formatCurrency(allLoans.filter(l => l.status === 'DISBURSED').reduce((acc, curr) => acc + curr.principal, 0))}</p>
                </div>
              </div>
            </div>
          </div>

          <div className="flex p-2 bg-gray-100 dark:bg-slate-800 rounded-[2rem] gap-1 overflow-x-auto no-scrollbar">
            {[
              { id: 'MONITOR', icon: 'fa-gauge-high', label: 'Monitor' },
              { id: 'PENDING', icon: 'fa-hourglass-half', label: 'Approvals' },
              { id: 'LIVE', icon: 'fa-satellite-dish', label: 'Live Tracking' },
              { id: 'USERS', icon: 'fa-user-group', label: 'Ledger' }
            ].map(tab => (
              <button key={tab.id} onClick={() => setActiveAdminTab(tab.id as any)} className={`flex-1 flex items-center justify-center gap-3 px-6 py-4 rounded-2xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white shadow-lg scale-105' : 'text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-700'}`}>
                <i className={`fas ${tab.icon} text-sm`}></i>
                <span className="hidden sm:inline">{tab.label}</span>
              </button>
            ))}
          </div>

          <div className="min-h-[60vh]">
            {activeAdminTab === 'LIVE' && (
              <div className="bg-white dark:bg-slate-800 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-700">
                <div className="flex justify-between items-center mb-8">
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tighter">Incoming Borrowers</h3>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Real-time GPS Tracking</p>
                  </div>
                  <div className="w-12 h-12 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-2xl flex items-center justify-center animate-pulse"><i className="fas fa-tower-broadcast"></i></div>
                </div>

                <div className="space-y-6">
                  {allLoans.filter(l => l.isTravelingToSite).map(loan => {
                    const user = allUsers.find(u => u.id === loan.userId);
                    return (
                      <div key={loan.id} className="p-6 bg-gray-50 dark:bg-slate-900 rounded-[2.5rem] border-2 border-emerald-500/20 flex flex-col md:flex-row items-center justify-between gap-6">
                        <div className="flex items-center gap-4 w-full">
                          <div className="w-16 h-16 bg-emerald-800 text-white rounded-2xl flex items-center justify-center text-2xl font-black">{loan.userName[0]}</div>
                          <div>
                            <h4 className="font-black text-lg">{loan.userName}</h4>
                            <div className="flex gap-3 text-[10px] font-black uppercase text-emerald-600">
                              <span><i className={`fas ${loan.travelMode === 'driving' ? 'fa-car' : loan.travelMode === 'cycling' ? 'fa-bicycle' : 'fa-person-walking'} mr-2`}></i>{loan.travelMode}</span>
                              <span className="text-orange-500"><i className="fas fa-clock mr-2"></i>ETA: {loan.estimatedArrival}</span>
                            </div>
                          </div>
                        </div>
                        <div className="w-full md:w-auto text-center md:text-right bg-emerald-500/10 p-4 rounded-2xl border border-emerald-500/20">
                          <p className="text-[9px] font-black text-emerald-600 uppercase mb-1">Live Coordinates</p>
                          <p className="text-[11px] font-mono text-slate-500">{user?.currentLocation ? `${user.currentLocation.lat.toFixed(5)}, ${user.currentLocation.lng.toFixed(5)}` : 'Awaiting Ping...'}</p>
                        </div>
                      </div>
                    );
                  })}
                  {allLoans.filter(l => l.isTravelingToSite).length === 0 && (
                    <div className="py-20 text-center opacity-30">
                       <i className="fas fa-satellite text-4xl mb-4"></i>
                       <p className="text-[10px] font-black uppercase">No active tracking sessions</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeAdminTab === 'MONITOR' && (
              <div className="bg-white dark:bg-slate-800 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-700">
                 <h3 className="text-xl font-black uppercase tracking-tighter mb-8">Active Portfolio</h3>
                 <div className="space-y-4">
                    {allLoans.filter(l => l.status === 'DISBURSED').map(loan => (
                      <div key={loan.id} className="p-6 bg-gray-50 dark:bg-slate-900 rounded-[2.5rem] flex items-center justify-between border border-transparent hover:border-emerald-500/50 transition-all">
                        <div className="flex items-center gap-4">
                           <div className="w-12 h-12 bg-slate-900 text-white rounded-xl flex items-center justify-center font-black">{loan.userName[0]}</div>
                           <div>
                              <p className="font-black">{loan.userName}</p>
                              <p className="text-[9px] font-black uppercase text-gray-400">Due: {new Date(loan.dueDate).toLocaleDateString()}</p>
                           </div>
                        </div>
                        <p className="text-xl font-black">{formatCurrency(loan.principal)}</p>
                      </div>
                    ))}
                 </div>
              </div>
            )}

            {activeAdminTab === 'PENDING' && (
              <div className="space-y-4">
                {allLoans.filter(l => l.status === 'PENDING').map(loan => (
                  <div key={loan.id} className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-xl border border-gray-100 dark:border-slate-700 flex flex-col md:flex-row items-center justify-between gap-8">
                    <div className="flex items-center gap-6 w-full">
                      <div className="w-16 h-16 bg-gray-100 dark:bg-slate-900 rounded-2xl flex items-center justify-center font-black text-2xl">
                        {loan.userName[0]}
                      </div>
                      <div>
                        <h4 className="text-xl font-black">{loan.userName}</h4>
                        <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">{loan.purpose}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-6 w-full md:w-auto justify-between md:justify-end">
                      <p className="text-2xl font-black text-emerald-800 dark:text-emerald-400">{formatCurrency(loan.principal)}</p>
                      <button onClick={() => handleManualDisbursementConfirm(loan.id)} className="px-8 py-4 bg-emerald-800 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg">Confirm</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      ) : (
        /* Borrower View */
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-12 animate-fadeIn text-slate-900 dark:text-white transition-colors">
           <div className="lg:col-span-1 space-y-8 order-2 lg:order-1">
              <Roadmap />
              <OfficeLocator />
           </div>

           <div className="lg:col-span-2 space-y-8 order-1 lg:order-2">
              <div className="bg-emerald-950 text-white p-8 md:p-12 rounded-[3.5rem] shadow-2xl border-4 border-emerald-900 relative overflow-hidden group">
                <div className="relative z-10">
                   <p className="text-[10px] font-black uppercase text-emerald-500 mb-2 tracking-[0.3em]">Current Available Capital</p>
                   <p className="text-4xl md:text-6xl font-black mb-10 tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                   <div className="grid grid-cols-2 gap-4">
                      <button className="bg-white/10 p-5 rounded-3xl text-[9px] font-black uppercase flex flex-col items-center gap-3"><i className="fas fa-plus-circle text-xl"></i> Fund Ledger</button>
                      <button className="bg-emerald-600 p-5 rounded-3xl text-[9px] font-black uppercase shadow-xl flex flex-col items-center gap-3"><i className="fas fa-paper-plane text-xl"></i> Payout MoMo</button>
                   </div>
                </div>
              </div>

              {allLoans.filter(l => l.status === 'PENDING').length > 0 && (
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] border-2 border-emerald-500/20 shadow-xl">
                  <div className="flex justify-between items-center mb-6">
                    <div>
                      <h4 className="text-lg font-black uppercase tracking-tighter">Approved & Ready</h4>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Select transport to calculate PTA</p>
                    </div>
                    <div className="w-10 h-10 bg-emerald-50 text-white rounded-xl flex items-center justify-center"><i className="fas fa-map-location-dot"></i></div>
                  </div>

                  <div className="grid grid-cols-3 gap-4 mb-8">
                    {(['walking', 'cycling', 'driving'] as TravelMode[]).map(m => (
                      <button key={m} onClick={() => handleStartTravel(allLoans.find(l => l.status === 'PENDING')!.id, m)} className="bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl flex flex-col items-center gap-3 border-2 border-transparent hover:border-emerald-500 transition-all active:scale-95">
                        <i className={`fas ${m === 'driving' ? 'fa-car' : m === 'cycling' ? 'fa-bicycle' : 'fa-person-walking'} text-2xl text-emerald-600`}></i>
                        <span className="text-[9px] font-black uppercase">{m}</span>
                      </button>
                    ))}
                  </div>

                  {allLoans.some(l => l.isTravelingToSite) && (
                    <div className="bg-emerald-800 text-white p-6 rounded-3xl flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center animate-pulse"><i className="fas fa-satellite-dish"></i></div>
                        <div>
                          <p className="text-[10px] font-black uppercase opacity-60">Traveling Mode Active</p>
                          <p className="text-sm font-bold">ETA: {allLoans.find(l => l.isTravelingToSite)?.estimatedArrival}</p>
                        </div>
                      </div>
                      <button onClick={() => apiService.setTravelStatus(allLoans.find(l => l.isTravelingToSite)!.id, false)} className="text-[10px] font-black uppercase bg-white/10 px-4 py-2 rounded-xl">Cancel</button>
                    </div>
                  )}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <LoanForm onSubmit={async (data) => {
                    const loan: Loan = {
                       id: `REQ-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
                       userId: currentUser.id,
                       userName: currentUser.name,
                       principal: data.principal,
                       purpose: data.purpose,
                       status: 'PENDING',
                       createdAt: new Date().toISOString(),
                       dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
                       collateralType: data.collateralType,
                       collateralValue: data.collateralValue
                    };
                    await apiService.submitLoanRequest(loan);
                    refreshData();
                  }} isLoading={false} />

                  <div className="bg-white dark:bg-slate-800 rounded-[3rem] p-8 shadow-xl border border-gray-100 dark:border-slate-700">
                    <h3 className="text-[10px] font-black uppercase text-gray-400 mb-8 tracking-widest">Your Ledger</h3>
                    <div className="space-y-4">
                       {allLoans.map(l => (
                         <div key={l.id} className="p-6 bg-gray-50 dark:bg-slate-900 rounded-[2.5rem] border border-gray-100 dark:border-slate-700">
                            <p className="text-2xl font-black">{formatCurrency(l.principal)}</p>
                            <span className={`px-2 py-0.5 rounded text-[7px] font-black uppercase ${l.status === 'DISBURSED' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>{l.status}</span>
                         </div>
                       ))}
                    </div>
                  </div>
              </div>
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

export type MobileOperator = 'Airtel' | 'MTN' | 'Zamtel';
export type UserRole = 'BORROWER' | 'ADMIN' | 'DEVELOPER';
export type CollateralType = 'LAPTOP' | 'PHONE' | 'CAR' | 'APPLIANCE' | 'NONE';
export type TravelMode = 'walking' | 'cycling' | 'driving';
export type ThemeMode = 'light' | 'dark' | 'system';

export interface Location {
  lat: number;
  lng: number;
  timestamp: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  nrc: string;
  phone: string;
  address: string;
  operator: MobileOperator;
  role: UserRole;
  joinedAt: string;
  walletBalance?: number;
  trustScore?: number; // 0-100
  currentLocation?: Location;
}

export interface Transaction {
  id: string;
  loanId?: string;
  userId?: string;
  userName?: string;
  amount: number;
  type: 'DISBURSEMENT' | 'REPAYMENT' | 'FEE' | 'WALLET_WITHDRAW' | 'WALLET_DEPOSIT';
  timestamp: string;
  status: 'SUCCESS' | 'FAILED' | 'PENDING' | 'CONFIRMED_BY_MANAGEMENT';
  operator?: MobileOperator;
}

export interface AuditLog {
  id: string;
  userId: string;
  userName: string;
  action: string;
  category: 'SECURITY' | 'FINANCE' | 'SYSTEM' | 'IDENTITY';
  details: string;
  timestamp: string;
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  deviceInfo?: string;
}

export interface AppNotification {
  id: string;
  userId: string;
  title: string;
  message: string;
  type: 'REMINDER' | 'PROMO' | 'SYSTEM';
  timestamp: string;
  isRead: boolean;
}

export interface Loan {
  id: string;
  userId: string;
  userName: string;
  principal: number;
  purpose: string;
  status: 'PENDING' | 'APPROVED' | 'DISBURSED' | 'REJECTED' | 'REPAID' | 'AWAITING_COLLATERAL';
  createdAt: string;
  dueDate: string;
  disbursedAt?: string;
  borrowerPhoto?: string;
  transactionId?: string;
  collateralType?: CollateralType;
  collateralValue?: number;
  riskScore?: number;
  riskRationale?: string;
  isTravelingToSite?: boolean;
  travelMode?: TravelMode;
  estimatedArrival?: string;
}

export interface InterestBreakdown {
  principal: number;
  baseInterest: number;
  dailyInterest: number;
  lateDelayFee: number;
  monthlyPenalty: number;
  totalDue: number;
  daysElapsed: number;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, TravelMode, AuditLog, Transaction } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showTour, setShowTour] = useState(false);

  // Login Sequence States: 'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'
  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');

  // Theme State
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');

  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'LOGS' | 'USERS' | 'SIMULATE' | 'LIVE'>('MONITOR');

  // Theme Management
  useEffect(() => {
    const root = document.documentElement;
    const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;

    if (effectiveTheme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('theme-mode', themeMode);
  }, [themeMode]);

  // Handle System Theme Changes
  useEffect(() => {
    if (themeMode !== 'system') return;
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handleChange = () => {
      if (mediaQuery.matches) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    };
    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, [themeMode]);

  // Check for tour completion
  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) setShowTour(true);
    }
  }, [currentUser]);

  // Borrower Live Tracking
  useEffect(() => {
    if (!currentUser || currentUser.role !== 'BORROWER') return;
    const activeTravelLoan = allLoans.find(l => l.userId === currentUser.id && l.isTravelingToSite);
    if (!activeTravelLoan) return;

    const watchId = navigator.geolocation.watchPosition(
      (pos) => {
        apiService.updateLocation(currentUser.id, {
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          timestamp: new Date().toISOString()
        });
      },
      (err) => console.error("Tracking failed", err),
      { enableHighAccuracy: true }
    );
    return () => navigator.geolocation.clearWatch(watchId);
  }, [currentUser, allLoans]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Data sync failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');

    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
    const response = await apiService.authenticate(email);

    if (response.status !== 200) {
      setLoginError(response.error || "Access Denied.");
      setLoginSequence('IDLE');
      return;
    }

    let role: UserRole = 'BORROWER';
    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    if (adminEmails.includes(email)) role = 'ADMIN';

    const userData: User = {
      ...(response.user || {
        id: Math.random().toString(36).substr(2, 9),
        name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
        email: email,
        nrc: 'N/A',
        phone: 'N/A',
        address: 'N/A',
        operator: 'Airtel',
        role: role,
        joinedAt: new Date().toISOString(),
        walletBalance: 0
      })
    };

    const sync = await apiService.syncUser(userData);

    // --- Start 5 Second Clock/Currency Animation ---
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 2500));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 2500));

    setCurrentUser(sync.user);
    localStorage.setItem('kwachatime_user', JSON.stringify(sync.user));
    setLoginSequence('IDLE');
  };

  const handleStartTravel = async (loanId: string, mode: TravelMode) => {
    setIsProcessing(true);
    const eta = mode === 'walking' ? '35 mins' : mode === 'cycling' ? '15 mins' : '10 mins';
    await apiService.setTravelStatus(loanId, true, mode, eta);
    refreshData();
    setIsProcessing(false);
  };

  const handleManualDisbursementConfirm = async (loanId: string) => {
    setIsProcessing(true);
    try {
      await apiService.disburseLoan(loanId);
      await refreshData();
    } catch (e) {
      console.error("Disbursement failed", e);
    } finally {
      setIsProcessing(false);
    }
  };

  const toggleTheme = () => {
    setThemeMode(prev => {
      if (prev === 'light') return 'dark';
      if (prev === 'dark') return 'system';
      return 'light';
    });
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[70vh] p-4 bg-gray-50 dark:bg-slate-950 transition-colors">
