            )}
            {/* Other tabs omitted for brevity, but logic remains same */}
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-12 text-slate-900 dark:text-white">
           <div className="lg:col-span-1 space-y-8">
              <Roadmap />
