              <div className="bg-emerald-950 text-white p-8 md:p-12 rounded-[3.5rem] shadow-2xl border-4 border-emerald-900">
                 <p className="text-[10px] font-black uppercase text-emerald-500 mb-2 tracking-[0.3em]">Capital Ledger Balance</p>
                 <p className="text-4xl md:text-6xl font-black mb-10 tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
