                <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border-2 border-emerald-500/20">
                  <h4 className="text-lg font-black uppercase mb-6">Dispatch Portal</h4>
                  <div className="grid grid-cols-3 gap-4">
                    {(['walking', 'cycling', 'driving'] as TravelMode[]).map(m => (
                      <button key={m} onClick={() => handleStartTravel(allLoans.find(l => l.status === 'PENDING')!.id, m)} className="bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl flex flex-col items-center gap-3 border-2 border-transparent hover:border-emerald-500 transition-all">
                        <i className={`fas ${m === 'driving' ? 'fa-car' : m === 'cycling' ? 'fa-bicycle' : 'fa-person-walking'} text-2xl text-emerald-600`}></i>
