import React, { useState, useRef, useMemo, useEffect } from 'react';
import { CollateralType } from '../types';
import { analyzeSafetyPhoto } from '../services/geminiService';
import { formatCurrency } from '../utils/loanCalculator';

interface LoanFormProps {
  onSubmit: (loanData: { 
    principal: number; 
    purpose: string; 
    collateral: File | null;
    collateralType: CollateralType;
    collateralValue: number;
  }) => void;
  isLoading: boolean;
}

const LTV_RATIO = 0.6; // 60% Loan-to-Value

const COLLATERAL_DATA: Record<CollateralType, { label: string; icon: string; minVal: number; maxVal: number }> = {
  PHONE: { label: 'Phone', icon: 'fa-mobile-screen', minVal: 1500, maxVal: 15000 },
  LAPTOP: { label: 'PC / Laptop', icon: 'fa-laptop', minVal: 4000, maxVal: 35000 },
  CAR: { label: 'Vehicle', icon: 'fa-car', minVal: 50000, maxVal: 900000 },
  APPLIANCE: { label: 'Appliance', icon: 'fa-plug', minVal: 2000, maxVal: 20000 },
  NONE: { label: 'None', icon: 'fa-ban', minVal: 0, maxVal: 0 }
};

const LoanForm: React.FC<LoanFormProps> = ({ onSubmit, isLoading }) => {
  const [amount, setAmount] = useState<string>('');
  const [purpose, setPurpose] = useState<string>('');
  const [photo, setPhoto] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [selectedCollateral, setSelectedCollateral] = useState<CollateralType>('NONE');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Estimation Logic
  const estimation = useMemo(() => {
    if (selectedCollateral === 'NONE') return { value: 0, maxLoan: 0 };
    const data = COLLATERAL_DATA[selectedCollateral];
    const avgValue = (data.minVal + data.maxVal) / 2;
    return {
      value: avgValue,
      maxLoan: avgValue * LTV_RATIO
    };
  }, [selectedCollateral]);

  const isOverLimit = useMemo(() => {
    const requested = parseFloat(amount) || 0;
    return requested > estimation.maxLoan && selectedCollateral !== 'NONE';
  }, [amount, estimation]);

  useEffect(() => {
    const draft = localStorage.getItem('kwachatime_loan_draft');
    if (draft) {
      try {
        const parsed = JSON.parse(draft);
        if (parsed.amount) setAmount(parsed.amount);
        if (parsed.purpose) setPurpose(parsed.purpose);
        if (parsed.selectedCollateral) setSelectedCollateral(parsed.selectedCollateral);
      } catch (e) {}
    }
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsAnalyzing(true);
      setError(null);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        const result = await analyzeSafetyPhoto(base64);
        if (!result.isValid) {
          setError(result.reason);
          setPhoto(null);
        } else {
          setPhoto(file);
        }
        setIsAnalyzing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isOverLimit) {
      setError(`Amount exceeds your ${COLLATERAL_DATA[selectedCollateral].label} credit limit of ${formatCurrency(estimation.maxLoan)}`);
      return;
    }
    if (!amount || selectedCollateral === 'NONE' || !photo) {
      setError("Please complete all steps including the identity selfie.");
      return;
    }
    onSubmit({ 
      principal: parseFloat(amount), 
      purpose, 
      collateral: photo,
      collateralType: selectedCollateral,
      collateralValue: estimation.value
    });
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl p-8 border border-gray-100 dark:border-slate-700 max-w-md mx-auto animate-fadeIn transition-colors">
      <h2 className="text-2xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter mb-8">Fast Kwacha Application</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400 dark:text-gray-500">Step 1: Choose Collateral</label>
          <div className="grid grid-cols-2 gap-3">
            {(Object.keys(COLLATERAL_DATA) as CollateralType[]).filter(k => k !== 'NONE').map(key => (
              <button
                key={key}
                type="button"
                onClick={() => {
                  setSelectedCollateral(key);
                  setError(null);
                }}
                className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all ${selectedCollateral === key ? 'bg-emerald-800 border-emerald-800 text-white shadow-lg' : 'bg-gray-50 dark:bg-slate-900 border-gray-100 dark:border-slate-700 text-gray-400 dark:text-gray-500'}`}
              >
                <i className={`fas ${COLLATERAL_DATA[key].icon} text-xl mb-2`}></i>
                <span className="text-[10px] font-black uppercase">{COLLATERAL_DATA[key].label}</span>
              </button>
            ))}
          </div>

          {selectedCollateral !== 'NONE' && (
            <div className="p-4 bg-emerald-50 dark:bg-emerald-900/20 rounded-2xl border border-emerald-100 dark:border-emerald-800 animate-slideUp">
              <p className="text-[9px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mb-1">Estimated Credit Limit</p>
              <p className="text-xl font-black text-emerald-950 dark:text-white">{formatCurrency(estimation.maxLoan)}</p>
              <p className="text-[8px] font-bold text-gray-400 mt-1 uppercase">Based on average market value for {COLLATERAL_DATA[selectedCollateral].label}s in Zambia</p>
            </div>
          )}
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400 dark:text-gray-500">Step 2: Loan Details</label>
          <div className="space-y-3">
            <div className="relative">
              <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-emerald-800 dark:text-emerald-400">K</span>
              <input 
                type="number" 
                value={amount} 
                onChange={(e) => {
                  setAmount(e.target.value);
                  setError(null);
                }} 
                className={`w-full bg-gray-50 dark:bg-slate-900 dark:text-white border-2 p-5 pl-10 rounded-2xl text-xl font-black outline-none transition-all ${isOverLimit ? 'border-red-500 text-red-500 ring-2 ring-red-500/20' : 'border-gray-100 dark:border-slate-700 focus:border-emerald-500'}`} 
                placeholder="0.00" 
              />
            </div>
            {isOverLimit && (
              <p className="text-[9px] font-black text-red-500 uppercase flex items-center gap-2 animate-shake">
                <i className="fas fa-triangle-exclamation"></i> Requested amount exceeds limit
              </p>
            )}
            <input 
              type="text" 
              value={purpose} 
              onChange={(e) => setPurpose(e.target.value)} 
              className="w-full bg-gray-50 dark:bg-slate-900 dark:text-white border-2 border-gray-100 dark:border-slate-700 p-5 rounded-2xl text-xs font-bold outline-none focus:border-emerald-500" 
              placeholder="What is the loan for?" 
            />
          </div>
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400 dark:text-gray-500">Step 3: Identity Verification</label>
          <div 
            onClick={() => fileInputRef.current?.click()} 
            className="group relative h-32 rounded-3xl border-2 border-dashed border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-900 flex flex-col items-center justify-center cursor-pointer hover:border-emerald-500 transition-all overflow-hidden"
          >
            {previewUrl ? (
              <>
                <img src={previewUrl} className="w-full h-full object-cover" alt="Selfie" />
                <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                  <span className="text-[10px] font-black text-white uppercase">Change Photo</span>
                </div>
              </>
            ) : (
              <>
                <i className="fas fa-camera text-2xl text-gray-300 group-hover:text-emerald-500 mb-2"></i>
                <span className="text-[9px] font-black text-gray-400 uppercase">Snap Selfie</span>
              </>
            )}
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
          </div>
        </div>

        {error && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{error}</p>}

        <button 
          type="submit" 
          disabled={isLoading || isAnalyzing || isOverLimit} 
          className="w-full bg-emerald-800 text-white py-6 rounded-[1.8rem] font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 disabled:opacity-50 disabled:grayscale"
        >
          {isAnalyzing ? "Analyzing Photo..." : isLoading ? "Processing..." : "Submit Secure Request"}
        </button>
      </form>
    </div>
  );
};

export default LoanForm;

