import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showTour, setShowTour] = useState(false);

  // Login Sequence States: 'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'
  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');

  // Theme State
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');

  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'LOGS' | 'USERS' | 'SIMULATE' | 'LIVE'>('MONITOR');

  // Theme Management
  useEffect(() => {
    const root = document.documentElement;
    const updateTheme = () => {
      const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;

      if (effectiveTheme === 'dark') {
        root.classList.add('dark');
      } else {
        root.classList.remove('dark');
      }
    };

    updateTheme();
    localStorage.setItem('theme-mode', themeMode);

    if (themeMode === 'system') {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      mediaQuery.addEventListener('change', updateTheme);
      return () => mediaQuery.removeEventListener('change', updateTheme);
    }
  }, [themeMode]);

  // Check for tour completion
  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) setShowTour(true);
    }
  }, [currentUser]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Data sync failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');

    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
    const response = await apiService.authenticate(email);

    if (response.status !== 200) {
      setLoginError(response.error || "Access Denied.");
      setLoginSequence('IDLE');
      return;
    }

    let role: UserRole = 'BORROWER';
    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    if (adminEmails.includes(email)) role = 'ADMIN';

    const userData: User = {
      ...(response.user || {
        id: Math.random().toString(36).substr(2, 9),
        name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
        email: email,
        nrc: 'N/A',
        phone: 'N/A',
        address: 'N/A',
        operator: 'Airtel',
        role: role,
        joinedAt: new Date().toISOString(),
        walletBalance: 0
      })
    };

    const sync = await apiService.syncUser(userData);

    // Enforce 5 Second clock and currency sequence
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 2500));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 2500));

    setCurrentUser(sync.user);
    localStorage.setItem('kwachatime_user', JSON.stringify(sync.user));
    setLoginSequence('IDLE');
  };

  const handleManualDisbursementConfirm = async (loanId: string) => {
    setIsProcessing(true);
    try {
      await apiService.disburseLoan(loanId);
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  const toggleTheme = () => {
    setThemeMode(prev => {
      if (prev === 'light') return 'dark';
      if (prev === 'dark') return 'system';
      return 'light';
    });
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[80vh] p-4 transition-colors">
          <div className="w-full max-w-md">
            <div className="bg-white dark:bg-slate-900 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-800 relative overflow-hidden">
              <div className="absolute top-0 left-0 p-8">
                <button 
                  onClick={toggleTheme} 
                  className="w-12 h-12 bg-gray-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-600 dark:text-slate-300 transition-all active:scale-90"
                >
                  <i className={`fas ${themeMode === 'light' ? 'fa-sun' : themeMode === 'dark' ? 'fa-moon' : 'fa-circle-half-stroke'}`}></i>
                </button>
              </div>

              <div className="text-center mb-10 mt-8">
                 <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm">
                    <i className="fas fa-landmark text-3xl"></i>
                 </div>
                 <h2 className="text-3xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Kwacha Gate</h2>
                 <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-[0.3em] mt-2">Verified Lending Gateway</p>
              </div>

              {loginSequence !== 'IDLE' ? (
                <div className="flex flex-col items-center justify-center py-12 space-y-8 animate-fadeIn">
                  <div className="relative w-28 h-28 flex items-center justify-center">
                    <div className="absolute inset-0 border-[6px] border-emerald-500/10 border-t-emerald-500 rounded-full animate-spin"></div>
                    <div className="text-5xl text-emerald-600 dark:text-emerald-400 animate-pulse">
                      {loginSequence === 'AUTHENTICATING' && <i className="fas fa-fingerprint"></i>}
                      {loginSequence === 'CLOCK' && <i className="fas fa-clock"></i>}
                      {loginSequence === 'CURRENCY' && <i className="fas fa-sack-dollar"></i>}
                    </div>
                  </div>
                  <div className="text-center">
                    <p className="text-xs font-black uppercase tracking-[0.4em] text-emerald-800 dark:text-emerald-400">
                      {loginSequence === 'AUTHENTICATING' && "Verifying Bio-ID"}
                      {loginSequence === 'CLOCK' && "Calculating Market PTA"}
                      {loginSequence === 'CURRENCY' && "Allocating Liquid Capital"}
                    </p>
                    <p className="text-[9px] font-bold text-gray-400 dark:text-gray-600 uppercase tracking-widest mt-3">DO NOT REFRESH SESSION</p>
                  </div>
                </div>
              ) : (
                <form onSubmit={handleInitialLogin} className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Email Identity</label>
                    <input name="email" type="email" placeholder="management@kwachatime.com" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Full Legal Name</label>
                    <input name="name" placeholder="John Doe" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  {loginError && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{loginError}</p>}
                  <button className="w-full py-6 mt-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-emerald-950 shadow-2xl transition-all active:scale-95">Open Secure Vault</button>
                </form>
              )}
            </div>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={toggleTheme}>
      <CurrencyConverter />
      {showTour && <OnboardingTour role={currentUser.role} onComplete={() => {
        localStorage.setItem(`kwachatime_tour_done_${currentUser.id}`, 'true');
        setShowTour(false);
      }} />}

      {isAdmin ? (
        <div className="space-y-10 animate-fadeIn text-slate-900 dark:text-white">
          <div className="bg-slate-900 dark:bg-emerald-950/40 text-white p-10 rounded-[4rem] shadow-2xl relative overflow-hidden border-4 border-slate-800 dark:border-emerald-900/50">
            <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-10">
              <div className="text-center md:text-left">
                <p className="text-emerald-400 text-[11px] font-black uppercase tracking-[0.5em] mb-3">Management Control Console</p>
                <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter">Terminal V2</h2>
              </div>
              <div className="flex gap-6">
                <div className="px-8 py-5 bg-white/5 rounded-[2rem] border border-white/10 text-center">
                  <p className="text-[9px] font-black uppercase text-emerald-400 mb-1">Vault Liquidity</p>
                  <p className="text-2xl font-black">{formatCurrency(vaultBalance)}</p>
                </div>
                <div className="px-8 py-5 bg-white/5 rounded-[2rem] border border-white/10 text-center">
                  <p className="text-[9px] font-black uppercase text-orange-400 mb-1">Active Portfolio</p>
                  <p className="text-2xl font-black">{formatCurrency(allLoans.filter(l => l.status === 'DISBURSED').reduce((acc, curr) => acc + curr.principal, 0))}</p>
                </div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <div className="lg:col-span-1 space-y-4">
              {[
                { id: 'MONITOR', icon: 'fa-chart-pie', label: 'Monitor' },
                { id: 'PENDING', icon: 'fa-shield-halved', label: 'Security Approval' },
                { id: 'USERS', icon: 'fa-users-line', label: 'User Ledger' }
              ].map(tab => (
                <button 
                  key={tab.id} 
                  onClick={() => setActiveAdminTab(tab.id as any)}
                  className={`w-full flex items-center gap-4 p-6 rounded-3xl text-[11px] font-black uppercase transition-all ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white shadow-xl' : 'bg-white dark:bg-slate-900 text-gray-400 dark:text-gray-500 border border-transparent'}`}
                >
                  <i className={`fas ${tab.icon} text-lg`}></i>
                  {tab.label}
                </button>
              ))}
            </div>

            <div className="lg:col-span-3 min-h-[60vh]">
              {activeAdminTab === 'PENDING' && (
                <div className="space-y-4">
                  {allLoans.filter(l => l.status === 'PENDING').map(loan => (
                    <div key={loan.id} className="bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800 flex justify-between items-center group hover:border-emerald-500 transition-colors">
                      <div className="flex items-center gap-6">
                        <div className="w-16 h-16 bg-gray-100 dark:bg-slate-800 rounded-3xl flex items-center justify-center font-black text-2xl text-emerald-800 dark:text-emerald-400">
                          {loan.userName[0]}
                        </div>
                        <div>
                          <h4 className="text-xl font-black">{loan.userName}</h4>
                          <p className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">{loan.purpose}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-8">
                        <div className="text-right">
                          <p className="text-2xl font-black">{formatCurrency(loan.principal)}</p>
                          <p className="text-[9px] font-black uppercase text-gray-400">{loan.collateralType}</p>
                        </div>
                        <button onClick={() => handleManualDisbursementConfirm(loan.id)} className="px-10 py-5 bg-emerald-800 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-emerald-950 transition-all">Approve Disbursement</button>
                      </div>
                    </div>
                  ))}
                  {allLoans.filter(l => l.status === 'PENDING').length === 0 && (
                    <div className="bg-white dark:bg-slate-900 p-20 rounded-[4rem] text-center opacity-30">
                       <i className="fas fa-check-double text-6xl mb-6"></i>
                       <p className="text-xs font-black uppercase tracking-widest">Queue is currently clear</p>
                    </div>
                  )}
                </div>
              )}
              {/* Other Tabs Logic stays same */}
            </div>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 text-slate-900 dark:text-white animate-fadeIn">
           <div className="lg:col-span-1 space-y-10">
              <Roadmap />
              <OfficeLocator />
           </div>
           <div className="lg:col-span-2 space-y-10">
              <div className="bg-emerald-950 text-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-900 relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-10 text-9xl text-white/5 pointer-events-none group-hover:scale-110 transition-transform duration-1000">
                    <i className="fas fa-wallet"></i>
                 </div>
                 <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-[0.4em]">Personal Capital Ledger</p>
                 <p className="text-5xl md:text-7xl font-black mb-12 tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 <div className="grid grid-cols-2 gap-4">
                    <button className="bg-white/10 p-6 rounded-3xl text-[10px] font-black uppercase flex flex-col items-center gap-3 hover:bg-white/20 transition-all border border-white/5"><i className="fas fa-plus-circle text-2xl"></i> Deposit MoMo</button>
                    <button className="bg-emerald-600 p-6 rounded-3xl text-[10px] font-black uppercase shadow-2xl flex flex-col items-center gap-3 hover:bg-emerald-500 transition-all active:scale-95"><i className="fas fa-paper-plane text-2xl"></i> Withdraw MoMo</button>
                 </div>
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `REQ-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: data.principal,
                   purpose: data.purpose,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
                   collateralType: data.collateralType,
                   collateralValue: data.collateralValue
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { ThemeMode } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  user?: any;
  onLogout?: () => void;
  themeMode?: ThemeMode;
  onToggleTheme?: () => void;
}

const Layout: React.FC<LayoutProps> = ({ children, user, onLogout, themeMode, onToggleTheme }) => {
  const [showNotifications, setShowNotifications] = useState(false);

  return (
    <div className={`min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 transition-colors duration-500`}>
      <header className="bg-emerald-800 dark:bg-emerald-950 text-white shadow-2xl sticky top-0 z-[100] border-b dark:border-emerald-900 transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 md:py-6 flex justify-between items-center">
          <div className="flex items-center space-x-3 cursor-pointer group" onClick={() => window.location.reload()}>
            <div className="w-10 h-10 md:w-12 md:h-12 bg-orange-500 rounded-2xl flex items-center justify-center font-black text-2xl md:text-3xl shadow-inner group-hover:rotate-12 transition-transform">K</div>
            <div>
              <h1 className="text-xl md:text-2xl font-black tracking-tight uppercase leading-none">KwachaTime</h1>
              <p className="text-[8px] font-black uppercase text-emerald-400 tracking-[0.3em] mt-1 hidden sm:block">Secure Micro-Lending</p>
            </div>
          </div>

          <div className="flex items-center space-x-3 md:space-x-6">
            <button 
              onClick={onToggleTheme}
              className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 transition-all text-sm w-12 h-12 flex items-center justify-center group relative shadow-inner"
            >
              <i className={`fas ${themeMode === 'light' ? 'fa-sun' : themeMode === 'dark' ? 'fa-moon' : 'fa-circle-half-stroke'} transition-transform group-active:scale-75`}></i>
              <span className="absolute top-full mt-3 right-0 bg-emerald-950 text-white text-[9px] font-black px-3 py-2 rounded-xl opacity-0 group-hover:opacity-100 whitespace-nowrap border border-emerald-800 shadow-2xl pointer-events-none transition-all">
                MODE: {themeMode?.toUpperCase()}
              </span>
            </button>

            {user && (
              <div className="flex items-center space-x-4">
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 transition-all relative w-12 h-12 flex items-center justify-center shadow-inner"
                >
                  <i className="fas fa-bell text-lg"></i>
                  <span className="absolute top-2 right-2 w-2 h-2 bg-orange-500 rounded-full"></span>
                </button>

                <div className="hidden lg:flex flex-col items-end">
                  <span className="text-[10px] text-emerald-400 font-black uppercase tracking-widest">Operator ID: {user.id.slice(0, 6)}</span>
                  <span className="text-sm font-black">{user.name}</span>
                </div>

                <button 
                  onClick={onLogout} 
                  className="bg-white/10 border border-white/10 px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-500/20 hover:border-red-500/30 transition-all shadow-lg active:scale-95"
                >
                  Logout
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-10 md:py-16">
        {children}
      </main>

      <footer className="bg-white dark:bg-slate-900 border-t dark:border-slate-800 py-12 text-center text-gray-400 dark:text-gray-600 transition-colors">
        <div className="mb-6 flex justify-center gap-8 text-xl">
          <i className="fab fa-facebook-messenger opacity-30 hover:opacity-100 transition-opacity cursor-pointer"></i>
          <i className="fab fa-whatsapp opacity-30 hover:opacity-100 transition-opacity cursor-pointer"></i>
          <i className="fas fa-headset opacity-30 hover:opacity-100 transition-opacity cursor-pointer"></i>
        </div>
        <p className="text-[10px] font-black uppercase tracking-widest">&copy; {new Date().getFullYear()} KwachaTime Micro-Lending. All Rights Reserved. Lusaka, Zambia.</p>
      </footer>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, TravelMode, AuditLog, Transaction } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showTour, setShowTour] = useState(false);

  // Login Sequence States: 'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'
  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');

  // Theme State
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');

  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'LOGS' | 'USERS' | 'SIMULATE' | 'LIVE'>('MONITOR');

  // Theme Management
  useEffect(() => {
    const root = document.documentElement;
    const updateTheme = () => {
      const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;

      if (effectiveTheme === 'dark') {
        root.classList.add('dark');
      } else {
        root.classList.remove('dark');
      }
    };

    updateTheme();
    localStorage.setItem('theme-mode', themeMode);

    if (themeMode === 'system') {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      mediaQuery.addEventListener('change', updateTheme);
      return () => mediaQuery.removeEventListener('change', updateTheme);
    }
  }, [themeMode]);

  // Check for tour completion
  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) setShowTour(true);
    }
  }, [currentUser]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Data sync failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');

    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
