                              <td className="py-4 font-black text-emerald-600">{formatCurrency(user.walletBalance || 0)}</td>
                              <td className="py-4"><span className="px-3 py-1 bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-400 rounded-full text-[9px] font-black uppercase">{user.role}</span></td>
                              <td className="py-4 font-mono text-gray-500">{user.nrc}</td>
                            </tr>
