                        </tbody>
                      </table>
                   </div>
                </div>
              )}

              {activeAdminTab === 'SIMULATE' && (
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                   <h3 className="text-xl font-black uppercase tracking-tighter mb-8">Loan Simulation Hub</h3>
                   <p className="text-xs text-gray-500 mb-10 leading-relaxed">Inject non-verified data into the ledger for testing interest accrual and risk engines. These loans are marked as DISBURSED immediately.</p>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                       <input 
                         type="text" 
                         placeholder="Mock Client Name" 
                         value={simName}
                         onChange={(e) => setSimName(e.target.value)}
                         className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold"
                       />
                       <input 
                         type="number" 
                         placeholder="Principal (ZMW)" 
                         value={simAmount}
                         onChange={(e) => setSimAmount(e.target.value)}
                         className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold"
                       />
                   </div>
                   <button 
                     onClick={handleRunSimulation}
                     className="w-full py-6 bg-emerald-800 text-white rounded-3xl font-black uppercase tracking-widest shadow-xl hover:bg-emerald-950 transition-all flex items-center justify-center gap-3"
                   >
                     <i className="fas fa-play-circle"></i> Inject Simulation Data
                   </button>
                </div>
              )}

              {activeAdminTab === 'LOGS' && (
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                   <h3 className="text-xl font-black uppercase tracking-tighter mb-8">System Audit Logs</h3>
                   <div className="space-y-4">
                      {auditLogs.map(log => (
                        <div key={log.id} className="p-5 bg-gray-50 dark:bg-slate-800 rounded-2xl flex items-start gap-4 border-l-4 border-emerald-500">
                           <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${log.severity === 'CRITICAL' ? 'bg-red-500' : 'bg-emerald-800'} text-white text-[10px]`}>
                              <i className="fas fa-shield-halved"></i>
                           </div>
                           <div>
                              <div className="flex items-center gap-3 mb-1">
                                 <p className="text-[10px] font-black uppercase tracking-widest">{log.action}</p>
                                 <span className="text-[8px] font-mono text-gray-400">{new Date(log.timestamp).toLocaleString()}</span>
                              </div>
                              <p className="text-[11px] font-medium text-gray-600 dark:text-gray-400">{log.details}</p>
                              <p className="text-[9px] font-black uppercase text-emerald-600 mt-2">Operator: {log.userName}</p>
                           </div>
                        </div>
                      ))}
