                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        /* Borrower View */
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 text-slate-900 dark:text-white animate-fadeIn">
           <div className="lg:col-span-1 space-y-10">
              <Roadmap />
              <OfficeLocator />
           </div>
           <div className="lg:col-span-2 space-y-10">
              <div className="bg-emerald-950 text-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-900 relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-10 text-9xl text-white/5 pointer-events-none group-hover:scale-110 transition-transform duration-1000">
                    <i className="fas fa-wallet"></i>
                 </div>
                 <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-[0.4em]">Personal Capital Ledger</p>
                 <p className="text-5xl md:text-7xl font-black mb-12 tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 <div className="grid grid-cols-2 gap-4">
                    <button className="bg-white/10 p-6 rounded-3xl text-[10px] font-black uppercase flex flex-col items-center gap-3 hover:bg-white/20 transition-all border border-white/5"><i className="fas fa-plus-circle text-2xl"></i> Deposit MoMo</button>
                    <button className="bg-emerald-600 p-6 rounded-3xl text-[10px] font-black uppercase shadow-2xl flex flex-col items-center gap-3 hover:bg-emerald-500 transition-all active:scale-95"><i className="fas fa-paper-plane text-2xl"></i> Withdraw MoMo</button>
                 </div>
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `REQ-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: data.principal,
                   purpose: data.purpose,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
                   collateralType: data.collateralType,
                   collateralValue: data.collateralValue
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, TravelMode, AuditLog, Transaction } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [sessionStartTime] = useState(new Date().toLocaleTimeString());

  // Login Sequence States
  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');

  // Theme State
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');

  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'LOGS' | 'USERS' | 'SIMULATE' | 'LIVE'>('MONITOR');

  // Vault Adjustment State
  const [adjAmount, setAdjAmount] = useState('');
  const [adjReason, setAdjReason] = useState('');

  // Simulation State
  const [simName, setSimName] = useState('');
  const [simAmount, setSimAmount] = useState('');

  // Helper for due date calculation
  const getDaysRemaining = (dueDate: string) => {
    const diff = new Date(dueDate).getTime() - new Date().getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  // Theme Management
  useEffect(() => {
    const root = document.documentElement;
    const updateTheme = () => {
      const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;

      if (effectiveTheme === 'dark') {
        root.classList.add('dark');
      } else {
        root.classList.remove('dark');
      }
    };

    updateTheme();
    localStorage.setItem('theme-mode', themeMode);

    if (themeMode === 'system') {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      mediaQuery.addEventListener('change', updateTheme);
      return () => mediaQuery.removeEventListener('change', updateTheme);
    }
  }, [themeMode]);

  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) setShowTour(true);
    }
  }, [currentUser]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Data sync failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');

    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
    const response = await apiService.authenticate(email);

    if (response.status !== 200) {
      setLoginError(response.error || "Access Denied.");
      setLoginSequence('IDLE');
      return;
    }

    let role: UserRole = 'BORROWER';
    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    if (adminEmails.includes(email)) role = 'ADMIN';

    const userData: User = {
      ...(response.user || {
        id: Math.random().toString(36).substr(2, 9),
        name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
        email: email,
        nrc: 'N/A',
        phone: 'N/A',
        address: 'N/A',
        operator: 'Airtel',
        role: role,
        joinedAt: new Date().toISOString(),
        walletBalance: 0
      })
    };

    const sync = await apiService.syncUser(userData);

    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 2500));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 2500));

    setCurrentUser(sync.user);
    localStorage.setItem('kwachatime_user', JSON.stringify(sync.user));
    setLoginSequence('IDLE');
  };

  const handleVaultAdjustment = async (isAddition: boolean) => {
    if (!adjAmount || !adjReason) return;
    setIsProcessing(true);
    const val = parseFloat(adjAmount) * (isAddition ? 1 : -1);
    await apiService.adjustCapital(val, adjReason);
    setAdjAmount('');
    setAdjReason('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleRunSimulation = async () => {
    if (!simName || !simAmount) return;
    setIsProcessing(true);
    await apiService.simulateLoan({
      name: simName,
      principal: parseFloat(simAmount),
      disbursedDate: new Date().toISOString(),
      dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
    });
    setSimName('');
    setSimAmount('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleManualDisbursementConfirm = async (loanId: string) => {
    setIsProcessing(true);
    try {
      await apiService.disburseLoan(loanId);
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  const toggleTheme = () => {
    setThemeMode(prev => {
      if (prev === 'light') return 'dark';
      if (prev === 'dark') return 'system';
      return 'light';
    });
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[80vh] p-4 transition-colors">
          <div className="w-full max-md">
            <div className="bg-white dark:bg-slate-900 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-800 relative overflow-hidden">
              <div className="absolute top-0 left-0 p-8">
                <button 
                  onClick={toggleTheme} 
                  className="w-12 h-12 bg-gray-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-600 dark:text-slate-300 transition-all active:scale-90"
                >
                  <i className={`fas ${themeMode === 'light' ? 'fa-sun' : themeMode === 'dark' ? 'fa-moon' : 'fa-circle-half-stroke'}`}></i>
                </button>
              </div>

              <div className="text-center mb-10 mt-8">
                 <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm">
                    <i className="fas fa-landmark text-3xl"></i>
                 </div>
                 <h2 className="text-3xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Kwacha Gate</h2>
                 <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-[0.3em] mt-2">Verified Lending Gateway</p>
              </div>

              {loginSequence !== 'IDLE' ? (
                <div className="flex flex-col items-center justify-center py-12 space-y-8 animate-fadeIn">
