export const backend = new VirtualBackend();

import { User, Loan, Transaction, AppNotification, AuditLog } from './types';

class VirtualBackend {
  private users: User[] = [];
  private loans: Loan[] = [];
  private transactions: Transaction[] = [];
  private auditLogs: AuditLog[] = [];
  private notifications: AppNotification[] = [];
  private vaultBalance: number = 750000;

  constructor() {
    this.loadFromStorage();
  }

  private loadFromStorage() {
    const data = localStorage.getItem('kwachatime_db');
    if (data) {
      try {
        const parsed = JSON.parse(data);
        this.users = parsed.users || [];
        this.loans = parsed.loans || [];
        this.transactions = parsed.transactions || [];
        this.auditLogs = parsed.auditLogs || [];
        this.notifications = parsed.notifications || [];
        this.vaultBalance = parsed.vaultBalance ?? 750000;
      } catch (e) {
        console.error("Failed to parse storage", e);
      }
    }
  }

  private saveToStorage() {
    const data = {
      users: this.users,
      loans: this.loans,
      transactions: this.transactions,
      auditLogs: this.auditLogs,
      notifications: this.notifications,
      vaultBalance: this.vaultBalance
    };
    localStorage.setItem('kwachatime_db', JSON.stringify(data));
  }

  public createAuditLog(userId: string, userName: string, action: string, category: AuditLog['category'], details: string, severity: AuditLog['severity'] = 'LOW') {
    const log: AuditLog = {
      id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
      userId,
      userName,
      action,
      category,
      details,
      timestamp: new Date().toISOString(),
      severity,
      deviceInfo: navigator.userAgent.slice(0, 50)
    };
    this.auditLogs.unshift(log);
    if (this.auditLogs.length > 5000) this.auditLogs.pop();
    this.saveToStorage();
  }

  async login(email: string): Promise<{ status: number; user?: User; error?: string }> {
    let user = this.users.find(u => u.email === email);
    const loginTime = new Date().toISOString();

    if (user) {
      this.createAuditLog(user.id, user.name, 'USER_LOGIN', 'SECURITY', `Successful login session started at ${new Date(loginTime).toLocaleString()}`, 'LOW');
    } else {
      this.createAuditLog('ANONYMOUS', email, 'LOGIN_ATTEMPT', 'SECURITY', `Initial access/registration requested for: ${email}`, 'LOW');
    }
    return { status: 200, user };
  }

  async register(userData: User): Promise<{ status: number; user: User }> {
    const existingIndex = this.users.findIndex(u => u.email === userData.email);
    const userToSave = { 
      ...userData, 
      walletBalance: userData.walletBalance ?? 0, 
      trustScore: 50,
      joinedAt: userData.joinedAt || new Date().toISOString()
    };

    if (existingIndex > -1) {
      this.users[existingIndex] = { ...this.users[existingIndex], ...userToSave };
    } else {
      this.users.push(userToSave);
      this.createAuditLog(userToSave.id, userToSave.name, 'USER_REGISTERED', 'IDENTITY', `New identity registered for ${userToSave.email}`, 'MEDIUM');
    }

    this.saveToStorage();
    return { status: 200, user: userToSave };
  }

  async adjustVault(amount: number, reason: string): Promise<{ status: number }> {
    this.vaultBalance += amount;
    const actionType = amount > 0 ? 'CAPITAL_INJECTION' : 'CAPITAL_WITHDRAWAL';

    this.createAuditLog('SYSTEM', 'MANAGEMENT', actionType, 'FINANCE', `Vault adjustment of ZMW ${Math.abs(amount)}. Reason: ${reason}`, 'HIGH');

    this.transactions.unshift({
      id: `ADJ-${Date.now()}`,
      amount: amount,
      type: amount > 0 ? 'WALLET_DEPOSIT' : 'WALLET_WITHDRAW',
      timestamp: new Date().toISOString(),
      status: 'SUCCESS',
      userName: 'MANAGEMENT'
    });

    this.saveToStorage();
    return { status: 200 };
  }

  async submitLoan(loan: Loan): Promise<{ status: number; loan: Loan }> {
    this.loans.push(loan);
    this.createAuditLog(loan.userId, loan.userName, 'LOAN_REQUEST', 'FINANCE', `Requested ZMW ${loan.principal} for ${loan.purpose}. Due date calculated for ${new Date(loan.dueDate).toLocaleDateString()}`, 'MEDIUM');
    this.saveToStorage();
    return { status: 201, loan };
  }

  async disburse(loanId: string): Promise<{ status: number; transactionId?: string; error?: string }> {
    const loan = this.loans.find(l => l.id === loanId);
    if (!loan) return { status: 404 };

    const user = this.users.find(u => u.id === loan.userId);
    if (!user) return { status: 404 };

    loan.status = 'DISBURSED';
    loan.disbursedAt = new Date().toISOString();

    this.vaultBalance -= loan.principal;
    user.walletBalance = (user.walletBalance || 0) + loan.principal;

    const txId = `TX-D-${Date.now()}`;
    this.transactions.unshift({
      id: txId,
      loanId: loan.id,
      userId: user.id,
      userName: user.name,
      amount: -loan.principal,
      type: 'DISBURSEMENT',
      timestamp: loan.disbursedAt,
      status: 'SUCCESS'
    });

    this.createAuditLog('ADMIN', 'MANAGEMENT', 'LOAN_DISBURSED', 'FINANCE', `ZMW ${loan.principal} successfully allocated to ${user.name}. Liquidity verified.`, 'HIGH');

    this.saveToStorage();
    return { status: 200, transactionId: txId };
  }

  async simulateLoan(data: { name: string, principal: number, disbursedDate: string, dueDate: string }) {
    const mockId = `SIM-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;
    const newLoan: Loan = {
      id: mockId,
      userId: 'SIM-USER',
      userName: data.name,
      principal: data.principal,
      purpose: 'System Simulation',
      status: 'DISBURSED',
      createdAt: new Date().toISOString(),
      disbursedAt: data.disbursedAt,
      dueDate: data.dueDate,
      collateralType: 'NONE'
    };
    this.loans.push(newLoan);
    this.createAuditLog('DEVELOPER', 'SIMULATOR', 'RUN_SIMULATION', 'SYSTEM', `Simulated loan of ZMW ${data.principal} for ${data.name}.`, 'MEDIUM');
    this.saveToStorage();
    return { status: 200 };
  }

  async repay(loanId: string, userId: string, amount: number): Promise<{ status: number }> {
    const loan = this.loans.find(l => l.id === loanId);
    const user = this.users.find(u => u.id === userId);

    if (loan) loan.status = 'REPAID';
    if (user) user.walletBalance = (user.walletBalance || 0) - amount;
    this.vaultBalance += amount;

    this.createAuditLog(userId, user?.name || 'Unknown', 'LOAN_REPAYMENT', 'FINANCE', `Repaid loan ${loanId} - Amount: ZMW ${amount}`, 'MEDIUM');
    this.saveToStorage();
    return { status: 200 };
  }

  getDashboardStats() {
    return {
      vaultBalance: this.vaultBalance,
      loans: [...this.loans],
      users: [...this.users],
      transactions: [...this.transactions],
      auditLogs: [...this.auditLogs]
    };
  }
}

