import { User, Loan, MobileOperator, Location, TravelMode, OutgoingEmail } from '../types';
import { backend } from '../backend';
import { generateLoanStatusEmail } from './geminiService';

const LATENCY = 1000;
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const apiService = {
  // Authentication handler
  async authenticate(email: string) {
    await wait(LATENCY);
    return backend.login(email);
  },

  // Sync user data with backend
  async syncUser(user: User) {
    await wait(500);
    return backend.register(user);
  },

  // Submit a new loan request
  async submitLoanRequest(loan: Loan) {
    await wait(LATENCY * 1.5);
    return backend.submitLoan(loan);
  },

  // Silently update user location
  async updateLocation(userId: string, location: Location) {
    // Silent update, minimal latency
    return backend.updateLocation(userId, location);
  },

  // Update travel status to office
  async setTravelStatus(loanId: string, status: boolean, mode?: TravelMode, eta?: string) {
    await wait(500);
    return backend.setTravelStatus(loanId, status, mode, eta);
  },

  // Fix: Added missing updateLoanStatus method for admin dashboard
  async updateLoanStatus(loanId: string, status: Loan['status']) {
    await wait(LATENCY);
    const result = await backend.updateLoanStatus(loanId, status);

    if (result.status === 200 && result.loan) {
      // Trigger Background AI Email Generation for status changes
      const stats = await backend.getDashboardStats();
      const user = stats.users.find(u => u.id === result.loan!.userId);
      if (user) {
        generateLoanStatusEmail(user, result.loan, status).then(emailContent => {
          const email: OutgoingEmail = {
            id: `MAIL-${Date.now()}`,
            recipientEmail: user.email,
            recipientName: user.name,
            subject: emailContent.subject,
            body: emailContent.body,
            status: 'SENT',
            timestamp: new Date().toISOString(),
            loanId: result.loan!.id
          };
          backend.logEmail(email);
        });
      }
    }
    return result;
  },

  // Confirm loan disbursement and trigger payout
  async disburseLoan(loanId: string) {
    await wait(LATENCY * 2);
    const result = await backend.disburse(loanId);

    if (result.status === 200) {
      // Trigger Background AI Email Generation for Disbursement confirmation
      const stats = await backend.getDashboardStats();
      const loan = stats.loans.find(l => l.id === loanId);
      const user = stats.users.find(u => u.id === loan?.userId);
      if (user && loan) {
        generateLoanStatusEmail(user, loan, 'DISBURSED').then(emailContent => {
          const email: OutgoingEmail = {
            id: `MAIL-${Date.now()}`,
            recipientEmail: user.email,
            recipientName: user.name,
            subject: emailContent.subject,
            body: emailContent.body,
            status: 'SENT',
            timestamp: new Date().toISOString(),
            loanId: loan.id
          };
          backend.logEmail(email);
        });
      }
    }
    return result;
  },

  // Admin capital management
  async adjustCapital(amount: number, reason: string) {
    await wait(LATENCY);
    return backend.adjustVault(amount, reason);
  },

  // Run a system simulation for developer testing
  async simulateLoan(data: { name: string, principal: number, disbursedDate: string, dueDate: string }) {
    await wait(LATENCY);
    return backend.simulateLoan(data);
  },

  // Handle loan repayments
  async repayLoan(loanId: string, userId: string, totalAmount: number) {
    await wait(LATENCY);
    return backend.repay(loanId, userId, totalAmount);
  },

  // Mobile Money withdrawal logic
  async withdrawToMoMo(userId: string, amount: number, operator: MobileOperator) {
    await wait(2500); 
    return backend.withdrawToMoMo(userId, amount, operator);
  },

  // Mobile Money deposit logic
  async depositFromMoMo(userId: string, amount: number) {
    await wait(2000); 
    return backend.depositFromMoMo(userId, amount);
  },

  // Fetch management statistics
  async getAdminData() {
    await wait(800);
    return backend.getDashboardStats();
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { User, Loan } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractNRCData = async (base64Image: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image.split(',')[1] || base64Image,
            },
          },
          {
            text: "You are a Zambian NRC scanner. Extract the following from this ID: Full Name, NRC Number (format 000000/00/0), and Residential Address. Return ONLY JSON.",
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            nrc: { type: Type.STRING },
            address: { type: Type.STRING },
          },
          required: ["name", "nrc", "address"],
        },
      },
    });
    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("NRC OCR failed", error);
    return null;
  }
};

export const generateLoanStatusEmail = async (user: User, loan: Loan, status: string, reason?: string) => {
  try {
    const ai = getAI();
    const prompt = `
      Act as the Automated Communications Officer for KwachaTime Micro-Lending (Lusaka, Zambia).
      Craft a professional, friendly, and firm email to a borrower regarding their loan status.
      Recipient Name: ${user.name}, Loan ID: ${loan.id}, Status: ${status}.
      Return ONLY JSON with "subject" and "body" (HTML).
    `;
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            subject: { type: Type.STRING },
            body: { type: Type.STRING },
          },
          required: ["subject", "body"],
        },
      },
    });
    return JSON.parse(response.text || '{"subject": "Loan Update", "body": "Your loan status has changed."}');
  } catch (error) {
    return { subject: "Loan Status Update", body: "Your KwachaTime loan has been updated." };
  }
};

export const generateLoanAgreement = async (user: User, loan: Loan) => {
  try {
    const ai = getAI();
    const prompt = `
      Generate a professional, legally binding Loan Agreement for a micro-loan in Zambia.
      Lender: KwachaTime Micro-Lending Systems Ltd (Lusaka).
      Borrower: ${user.name}, NRC: ${user.nrc}.
      Principal: ZMW ${loan.principal}.
      Terms: Repayment within 14 days, daily interest of 1% after grace period.
      Include sections: Parties, Loan Amount, Interest/Fees, Default/Collateral, and Signatures.
      Format: Professional HTML with Tailwind CSS. Do NOT include html/body/head tags. 
      Use a serif-like font style and a formal legal structure.
    `;
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    return "<p>Error generating legal document.</p>";
  }
};

export const generateLetterOfSale = async (user: User, loan: Loan) => {
  try {
    const ai = getAI();
    const prompt = `
      Generate a formal 'Letter of Sale & Transfer of Rights' for collateral in Zambia.
      This document allows KwachaTime to seize and sell the following item if the loan is defaulted:
      Item Type: ${loan.collateralType}
      Item Estimated Value: ZMW ${loan.collateralValue}
