  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [outgoingEmails, setOutgoingEmails] = useState<OutgoingEmail[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [sessionStartTime] = useState(new Date().toLocaleTimeString());

  // Legal Modal State
  const [activeLegalDoc, setActiveLegalDoc] = useState<{ loan: Loan; type: 'AGREEMENT' | 'LETTER_OF_SALE' } | null>(null);

  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');
  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'USERS' | 'SIMULATE' | 'LOGS' | 'COMMS'>('MONITOR');

  const [adjAmount, setAdjAmount] = useState('');
  const [adjReason, setAdjReason] = useState('');
  const [simName, setSimName] = useState('');
  const [simAmount, setSimAmount] = useState('');

  const getDaysRemaining = (dueDate: string) => {
    const diff = new Date(dueDate).getTime() - new Date().getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  useEffect(() => {
    const root = document.documentElement;
    const updateTheme = () => {
      const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;
      if (effectiveTheme === 'dark') root.classList.add('dark');
      else root.classList.remove('dark');
    };
    updateTheme();
    localStorage.setItem('theme-mode', themeMode);
  }, [themeMode]);

  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) setShowTour(true);
    }
  }, [currentUser]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
        setOutgoingEmails(stats.outgoingEmails);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Refresh failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
    const response = await apiService.authenticate(email);

    if (response.status !== 200) {
      setLoginError(response.error || "Access Denied.");
      setLoginSequence('IDLE');
      return;
    }

    let role: UserRole = 'BORROWER';
    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    if (adminEmails.includes(email)) role = 'ADMIN';

    const userData: User = {
      ...(response.user || {
        id: Math.random().toString(36).substr(2, 9),
        name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
        email: email,
        nrc: 'N/A',
        phone: 'N/A',
        address: 'N/A',
        operator: 'Airtel',
        role: role,
        joinedAt: new Date().toISOString(),
        walletBalance: 0
      })
    };

    const sync = await apiService.syncUser(userData);
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 2000));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 2000));

    setCurrentUser(sync.user);
    localStorage.setItem('kwachatime_user', JSON.stringify(sync.user));
    setLoginSequence('IDLE');
  };

  const handleVaultAdjustment = async (isAddition: boolean) => {
    if (!adjAmount || !adjReason) return;
    setIsProcessing(true);
    const val = parseFloat(adjAmount) * (isAddition ? 1 : -1);
    await apiService.adjustCapital(val, adjReason);
    setAdjAmount('');
    setAdjReason('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleRunSimulation = async () => {
    if (!simName || !simAmount) return;
    setIsProcessing(true);
    await apiService.simulateLoan({
      name: simName,
      principal: parseFloat(simAmount),
      disbursedDate: new Date().toISOString(),
      dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
    });
    setSimName('');
    setSimAmount('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleManualStatusUpdate = async (loanId: string, status: Loan['status']) => {
    setIsProcessing(true);
    try {
      if (status === 'DISBURSED') {
        await apiService.disburseLoan(loanId);
      } else {
        await apiService.updateLoanStatus(loanId, status);
      }
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  const toggleTheme = () => {
    setThemeMode(prev => {
      if (prev === 'light') return 'dark';
      if (prev === 'dark') return 'system';
      return 'light';
    });
  };

  const printLogs = () => {
    window.print();
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[80vh] p-4 transition-colors">
          <div className="w-full max-w-md">
            <div className="bg-white dark:bg-slate-900 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-800 relative overflow-hidden">
              <div className="absolute top-0 left-0 p-8">
                <button onClick={toggleTheme} className="w-12 h-12 bg-gray-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-600 dark:text-slate-300 transition-all active:scale-90">
                  <i className={`fas ${themeMode === 'light' ? 'fa-sun' : themeMode === 'dark' ? 'fa-moon' : 'fa-circle-half-stroke'}`}></i>
                </button>
              </div>

              <div className="text-center mb-10 mt-8">
                 <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm">
                    <i className="fas fa-landmark text-3xl"></i>
                 </div>
                 <h2 className="text-3xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Kwacha Gate</h2>
                 <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-[0.3em] mt-2">Verified Lending Gateway</p>
              </div>

              {loginSequence !== 'IDLE' ? (
                <div className="flex flex-col items-center justify-center py-12 space-y-8 animate-fadeIn">
                  <div className="relative w-28 h-28 flex items-center justify-center">
                    <div className="absolute inset-0 border-[6px] border-emerald-500/10 border-t-emerald-500 rounded-full animate-spin"></div>
                    <div className="text-5xl text-emerald-600 dark:text-emerald-400 animate-pulse">
                      {loginSequence === 'AUTHENTICATING' && <i className="fas fa-fingerprint"></i>}
                      {loginSequence === 'CLOCK' && <i className="fas fa-clock"></i>}
                      {loginSequence === 'CURRENCY' && <i className="fas fa-sack-dollar"></i>}
                    </div>
                  </div>
                  <div className="text-center">
                    <p className="text-xs font-black uppercase tracking-[0.4em] text-emerald-800 dark:text-emerald-400">
                      {loginSequence === 'AUTHENTICATING' && "Verifying Bio-Identity"}
                      {loginSequence === 'CLOCK' && "Calculating Market Time"}
                      {loginSequence === 'CURRENCY' && "Allocating Liquid Capital"}
                    </p>
                    <p className="text-[9px] font-bold text-gray-400 dark:text-gray-600 uppercase tracking-widest mt-3">DO NOT REFRESH SESSION</p>
                  </div>
                </div>
              ) : (
                <form onSubmit={handleInitialLogin} className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Email Identity</label>
                    <input name="email" type="email" placeholder="Enter your email address" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Full Legal Name</label>
                    <input name="name" placeholder="Enter your full legal name" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  {loginError && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{loginError}</p>}
                  <button className="w-full py-6 mt-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-emerald-950 shadow-2xl transition-all active:scale-95">Open Secure Vault</button>
                </form>
              )}
            </div>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={toggleTheme}>
      <CurrencyConverter />
      {showTour && <OnboardingTour role={currentUser.role} onComplete={() => {
        localStorage.setItem(`kwachatime_tour_done_${currentUser.id}`, 'true');
        setShowTour(false);
      }} />}

      {/* Legal Doc Modal Integration */}
      {activeLegalDoc && (
        <LegalDocumentModal 
          user={currentUser} 
          loan={activeLegalDoc.loan} 
          type={activeLegalDoc.type} 
          onClose={() => setActiveLegalDoc(null)} 
        />
      )}

      {isAdmin ? (
        <div className="space-y-10 animate-fadeIn text-slate-900 dark:text-white no-print">
          <div className="bg-slate-900 dark:bg-emerald-950/40 text-white p-10 rounded-[4rem] shadow-2xl relative overflow-hidden border-4 border-slate-800 dark:border-emerald-900/50">
            <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-10">
              <div className="text-center md:text-left">
                <p className="text-emerald-400 text-[11px] font-black uppercase tracking-[0.5em] mb-3">Management Terminal</p>
                <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter">Kwacha Ops</h2>
              </div>
              <div className="flex flex-wrap justify-center gap-6">
                <div className="px-8 py-5 bg-white/5 rounded-[2rem] border border-white/10 text-center min-w-[160px]">
                  <p className="text-[9px] font-black uppercase text-emerald-400 mb-1">Vault Liquidity</p>
                  <p className="text-2xl font-black">{formatCurrency(vaultBalance)}</p>
                </div>
                <div className="px-8 py-5 bg-white/5 rounded-[2rem] border border-white/10 text-center min-w-[160px]">
                  <p className="text-[9px] font-black uppercase text-orange-400 mb-1">Active Portfolio</p>
                  <p className="text-2xl font-black">{formatCurrency(allLoans.filter(l => l.status === 'DISBURSED').reduce((acc, curr) => acc + curr.principal, 0))}</p>
                </div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <div className="lg:col-span-1 space-y-4">
              {[
                { id: 'MONITOR', icon: 'fa-chart-pie', label: 'Monitor' },
                { id: 'PENDING', icon: 'fa-shield-halved', label: 'Approvals' },
                { id: 'COMMS', icon: 'fa-envelope-open-text', label: 'Comms' },
                { id: 'USERS', icon: 'fa-users-line', label: 'Ledger' },
                { id: 'SIMULATE', icon: 'fa-flask-vial', label: 'Simulate' },
                { id: 'LOGS', icon: 'fa-list-check', label: 'Audit Logs' }
              ].map(tab => (
                <button 
                  key={tab.id} 
                  onClick={() => setActiveAdminTab(tab.id as any)}
                  className={`w-full flex items-center gap-4 p-6 rounded-3xl text-[11px] font-black uppercase transition-all ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white shadow-xl' : 'bg-white dark:bg-slate-900 text-gray-400 dark:text-gray-500 border border-transparent hover:bg-gray-100 dark:hover:bg-slate-800'}`}
                >
                  <i className={`fas ${tab.icon} text-lg w-6`}></i>
                  {tab.label}
                </button>
              ))}
            </div>

            <div className="lg:col-span-3 min-h-[60vh]">
              {activeAdminTab === 'MONITOR' && (
                <div className="space-y-8 animate-fadeIn">
                  <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                    <h3 className="text-xl font-black uppercase tracking-tighter mb-8">Vault Controls</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                       <input 
                         type="number" placeholder="ZMW Amount" value={adjAmount}
                         onChange={(e) => setAdjAmount(e.target.value)}
                         className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold"
                       />
                       <input 
                         type="text" placeholder="Adjustment Reason" value={adjReason}
                         onChange={(e) => setAdjReason(e.target.value)}
                         className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold"
                       />
                    </div>
                    <div className="grid grid-cols-2 gap-6">
                       <button onClick={() => handleVaultAdjustment(true)} className="py-6 bg-emerald-600 text-white rounded-3xl font-black uppercase tracking-widest shadow-xl hover:bg-emerald-700 transition-all flex items-center justify-center gap-3">
                         <i className="fas fa-plus-circle"></i> Add Capital
                       </button>
                       <button onClick={() => handleVaultAdjustment(false)} className="py-6 bg-red-600 text-white rounded-3xl font-black uppercase tracking-widest shadow-xl hover:bg-red-700 transition-all flex items-center justify-center gap-3">
                         <i className="fas fa-minus-circle"></i> Subtract Capital
                       </button>
                    </div>
                  </div>

                  <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                    <h3 className="text-xl font-black uppercase tracking-tighter mb-6">Live Activity</h3>
                    <div className="overflow-x-auto">
                      <table className="w-full text-left">
                        <thead>
                          <tr className="text-[10px] font-black uppercase text-gray-400 border-b border-gray-100 dark:border-slate-800">
                            <th className="pb-4">Time</th>
                            <th className="pb-4">User</th>
                            <th className="pb-4">Action</th>
                            <th className="pb-4">Amount</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 dark:divide-slate-800">
                          {transactions.slice(0, 8).map(tx => (
                            <tr key={tx.id} className="text-xs">
                              <td className="py-4 font-mono text-gray-400">{new Date(tx.timestamp).toLocaleTimeString()}</td>
                              <td className="py-4 font-bold">{tx.userName}</td>
                              <td className="py-4 font-black uppercase text-emerald-600">{tx.type}</td>
                              <td className={`py-4 font-black ${tx.amount > 0 ? 'text-emerald-500' : 'text-red-500'}`}>{formatCurrency(tx.amount)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              )}

              {activeAdminTab === 'PENDING' && (
                <div className="space-y-4">
                  {allLoans.filter(l => l.status === 'PENDING').map(loan => (
                    <div key={loan.id} className="bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800 flex justify-between items-center group">
                      <div className="flex items-center gap-6">
                        <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 rounded-3xl flex items-center justify-center font-black text-2xl">
                          {loan.userName[0]}
                        </div>
                        <div>
                          <h4 className="text-xl font-black">{loan.userName}</h4>
                          <p className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">Purpose: {loan.purpose}</p>
                          <div className="flex gap-2 mt-2">
                            <button onClick={() => setActiveLegalDoc({ loan, type: 'AGREEMENT' })} className="text-[8px] font-black uppercase bg-gray-100 dark:bg-slate-800 px-3 py-1 rounded-md hover:bg-emerald-100 transition-colors">Draft Agreement</button>
                            <button onClick={() => setActiveLegalDoc({ loan, type: 'LETTER_OF_SALE' })} className="text-[8px] font-black uppercase bg-gray-100 dark:bg-slate-800 px-3 py-1 rounded-md hover:bg-emerald-100 transition-colors">Draft Sale Letter</button>
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-4">
                        <div className="text-right mr-4">
                          <p className="text-2xl font-black">{formatCurrency(loan.principal)}</p>
                          <p className="text-[9px] font-black uppercase text-gray-400">Due: {new Date(loan.dueDate).toLocaleDateString()}</p>
                        </div>
                        <div className="flex flex-col gap-2">
                          <button 
                            disabled={isProcessing}
                            onClick={() => handleManualStatusUpdate(loan.id, 'APPROVED')} 
                            className="px-6 py-3 bg-emerald-800 text-white rounded-xl text-[9px] font-black uppercase shadow-lg hover:bg-emerald-950 transition-all flex items-center justify-center gap-2"
                          >
                            <i className="fas fa-check"></i> Approve
                          </button>
                          <button 
                            disabled={isProcessing}
                            onClick={() => handleManualStatusUpdate(loan.id, 'REJECTED')} 
                            className="px-6 py-3 bg-red-800 text-white rounded-xl text-[9px] font-black uppercase shadow-lg hover:bg-red-950 transition-all flex items-center justify-center gap-2"
                          >
                            <i className="fas fa-times"></i> Reject
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}

                  {allLoans.filter(l => l.status === 'APPROVED').length > 0 && (
                    <div className="mt-10 space-y-4">
                       <h4 className="text-[10px] font-black uppercase text-emerald-600 tracking-widest pl-4">Awaiting Disbursement</h4>
                       {allLoans.filter(l => l.status === 'APPROVED').map(loan => (
                          <div key={loan.id} className="bg-emerald-50 dark:bg-emerald-950/20 p-8 rounded-[3.5rem] shadow-xl border border-emerald-100 dark:border-emerald-900/50 flex justify-between items-center">
                             <div className="flex items-center gap-6">
                                <div className="w-12 h-12 bg-emerald-800 text-white rounded-2xl flex items-center justify-center"><i className="fas fa-thumbs-up"></i></div>
                                <div>
                                   <p className="font-black">{loan.userName}</p>
                                   <p className="text-[9px] font-black uppercase text-emerald-600">ID: {loan.id}</p>
                                </div>
                             </div>
                             <button 
                                onClick={() => handleManualStatusUpdate(loan.id, 'DISBURSED')}
                                className="px-10 py-5 bg-orange-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-orange-700 transition-all"
                             >
                                Confirm Payout
                             </button>
                          </div>
                       ))}
                    </div>
                  )}

                  {allLoans.filter(l => l.status === 'PENDING').length === 0 && allLoans.filter(l => l.status === 'APPROVED').length === 0 && (
                    <div className="bg-white dark:bg-slate-900 p-20 rounded-[4rem] text-center opacity-30">
                       <i className="fas fa-check-double text-6xl mb-6"></i>
                       <p className="text-xs font-black uppercase">Approval queue clear</p>
                    </div>
                  )}
                </div>
              )}

              {activeAdminTab === 'COMMS' && (
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                  <h3 className="text-xl font-black uppercase tracking-tighter mb-8">AI Notification Ledger</h3>
                  <div className="space-y-6">
                    {outgoingEmails.map(mail => (
                      <div key={mail.id} className="p-6 bg-gray-50 dark:bg-slate-800 rounded-[2rem] border border-gray-100 dark:border-slate-700">
                        <div className="flex justify-between items-start mb-4">
                          <div>
                            <p className="text-[9px] font-black uppercase text-emerald-600 mb-1">Sent to {mail.recipientName}</p>
                            <p className="text-xs font-black">{mail.subject}</p>
                          </div>
                          <span className="px-3 py-1 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 text-[8px] font-black uppercase rounded-full">
                            {mail.status} via AI-Gateway
                          </span>
                        </div>
                        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl text-[10px] text-gray-500 max-h-32 overflow-y-auto" dangerouslySetInnerHTML={{ __html: mail.body }} />
                        <p className="mt-3 text-[8px] font-mono text-gray-400">{new Date(mail.timestamp).toLocaleString()} • Loan Ref: {mail.loanId}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {activeAdminTab === 'USERS' && (
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                   <h3 className="text-xl font-black uppercase tracking-tighter mb-8">User Ledger</h3>
                   <div className="overflow-x-auto">
                      <table className="w-full text-left">
                        <thead>
                          <tr className="text-[10px] font-black uppercase text-gray-400 border-b border-gray-100 dark:border-slate-800">
                            <th className="pb-4">User Details</th>
                            <th className="pb-4">Balance</th>
                            <th className="pb-4">Join Date</th>
                            <th className="pb-4">Last Active</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 dark:divide-slate-800">
                          {allUsers.map(user => (
                            <tr key={user.id} className="text-xs">
                              <td className="py-4">
                                <p className="font-black">{user.name}</p>
                                <p className="text-[10px] text-gray-400">{user.email}</p>
                              </td>
                              <td className="py-4 font-black text-emerald-600">{formatCurrency(user.walletBalance || 0)}</td>
                              <td className="py-4 text-gray-400">{new Date(user.joinedAt).toLocaleDateString()}</td>
                              <td className="py-4 font-mono">{user.currentLocation?.timestamp ? new Date(user.currentLocation.timestamp).toLocaleTimeString() : 'N/A'}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                   </div>
                </div>
              )}

              {activeAdminTab === 'SIMULATE' && (
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                   <h3 className="text-xl font-black uppercase tracking-tighter mb-8">Simulate Loan Activity</h3>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                       <input type="text" placeholder="Mock Client Name" value={simName} onChange={(e) => setSimName(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                       <input type="number" placeholder="Principal (ZMW)" value={simAmount} onChange={(e) => setSimAmount(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                   </div>
                   <button onClick={handleRunSimulation} className="w-full py-6 bg-emerald-800 text-white rounded-3xl font-black uppercase tracking-widest">Inject Simulation Data</button>
                </div>
              )}

              {activeAdminTab === 'LOGS' && (
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl border border-gray-100 dark:border-slate-800">
                   <div className="flex justify-between items-center mb-8">
                      <h3 className="text-xl font-black uppercase tracking-tighter">System Audit History</h3>
                      <button onClick={printLogs} className="px-6 py-3 bg-emerald-800 text-white rounded-2xl text-[10px] font-black uppercase flex items-center gap-2">
                         <i className="fas fa-print"></i> Export Report
                      </button>
                   </div>
                   <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                      {auditLogs.map(log => (
                        <div key={log.id} className={`p-5 bg-gray-50 dark:bg-slate-800 rounded-2xl border-l-4 ${log.severity === 'HIGH' ? 'border-red-500' : 'border-emerald-500'} flex items-start gap-4`}>
                           <div className="shrink-0 pt-1 text-gray-400"><i className="fas fa-clock text-xs"></i></div>
                           <div>
                              <div className="flex items-center gap-3 mb-1">
                                 <p className="text-[10px] font-black uppercase tracking-widest">{log.action}</p>
                                 <span className="text-[8px] font-mono text-gray-400">{new Date(log.timestamp).toLocaleString()}</span>
                              </div>
                              <p className="text-[11px] font-medium text-gray-600 dark:text-gray-400 leading-tight">{log.details}</p>
                              <p className="text-[9px] font-black uppercase text-emerald-600 mt-2">Operator: {log.userName}</p>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        /* Borrower Dashboard */
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 text-slate-900 dark:text-white animate-fadeIn no-print">
           <div className="lg:col-span-1 space-y-10">
              <div className="p-8 bg-emerald-100/50 dark:bg-emerald-900/20 rounded-[2.5rem] border-2 border-emerald-200 dark:border-emerald-800/30">
                 <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-emerald-800 text-white rounded-xl flex items-center justify-center"><i className="fas fa-fingerprint"></i></div>
                    <div>
                       <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest">Active Session Verified</p>
                       <p className="text-xs font-black uppercase">Started: {sessionStartTime}</p>
                    </div>
                 </div>
              </div>
              <Roadmap />
              <OfficeLocator />
              <div className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] shadow-xl border border-gray-100 dark:border-slate-800">
                <h4 className="text-[10px] font-black uppercase text-gray-400 mb-6 tracking-widest">Sample Documents</h4>
                <div className="space-y-4">
                  <button onClick={() => setActiveLegalDoc({ loan: allLoans[0] || { id: 'SAMPLE' }, type: 'AGREEMENT' } as any)} className="w-full p-4 bg-gray-50 dark:bg-slate-800 rounded-2xl text-[9px] font-black uppercase text-emerald-600 border border-emerald-100 hover:bg-emerald-50 transition-all flex items-center gap-3">
                    <i className="fas fa-file-contract"></i> Sample Loan Agreement
                  </button>
                  <button onClick={() => setActiveLegalDoc({ loan: allLoans[0] || { id: 'SAMPLE' }, type: 'LETTER_OF_SALE' } as any)} className="w-full p-4 bg-gray-50 dark:bg-slate-800 rounded-2xl text-[9px] font-black uppercase text-emerald-600 border border-emerald-100 hover:bg-emerald-50 transition-all flex items-center gap-3">
                    <i className="fas fa-file-signature"></i> Sample Letter of Sale
                  </button>
                </div>
              </div>
           </div>

           <div className="lg:col-span-2 space-y-10">
              <div className="bg-emerald-950 text-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-900 relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-10 text-9xl text-white/5 pointer-events-none group-hover:scale-110 transition-transform duration-1000"><i className="fas fa-wallet"></i></div>
                 <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-[0.4em]">Personal Capital Balance</p>
                 <p className="text-5xl md:text-7xl font-black mb-12 tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 <div className="grid grid-cols-2 gap-4">
                    <button className="bg-white/10 p-6 rounded-3xl text-[10px] font-black uppercase border border-white/5 hover:bg-white/20 transition-all flex flex-col items-center gap-3"><i className="fas fa-plus-circle text-2xl"></i> Top-up MoMo</button>
                    <button className="bg-emerald-600 p-6 rounded-3xl text-[10px] font-black uppercase shadow-2xl hover:bg-emerald-500 transition-all flex flex-col items-center gap-3"><i className="fas fa-paper-plane text-2xl"></i> Withdraw MoMo</button>
                 </div>
              </div>

              <div className="space-y-6">
                 <h3 className="text-xs font-black uppercase text-gray-400 tracking-widest pl-4">Your Active Portfolio</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {allLoans.filter(l => l.status === 'DISBURSED' || l.status === 'APPROVED' || l.status === 'REJECTED').map(loan => {
                       const daysLeft = getDaysRemaining(loan.dueDate);
                       const isOverdue = daysLeft < 0;
                       const statusColor = loan.status === 'APPROVED' ? 'bg-blue-500' : loan.status === 'REJECTED' ? 'bg-red-500' : 'bg-emerald-600';

                       return (
                          <div key={loan.id} className={`p-8 bg-white dark:bg-slate-900 rounded-[3rem] shadow-xl border-2 transition-all ${isOverdue && loan.status === 'DISBURSED' ? 'border-red-500 animate-pulse' : 'border-gray-50 dark:border-slate-800'}`}>
                             <div className="flex justify-between items-start mb-6">
                                <div>
                                   <p className="text-[9px] font-black uppercase text-gray-400 mb-1">Ref: {loan.id}</p>
                                   <h4 className="text-xl font-black">{formatCurrency(loan.principal)}</h4>
                                </div>
                                <div className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase text-white ${statusColor}`}>
                                   {loan.status}
                                </div>
                             </div>

                             <div className="flex flex-col gap-2 mb-6">
                                <button onClick={() => setActiveLegalDoc({ loan, type: 'AGREEMENT' })} className="w-full text-[8px] font-black uppercase border-2 border-emerald-50 py-3 rounded-xl hover:bg-emerald-50 transition-all flex items-center justify-center gap-2">
                                  <i className="fas fa-file-contract text-emerald-600"></i> View Agreement
                                </button>
                                <button onClick={() => setActiveLegalDoc({ loan, type: 'LETTER_OF_SALE' })} className="w-full text-[8px] font-black uppercase border-2 border-emerald-50 py-3 rounded-xl hover:bg-emerald-50 transition-all flex items-center justify-center gap-2">
                                  <i className="fas fa-file-signature text-emerald-600"></i> View Letter of Sale
                                </button>
                             </div>

                             {loan.status === 'DISBURSED' && (
                                <div className="space-y-4">
                                  <div className="flex justify-between items-end">
                                     <p className="text-[10px] font-black uppercase text-gray-500">
                                        {isOverdue ? `${Math.abs(daysLeft)} Days Past Due` : `${daysLeft} Days Remaining`}
                                     </p>
                                     <p className="text-[9px] font-bold text-gray-400">Due: {new Date(loan.dueDate).toLocaleDateString()}</p>
                                  </div>
                                  <div className="h-2 bg-gray-100 dark:bg-slate-800 rounded-full overflow-hidden">
                                     <div className={`h-full transition-all duration-1000 ${isOverdue ? 'bg-red-500' : 'bg-emerald-600'}`} style={{ width: `${Math.min(100, Math.max(0, (14 - daysLeft) / 14 * 100))}%` }}></div>
                                  </div>
                                </div>
                             )}
                          </div>
                       );
                    })}
                 </div>
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `REQ-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: data.principal,
                   purpose: data.purpose,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
                   collateralType: data.collateralType,
                   collateralValue: data.collateralValue
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, AuditLog, Transaction, OutgoingEmail } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import LegalDocumentModal from './components/LegalDocumentModal';
import OperationalManual from './components/OperationalManual';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [outgoingEmails, setOutgoingEmails] = useState<OutgoingEmail[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [showManual, setShowManual] = useState(false);
  const [sessionStartTime] = useState(new Date().toLocaleTimeString());

  // Legal Modal State
  const [activeLegalDoc, setActiveLegalDoc] = useState<{ loan: Loan; type: 'AGREEMENT' | 'LETTER_OF_SALE' } | null>(null);

  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');
  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'USERS' | 'SIMULATE' | 'LOGS' | 'COMMS'>('MONITOR');

  const [adjAmount, setAdjAmount] = useState('');
  const [adjReason, setAdjReason] = useState('');
  const [simName, setSimName] = useState('');
  const [simAmount, setSimAmount] = useState('');

  const getDaysRemaining = (dueDate: string) => {
    const diff = new Date(dueDate).getTime() - new Date().getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  useEffect(() => {
    const root = document.documentElement;
    const updateTheme = () => {
      const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;
      if (effectiveTheme === 'dark') root.classList.add('dark');
      else root.classList.remove('dark');
    };
    updateTheme();
    localStorage.setItem('theme-mode', themeMode);
  }, [themeMode]);

  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) setShowTour(true);
    }
  }, [currentUser]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
        setOutgoingEmails(stats.outgoingEmails);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Refresh failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
    const response = await apiService.authenticate(email);

    if (response.status !== 200) {
      setLoginError(response.error || "Access Denied.");
      setLoginSequence('IDLE');
      return;
    }

    let role: UserRole = 'BORROWER';
    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    if (adminEmails.includes(email)) role = 'ADMIN';

    const userData: User = {
      ...(response.user || {
        id: Math.random().toString(36).substr(2, 9),
        name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
        email: email,
        nrc: 'N/A',
        phone: 'N/A',
        address: 'N/A',
        operator: 'Airtel',
        role: role,
        joinedAt: new Date().toISOString(),
        walletBalance: 0
      })
    };

    const sync = await apiService.syncUser(userData);
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 2000));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 2000));

    setCurrentUser(sync.user);
    localStorage.setItem('kwachatime_user', JSON.stringify(sync.user));
    setLoginSequence('IDLE');
  };

  const handleVaultAdjustment = async (isAddition: boolean) => {
    if (!adjAmount || !adjReason) return;
    setIsProcessing(true);
    const val = parseFloat(adjAmount) * (isAddition ? 1 : -1);
    await apiService.adjustCapital(val, adjReason);
    setAdjAmount('');
    setAdjReason('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleRunSimulation = async () => {
    if (!simName || !simAmount) return;
    setIsProcessing(true);
    await apiService.simulateLoan({
      name: simName,
      principal: parseFloat(simAmount),
      disbursedDate: new Date().toISOString(),
      dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
    });
    setSimName('');
    setSimAmount('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleManualStatusUpdate = async (loanId: string, status: Loan['status']) => {
    setIsProcessing(true);
    try {
      if (status === 'DISBURSED') {
        await apiService.disburseLoan(loanId);
      } else {
        await apiService.updateLoanStatus(loanId, status);
      }
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  const toggleTheme = () => {
    setThemeMode(prev => {
      if (prev === 'light') return 'dark';
      if (prev === 'dark') return 'system';
      return 'light';
    });
  };

  const printLogs = () => {
    window.print();
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[80vh] p-4 transition-colors">
          <div className="w-full max-w-md">
            <div className="bg-white dark:bg-slate-900 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-800 relative overflow-hidden">
              <div className="absolute top-0 left-0 p-8">
                <button onClick={toggleTheme} className="w-12 h-12 bg-gray-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-600 dark:text-slate-300 transition-all active:scale-90">
                  <i className={`fas ${themeMode === 'light' ? 'fa-sun' : themeMode === 'dark' ? 'fa-moon' : 'fa-circle-half-stroke'}`}></i>
                </button>
              </div>

              <div className="text-center mb-10 mt-8">
                 <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm">
                    <i className="fas fa-landmark text-3xl"></i>
                 </div>
                 <h2 className="text-3xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Kwacha Gate</h2>
                 <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-[0.3em] mt-2">Verified Lending Gateway</p>
              </div>

              {loginSequence !== 'IDLE' ? (
                <div className="flex flex-col items-center justify-center py-12 space-y-8 animate-fadeIn">
                  <div className="relative w-28 h-28 flex items-center justify-center">
                    <div className="absolute inset-0 border-[6px] border-emerald-500/10 border-t-emerald-500 rounded-full animate-spin"></div>
                    <div className="text-5xl text-emerald-600 dark:text-emerald-400 animate-pulse">
                      {loginSequence === 'AUTHENTICATING' && <i className="fas fa-fingerprint"></i>}
                      {loginSequence === 'CLOCK' && <i className="fas fa-clock"></i>}
                      {loginSequence === 'CURRENCY' && <i className="fas fa-sack-dollar"></i>}
                    </div>
                  </div>
                  <div className="text-center">
                    <p className="text-xs font-black uppercase tracking-[0.4em] text-emerald-800 dark:text-emerald-400">
                      {loginSequence === 'AUTHENTICATING' && "Verifying Bio-Identity"}
                      {loginSequence === 'CLOCK' && "Calculating Market Time"}
                      {loginSequence === 'CURRENCY' && "Allocating Liquid Capital"}
                    </p>
                    <p className="text-[9px] font-bold text-gray-400 dark:text-gray-600 uppercase tracking-widest mt-3">DO NOT REFRESH SESSION</p>
                  </div>
                </div>
              ) : (
                <form onSubmit={handleInitialLogin} className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Email Identity</label>
                    <input name="email" type="email" placeholder="Enter your email address" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Full Legal Name</label>
                    <input name="name" placeholder="Enter your full legal name" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  {loginError && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{loginError}</p>}
                  <button className="w-full py-6 mt-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-emerald-950 shadow-2xl transition-all active:scale-95">Open Secure Vault</button>
                </form>
              )}
            </div>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={toggleTheme}>
      <CurrencyConverter />
      {showTour && <OnboardingTour role={currentUser.role} onComplete={() => {
        localStorage.setItem(`kwachatime_tour_done_${currentUser.id}`, 'true');
        setShowTour(false);
      }} />}

      {/* Manual & Help Integration */}
      {showManual && <OperationalManual onClose={() => setShowManual(false)} />}

      {/* Legal Doc Modal Integration */}
      {activeLegalDoc && (
        <LegalDocumentModal 
          user={currentUser} 
          loan={activeLegalDoc.loan} 
          type={activeLegalDoc.type} 
          onClose={() => setActiveLegalDoc(null)} 
        />
      )}

      {/* Action Bar for Manual Access */}
      <div className="fixed bottom-10 left-10 z-[2000] no-print">
        <button
          onClick={() => setShowManual(true)}
          className="w-16 h-16 bg-white dark:bg-slate-900 text-emerald-800 dark:text-emerald-400 rounded-full shadow-2xl border-4 border-emerald-50 dark:border-slate-800 flex items-center justify-center hover:scale-110 transition-transform active:scale-95 group relative"
        >
          <i className="fas fa-book-open text-xl"></i>
          <span className="absolute left-20 bg-emerald-950 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
            System Roadmap
          </span>
        </button>
      </div>

      {isAdmin ? (
        <div className="space-y-10 animate-fadeIn text-slate-900 dark:text-white no-print">
          <div className="bg-slate-900 dark:bg-emerald-950/40 text-white p-10 rounded-[4rem] shadow-2xl relative overflow-hidden border-4 border-slate-800 dark:border-emerald-900/50">
            <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-10">
              <div className="text-center md:text-left">
                <p className="text-emerald-400 text-[11px] font-black uppercase tracking-[0.5em] mb-3">Management Terminal</p>
                <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter">Kwacha Ops</h2>
              </div>
              <div className="flex flex-wrap justify-center gap-6">
                <div className="px-8 py-5 bg-white/5 rounded-[2rem] border border-white/10 text-center min-w-[160px]">
                  <p className="text-[9px] font-black uppercase text-emerald-400 mb-1">Vault Liquidity</p>
                  <p className="text-2xl font-black">{formatCurrency(vaultBalance)}</p>
                </div>
                <div className="px-8 py-5 bg-white/5 rounded-[2rem] border border-white/10 text-center min-w-[160px]">
                  <p className="text-[9px] font-black uppercase text-orange-400 mb-1">Active Portfolio</p>
                  <p className="text-2xl font-black">{formatCurrency(allLoans.filter(l => l.status === 'DISBURSED').reduce((acc, curr) => acc + curr.principal, 0))}</p>
                </div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <div className="lg:col-span-1 space-y-4">
              {[
                { id: 'MONITOR', icon: 'fa-chart-pie', label: 'Monitor' },
                { id: 'PENDING', icon: 'fa-shield-halved', label: 'Approvals' },
                { id: 'COMMS', icon: 'fa-envelope-open-text', label: 'Comms' },
                { id: 'USERS', icon: 'fa-users-line', label: 'Ledger' },
                { id: 'SIMULATE', icon: 'fa-flask-vial', label: 'Simulate' },
                { id: 'LOGS', icon: 'fa-list-check', label: 'Audit Logs' }
              ].map(tab => (
                <button 
                  key={tab.id} 
                  onClick={() => setActiveAdminTab(tab.id as any)}
