import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, AuditLog, Transaction, OutgoingEmail } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import LegalDocumentModal from './components/LegalDocumentModal';
import OperationalManual from './components/OperationalManual';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [outgoingEmails, setOutgoingEmails] = useState<OutgoingEmail[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [showManual, setShowManual] = useState(false);
  const [updateAvailable, setUpdateAvailable] = useState(false);
  const [sessionStartTime] = useState(new Date().toLocaleTimeString());

  // Legal Modal State
  const [activeLegalDoc, setActiveLegalDoc] = useState<{ loan: Loan; type: 'AGREEMENT' | 'LETTER_OF_SALE' } | null>(null);

  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');
  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'USERS' | 'SIMULATE' | 'LOGS' | 'COMMS'>('MONITOR');

  const [adjAmount, setAdjAmount] = useState('');
  const [adjReason, setAdjReason] = useState('');
  const [simName, setSimName] = useState('');
  const [simAmount, setSimAmount] = useState('');

  const getDaysRemaining = (dueDate: string) => {
    const diff = new Date(dueDate).getTime() - new Date().getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  useEffect(() => {
    const root = document.documentElement;
    const updateTheme = () => {
      const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;
      if (effectiveTheme === 'dark') root.classList.add('dark');
      else root.classList.remove('dark');
    };
    updateTheme();
    localStorage.setItem('theme-mode', themeMode);
  }, [themeMode]);

  // Listen for PWA Update Event
  useEffect(() => {
    const handleUpdate = () => {
      setUpdateAvailable(true);
    };
    window.addEventListener('pwa-update-available', handleUpdate);
    return () => window.removeEventListener('pwa-update-available', handleUpdate);
  }, []);

  const handleRefreshApp = () => {
    window.location.reload();
  };

  useEffect(() => {
    if (currentUser) {
      const tourDone = localStorage.getItem(`kwachatime_tour_done_${currentUser.id}`);
      if (!tourDone) setShowTour(true);
    }
  }, [currentUser]);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setTransactions(stats.transactions);
        setAuditLogs(stats.auditLogs);
        setOutgoingEmails(stats.outgoingEmails);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Refresh failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();
    const response = await apiService.authenticate(email);

    if (response.status !== 200) {
      setLoginError(response.error || "Access Denied.");
      setLoginSequence('IDLE');
      return;
    }

    let role: UserRole = 'BORROWER';
    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    if (adminEmails.includes(email)) role = 'ADMIN';

    const userData: User = {
      ...(response.user || {
        id: Math.random().toString(36).substr(2, 9),
        name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
        email: email,
        nrc: 'N/A',
        phone: 'N/A',
        address: 'N/A',
        operator: 'Airtel',
        role: role,
        joinedAt: new Date().toISOString(),
        walletBalance: 0
      })
    };

    const sync = await apiService.syncUser(userData);
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 2000));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 2000));

    setCurrentUser(sync.user);
    localStorage.setItem('kwachatime_user', JSON.stringify(sync.user));
    setLoginSequence('IDLE');
  };

  const handleVaultAdjustment = async (isAddition: boolean) => {
    if (!adjAmount || !adjReason) return;
    setIsProcessing(true);
    const val = parseFloat(adjAmount) * (isAddition ? 1 : -1);
    await apiService.adjustCapital(val, adjReason);
    setAdjAmount('');
    setAdjReason('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleRunSimulation = async () => {
    if (!simName || !simAmount) return;
    setIsProcessing(true);
    await apiService.simulateLoan({
      name: simName,
      principal: parseFloat(simAmount),
      disbursedDate: new Date().toISOString(),
      dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
    });
    setSimName('');
    setSimAmount('');
    await refreshData();
    setIsProcessing(false);
  };

  const handleManualStatusUpdate = async (loanId: string, status: Loan['status']) => {
    setIsProcessing(true);
    try {
      if (status === 'DISBURSED') {
        await apiService.disburseLoan(loanId);
      } else {
        await apiService.updateLoanStatus(loanId, status);
      }
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  const toggleTheme = () => {
    setThemeMode(prev => {
      if (prev === 'light') return 'dark';
      if (prev === 'dark') return 'system';
      return 'light';
    });
  };

  const printLogs = () => {
    window.print();
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[80vh] p-4 transition-colors">
          <div className="w-full max-w-md">
            <div className="bg-white dark:bg-slate-900 p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-800 relative overflow-hidden">
              <div className="absolute top-0 left-0 p-8">
                <button onClick={toggleTheme} className="w-12 h-12 bg-gray-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-600 dark:text-slate-300 transition-all active:scale-90">
                  <i className={`fas ${themeMode === 'light' ? 'fa-sun' : themeMode === 'dark' ? 'fa-moon' : 'fa-circle-half-stroke'}`}></i>
                </button>
              </div>

              <div className="text-center mb-10 mt-8">
                 <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm">
                    <i className="fas fa-landmark text-3xl"></i>
                 </div>
                 <h2 className="text-3xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Kwacha Gate</h2>
                 <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-[0.3em] mt-2">Verified Lending Gateway</p>
              </div>

              {loginSequence !== 'IDLE' ? (
                <div className="flex flex-col items-center justify-center py-12 space-y-8 animate-fadeIn">
                  <div className="relative w-28 h-28 flex items-center justify-center">
                    <div className="absolute inset-0 border-[6px] border-emerald-500/10 border-t-emerald-500 rounded-full animate-spin"></div>
                    <div className="text-5xl text-emerald-600 dark:text-emerald-400 animate-pulse">
                      {loginSequence === 'AUTHENTICATING' && <i className="fas fa-fingerprint"></i>}
                      {loginSequence === 'CLOCK' && <i className="fas fa-clock"></i>}
                      {loginSequence === 'CURRENCY' && <i className="fas fa-sack-dollar"></i>}
                    </div>
                  </div>
                  <div className="text-center">
                    <p className="text-xs font-black uppercase tracking-[0.4em] text-emerald-800 dark:text-emerald-400">
                      {loginSequence === 'AUTHENTICATING' && "Verifying Bio-Identity"}
                      {loginSequence === 'CLOCK' && "Calculating Market Time"}
                      {loginSequence === 'CURRENCY' && "Allocating Liquid Capital"}
                    </p>
                    <p className="text-[9px] font-bold text-gray-400 dark:text-gray-600 uppercase tracking-widest mt-3">DO NOT REFRESH SESSION</p>
                  </div>
                </div>
              ) : (
                <form onSubmit={handleInitialLogin} className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Email Identity</label>
                    <input name="email" type="email" placeholder="Enter your email address" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4 tracking-widest">Full Legal Name</label>
                    <input name="name" placeholder="Enter your full legal name" required className="w-full bg-gray-50 dark:bg-slate-800 dark:text-white p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 transition-all font-bold" />
                  </div>
                  {loginError && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{loginError}</p>}
                  <button className="w-full py-6 mt-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-emerald-950 shadow-2xl transition-all active:scale-95">Open Secure Vault</button>
                </form>
              )}
            </div>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={toggleTheme}>

      {/* Update Available Notification */}
      {updateAvailable && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[9000] w-[90%] max-w-md bg-emerald-950 text-white p-4 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] border-2 border-orange-500/50 flex items-center justify-between gap-4 animate-slideDown">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-orange-600 rounded-xl flex items-center justify-center animate-pulse">
              <i className="fas fa-cloud-arrow-down"></i>
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-orange-400">Update Available</p>
              <p className="text-[9px] font-bold text-gray-300">A new version of KwachaTime is ready.</p>
            </div>
          </div>
          <button 
            onClick={handleRefreshApp}
            className="px-6 py-3 bg-white text-emerald-950 rounded-xl text-[10px] font-black uppercase hover:bg-orange-500 hover:text-white transition-all shadow-lg"
          >
            Update Now
          </button>
        </div>
      )}

      <CurrencyConverter />
      {showTour && <OnboardingTour role={currentUser.role} onComplete={() => {
        localStorage.setItem(`kwachatime_tour_done_${currentUser.id}`, 'true');
        setShowTour(false);
