      email: email,
      nrc: 'N/A',
      phone: 'N/A',
      address: 'N/A',
      operator: 'Airtel',
      role: role,
      joinedAt: new Date().toISOString(),
      walletBalance: 0
    };

    await apiService.syncUser(userData);
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 1000));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 1000));

    setCurrentUser(userData);
    localStorage.setItem('kwachatime_user', JSON.stringify(userData));
    setLoginSequence('IDLE');
