                <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-xs font-black uppercase tracking-widest text-emerald-600">{loginSequence}</p>
              </div>
            ) : (
              <form onSubmit={handleInitialLogin} className="space-y-4 mt-8">
