          <p className="text-[10px] font-black uppercase tracking-widest">Update Ready</p>
          <button onClick={() => window.location.reload()} className="px-6 py-2 bg-white text-emerald-950 rounded-xl text-[10px] font-black uppercase">Refresh</button>
        </div>
