            <div className="bg-slate-900 text-white p-8 rounded-[3rem] mb-6">
               <p className="text-[10px] font-black uppercase text-emerald-400 mb-1">Vault Status</p>
               <p className="text-2xl font-black">{formatCurrency(vaultBalance)}</p>
