                      <div key={m.id} className="p-6 bg-gray-50 dark:bg-slate-800 rounded-3xl">
                        <p className="text-[10px] font-black uppercase text-emerald-600 mb-1">To: {m.recipientName}</p>
                        <p className="text-xs font-black">{m.subject}</p>
                        <p className="text-[9px] text-gray-400 mt-2">{new Date(m.timestamp).toLocaleString()}</p>
                      </div>
                    ))}
                 </div>
              </div>
            )}

            {activeAdminTab === 'LOGS' && (
              <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl">
                 <h3 className="text-xl font-black uppercase mb-8">System Audit Logs</h3>
                 <div className="space-y-4 max-h-[500px] overflow-y-auto">
                    {auditLogs.map(log => (
                      <div key={log.id} className="p-4 border-l-4 border-emerald-500 bg-gray-50 dark:bg-slate-800 rounded-r-xl">
