        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 animate-fadeIn">
           <div className="lg:col-span-1 space-y-10">
              <Roadmap />
              <OfficeLocator />
              <div className="text-center py-4">
                 <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">v{APP_VERSION}</p>
              </div>
           </div>

           <div className="lg:col-span-2 space-y-10">
              <div className="bg-emerald-950 text-white p-10 rounded-[4rem] shadow-2xl relative overflow-hidden">
                 <p className="text-[11px] font-black uppercase text-emerald-500 mb-3">Wallet Balance</p>
                 <p className="text-5xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
              </div>

              <div className="space-y-6">
                 <h3 className="text-xs font-black uppercase text-gray-400 pl-4 tracking-widest">Active Timeline</h3>
                 {allLoans.map(loan => (
                    <div key={loan.id} className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] shadow-xl border-2 border-gray-50 dark:border-slate-800">
                       <div className="flex justify-between items-start mb-8">
                          <div>
                             <p className="text-[9px] font-black uppercase text-gray-400">ID: {loan.id}</p>
                             <h4 className="text-2xl font-black">{formatCurrency(loan.principal)}</h4>
                          </div>
                          <div className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-600'}`}>
                             {loan.status}
                          </div>
                       </div>
                       <div className="pl-4 border-l-2 border-emerald-100 space-y-8">
                          {loan.statusHistory?.map((step, idx) => (
                             <div key={idx} className="relative">
                                <div className="absolute -left-[21px] top-1 w-4 h-4 bg-emerald-500 rounded-full border-4 border-white dark:border-slate-900 shadow-sm"></div>
                                <p className="text-[9px] font-black uppercase text-emerald-600">{step.status}</p>
                                <p className="text-[10px] text-gray-400 font-medium">{step.message}</p>
                                <p className="text-[8px] font-mono text-gray-300 mt-1">{new Date(step.timestamp).toLocaleTimeString()}</p>
                             </div>
                          ))}
                       </div>
                    </div>
                 ))}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: data.principal,
                   purpose: data.purpose,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, AuditLog, Transaction, OutgoingEmail } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import LegalDocumentModal from './components/LegalDocumentModal';
import OperationalManual from './components/OperationalManual';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const APP_VERSION = "1.0.5-Legal";

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [outgoingEmails, setOutgoingEmails] = useState<OutgoingEmail[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [updateAvailable, setUpdateAvailable] = useState(false);

  const [activeLegalDoc, setActiveLegalDoc] = useState<{ loan: Loan; type: 'AGREEMENT' | 'LETTER_OF_SALE' } | null>(null);
  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');
  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'USERS' | 'LOGS' | 'COMMS'>('MONITOR');

  const [adjAmount, setAdjAmount] = useState('');
  const [adjReason, setAdjReason] = useState('');

  useEffect(() => {
    const root = document.documentElement;
    const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;
    if (effectiveTheme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
    localStorage.setItem('theme-mode', themeMode);
  }, [themeMode]);

  useEffect(() => {
    const handleUpdate = () => setUpdateAvailable(true);
    window.addEventListener('pwa-update-available', handleUpdate);
    return () => window.removeEventListener('pwa-update-available', handleUpdate);
  }, []);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setAuditLogs(stats.auditLogs);
        setOutgoingEmails(stats.outgoingEmails);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Refresh failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();

    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    const role: UserRole = adminEmails.includes(email) ? 'ADMIN' : 'BORROWER';

    const response = await apiService.authenticate(email);
    const userData: User = response.user || {
      id: Math.random().toString(36).substr(2, 9),
      name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
      email: email,
      nrc: 'N/A',
      phone: 'N/A',
      address: 'N/A',
      operator: 'Airtel',
      role: role,
      joinedAt: new Date().toISOString(),
      walletBalance: 0
    };

    await apiService.syncUser(userData);
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 800));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 800));

    setCurrentUser(userData);
    localStorage.setItem('kwachatime_user', JSON.stringify(userData));
    setLoginSequence('IDLE');
  };

  const handleManualStatusUpdate = async (loanId: string, status: Loan['status']) => {
    setIsProcessing(true);
    try {
      if (status === 'DISBURSED') {
        await apiService.disburseLoan(loanId);
      } else {
        await apiService.updateLoanStatus(loanId, status);
      }
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  const handleVaultAdjustment = async (isAddition: boolean) => {
    if (!adjAmount || !adjReason) return;
    setIsProcessing(true);
    await apiService.adjustCapital(parseFloat(adjAmount) * (isAddition ? 1 : -1), adjReason);
    setAdjAmount(''); setAdjReason('');
    await refreshData();
    setIsProcessing(false);
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[80vh] p-4">
          <div className="w-full max-w-md bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-800 text-center">
            <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2rem] flex items-center justify-center mx-auto mb-6">
               <i className="fas fa-landmark text-3xl"></i>
            </div>
            <h2 className="text-3xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Kwacha Gate</h2>
            {loginSequence !== 'IDLE' ? (
              <div className="py-12 flex flex-col items-center gap-6">
                <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-xs font-black uppercase tracking-widest text-emerald-600">{loginSequence}</p>
              </div>
            ) : (
              <form onSubmit={handleInitialLogin} className="space-y-4 mt-8">
                <input name="email" type="email" placeholder="Email Address" required className="w-full bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                <input name="name" placeholder="Full Legal Name" required className="w-full bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                <button className="w-full py-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest">Enter Secure Vault</button>
              </form>
            )}
            <p className="mt-8 text-[9px] font-black text-gray-300 uppercase tracking-widest">Build {APP_VERSION}</p>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={() => setThemeMode(themeMode === 'light' ? 'dark' : 'light')}>

      {/* Legal Document Modal */}
      {activeLegalDoc && (
        <LegalDocumentModal 
          user={allUsers.find(u => u.id === activeLegalDoc.loan.userId) || currentUser}
          loan={activeLegalDoc.loan}
          type={activeLegalDoc.type}
          onClose={() => setActiveLegalDoc(null)}
        />
      )}

      {isAdmin ? (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 animate-fadeIn">
          <div className="lg:col-span-1 space-y-4">
            <div className="bg-slate-900 text-white p-8 rounded-[3rem] mb-6">
               <p className="text-[10px] font-black uppercase text-emerald-400 mb-1">Vault Status</p>
               <p className="text-2xl font-black">{formatCurrency(vaultBalance)}</p>
            </div>
            {[
              { id: 'MONITOR', icon: 'fa-chart-pie', label: 'Monitor' },
              { id: 'PENDING', icon: 'fa-shield-halved', label: 'Approvals' },
              { id: 'USERS', icon: 'fa-users-line', label: 'Ledger' },
              { id: 'COMMS', icon: 'fa-envelope-open-text', label: 'Emails' },
              { id: 'LOGS', icon: 'fa-list-check', label: 'Audit Logs' }
            ].map(tab => (
              <button 
                key={tab.id} 
                onClick={() => setActiveAdminTab(tab.id as any)}
                className={`w-full flex items-center gap-4 p-6 rounded-3xl text-[11px] font-black uppercase transition-all ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white' : 'bg-white dark:bg-slate-900 text-gray-400 border border-transparent hover:bg-gray-100 dark:hover:bg-slate-800'}`}
              >
                <i className={`fas ${tab.icon} w-6`}></i>
                {tab.label}
              </button>
            ))}
          </div>

          <div className="lg:col-span-3">
            {activeAdminTab === 'MONITOR' && (
              <div className="space-y-8">
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl">
                  <h3 className="text-xl font-black uppercase tracking-tighter mb-8">Vault Controls</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                     <input type="number" placeholder="ZMW Amount" value={adjAmount} onChange={(e) => setAdjAmount(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                     <input type="text" placeholder="Reason" value={adjReason} onChange={(e) => setAdjReason(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                  </div>
                  <div className="grid grid-cols-2 gap-6">
                     <button onClick={() => handleVaultAdjustment(true)} className="py-6 bg-emerald-600 text-white rounded-3xl font-black uppercase tracking-widest">Deposit</button>
                     <button onClick={() => handleVaultAdjustment(false)} className="py-6 bg-red-600 text-white rounded-3xl font-black uppercase tracking-widest">Withdraw</button>
                  </div>
                </div>
              </div>
            )}

            {activeAdminTab === 'PENDING' && (
              <div className="space-y-6">
                {allLoans.filter(l => l.status === 'PENDING').length === 0 ? (
                  <div className="p-20 text-center bg-gray-50 dark:bg-slate-900 rounded-[3.5rem] text-gray-400 uppercase font-black tracking-widest">No Pending Applications</div>
                ) : (
                  allLoans.filter(l => l.status === 'PENDING').map(loan => (
                    <div key={loan.id} className="bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] shadow-xl">
                       <div className="flex justify-between items-start mb-6">
                          <div>
                            <p className="text-[10px] font-black uppercase text-emerald-600">Ref: {loan.id}</p>
                            <h4 className="text-xl font-black">{loan.userName}</h4>
                            <p className="text-2xl font-black mt-1">{formatCurrency(loan.principal)}</p>
                          </div>
                          <div className="flex flex-col gap-2">
                             <button onClick={() => setActiveLegalDoc({ loan, type: 'AGREEMENT' })} className="px-4 py-2 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-xl text-[9px] font-black uppercase hover:bg-slate-200 transition-all">
                               Agreement
                             </button>
                             {loan.collateralType !== 'NONE' && (
                               <button onClick={() => setActiveLegalDoc({ loan, type: 'LETTER_OF_SALE' })} className="px-4 py-2 bg-orange-50 dark:bg-orange-900/20 text-orange-600 dark:text-orange-400 rounded-xl text-[9px] font-black uppercase hover:bg-orange-100 transition-all">
                                 Sale Letter
                               </button>
                             )}
                          </div>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'APPROVED')} className="flex-1 py-4 bg-emerald-800 text-white rounded-2xl font-black uppercase text-[10px]">Approve</button>
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'REJECTED')} className="flex-1 py-4 bg-red-800 text-white rounded-2xl font-black uppercase text-[10px]">Reject</button>
                       </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {activeAdminTab === 'USERS' && (
              <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl">
                 <h3 className="text-xl font-black uppercase mb-8">Registered Clients</h3>
                 <div className="divide-y divide-gray-100 dark:divide-slate-800">
                    {allUsers.map(u => (
                      <div key={u.id} className="py-6 flex justify-between items-center">
                        <div>
                          <p className="font-black">{u.name}</p>
                          <p className="text-[10px] text-gray-400 uppercase">{u.email}</p>
                        </div>
                        <p className="font-black text-emerald-600">{formatCurrency(u.walletBalance || 0)}</p>
                      </div>
                    ))}
                 </div>
              </div>
            )}

            {activeAdminTab === 'COMMS' && (
              <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl">
                 <h3 className="text-xl font-black uppercase mb-8">AI Notification Ledger</h3>
                 <div className="space-y-6">
                    {outgoingEmails.length === 0 ? <p className="text-gray-400 uppercase font-black text-center">No Emails Sent Yet</p> : outgoingEmails.map(m => (
                      <div key={m.id} className="p-6 bg-gray-50 dark:bg-slate-800 rounded-3xl">
                        <p className="text-[10px] font-black uppercase text-emerald-600 mb-1">To: {m.recipientName}</p>
                        <p className="text-xs font-black">{m.subject}</p>
                        <p className="text-[9px] text-gray-400 mt-2">{new Date(m.timestamp).toLocaleString()}</p>
                      </div>
                    ))}
                 </div>
              </div>
            )}

            {activeAdminTab === 'LOGS' && (
              <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-xl">
                 <h3 className="text-xl font-black uppercase mb-8">System Audit Logs</h3>
                 <div className="space-y-4 max-h-[500px] overflow-y-auto pr-4">
                    {auditLogs.map(log => (
                      <div key={log.id} className="p-4 border-l-4 border-emerald-500 bg-gray-50 dark:bg-slate-800 rounded-r-xl">
                        <p className="text-[10px] font-black uppercase">{log.action}</p>
                        <p className="text-[11px] text-gray-500">{log.details}</p>
                        <p className="text-[8px] font-mono mt-1">{new Date(log.timestamp).toLocaleTimeString()}</p>
                      </div>
                    ))}
                 </div>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 animate-fadeIn">
           <div className="lg:col-span-1 space-y-10">
              <Roadmap />
              <OfficeLocator />
              <div className="text-center py-4">
                 <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">v{APP_VERSION}</p>
              </div>
           </div>

           <div className="lg:col-span-2 space-y-10">
              <div className="bg-emerald-950 text-white p-10 rounded-[4rem] shadow-2xl relative overflow-hidden">
                 <p className="text-[11px] font-black uppercase text-emerald-500 mb-3">Wallet Balance</p>
                 <p className="text-5xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
              </div>

              <div className="space-y-6">
                 <h3 className="text-xs font-black uppercase text-gray-400 pl-4 tracking-widest">Active Timeline</h3>
                 {allLoans.map(loan => (
                    <div key={loan.id} className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] shadow-xl border-2 border-gray-50 dark:border-slate-800">
                       <div className="flex justify-between items-start mb-8">
                          <div>
                             <p className="text-[9px] font-black uppercase text-gray-400">ID: {loan.id}</p>
                             <h4 className="text-2xl font-black">{formatCurrency(loan.principal)}</h4>
                          </div>
                          <div className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-600'}`}>
                             {loan.status}
                          </div>
                       </div>
                       <div className="pl-4 border-l-2 border-emerald-100 space-y-8">
                          {loan.statusHistory?.map((step, idx) => (
                             <div key={idx} className="relative">
                                <div className="absolute -left-[21px] top-1 w-4 h-4 bg-emerald-500 rounded-full border-4 border-white dark:border-slate-900 shadow-sm"></div>
                                <p className="text-[9px] font-black uppercase text-emerald-600">{step.status}</p>
                                <p className="text-[10px] text-gray-400 font-medium">{step.message}</p>
                                <p className="text-[8px] font-mono text-gray-300 mt-1">{new Date(step.timestamp).toLocaleTimeString()}</p>
                             </div>
                          ))}
                       </div>
                    </div>
                 ))}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: data.principal,
                   purpose: data.purpose,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
                   collateralType: data.collateralType,
                   collateralValue: data.collateralValue
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
      <CurrencyConverter />
    </Layout>
  );
};

export default App;

export type MobileOperator = 'Airtel' | 'MTN' | 'Zamtel';
export type UserRole = 'BORROWER' | 'ADMIN' | 'DEVELOPER';
export type CollateralType = 'LAPTOP' | 'PHONE' | 'CAR' | 'APPLIANCE' | 'OTHER' | 'NONE';
export type TravelMode = 'walking' | 'cycling' | 'driving';
export type ThemeMode = 'light' | 'dark' | 'system';

export interface Location {
  lat: number;
  lng: number;
  timestamp: string;
}

export interface StatusUpdate {
  status: Loan['status'];
  timestamp: string;
  message: string;
}

export interface OutgoingEmail {
  id: string;
  recipientEmail: string;
  recipientName: string;
  subject: string;
  body: string;
  status: 'SENT' | 'FAILED' | 'DRAFTING';
  timestamp: string;
  loanId: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  nrc: string;
  phone: string;
  address: string;
  operator: MobileOperator;
  role: UserRole;
  joinedAt: string;
  walletBalance?: number;
  trustScore?: number; // 0-100
  currentLocation?: Location;
}

export interface Transaction {
  id: string;
  loanId?: string;
  userId?: string;
  userName?: string;
  amount: number;
  type: 'DISBURSEMENT' | 'REPAYMENT' | 'FEE' | 'WALLET_WITHDRAW' | 'WALLET_DEPOSIT';
  timestamp: string;
