import React, { useState, useRef, useMemo, useEffect } from 'react';
import { CollateralType } from '../types';
import { analyzeSafetyPhoto } from '../services/geminiService';
import { formatCurrency } from '../utils/loanCalculator';

interface LoanFormProps {
  onSubmit: (loanData: { 
    principal: number; 
    purpose: string; 
    collateral: File | null;
    collateralType: CollateralType;
    collateralDescription: string;
  }) => void;
  isLoading: boolean;
}

const COLLATERAL_DATA: Record<CollateralType, { label: string; icon: string }> = {
  PHONE: { label: 'Phone', icon: 'fa-mobile-screen' },
  LAPTOP: { label: 'PC / Laptop', icon: 'fa-laptop' },
  CAR: { label: 'Vehicle', icon: 'fa-car' },
  APPLIANCE: { label: 'Appliance', icon: 'fa-plug' },
  OTHER: { label: 'Other', icon: 'fa-ellipsis' },
  NONE: { label: 'None', icon: 'fa-ban' }
};

const LoanForm: React.FC<LoanFormProps> = ({ onSubmit, isLoading }) => {
  const [amount, setAmount] = useState<string>('');
  const [purpose, setPurpose] = useState<string>('');
  const [photo, setPhoto] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [selectedCollateral, setSelectedCollateral] = useState<CollateralType>('NONE');
  const [otherDesc, setOtherDesc] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsAnalyzing(true);
      setError(null);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        const result = await analyzeSafetyPhoto(base64);
        if (!result.isValid) {
          setError(result.reason);
          setPhoto(null);
        } else {
          setPhoto(file);
        }
        setIsAnalyzing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || selectedCollateral === 'NONE' || !photo) {
      setError("Please complete all steps including identity verification.");
      return;
    }
    if (selectedCollateral === 'OTHER' && !otherDesc) {
      setError("Please describe the 'Other' collateral.");
      return;
    }
    onSubmit({ 
      principal: parseFloat(amount), 
      purpose, 
      collateral: photo,
      collateralType: selectedCollateral,
      collateralDescription: selectedCollateral === 'OTHER' ? otherDesc : COLLATERAL_DATA[selectedCollateral].label
    });
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl p-8 border border-gray-100 dark:border-slate-700 max-w-md mx-auto animate-fadeIn transition-colors">

      {/* Physical Handout Alert */}
      <div className="mb-8 p-4 bg-orange-50 dark:bg-orange-950/30 border border-orange-200 dark:border-orange-800 rounded-3xl flex gap-4 animate-pulse">
        <div className="w-10 h-10 bg-orange-500 text-white rounded-2xl flex items-center justify-center shrink-0 shadow-lg">
          <i className="fas fa-handshake"></i>
        </div>
        <div>
          <p className="text-[10px] font-black uppercase text-orange-900 dark:text-orange-400 leading-none mb-1">Operational Notice</p>
          <p className="text-[11px] text-orange-800 dark:text-orange-300 font-medium">Physical hand-to-hand disbursement only. Loans are collected in person at our Lusaka branch.</p>
        </div>
      </div>

      <h2 className="text-2xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter mb-8">Secure Application</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400 dark:text-gray-500">Step 1: Choose Collateral</label>
          <div className="grid grid-cols-3 gap-3">
            {(Object.keys(COLLATERAL_DATA) as CollateralType[]).filter(k => k !== 'NONE').map(key => (
              <button
                key={key}
                type="button"
                onClick={() => {
                  setSelectedCollateral(key);
                  setError(null);
                }}
                className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${selectedCollateral === key ? 'bg-emerald-800 border-emerald-800 text-white shadow-lg' : 'bg-gray-50 dark:bg-slate-900 border-gray-100 dark:border-slate-700 text-gray-400'}`}
              >
                <i className={`fas ${COLLATERAL_DATA[key].icon} text-lg mb-1`}></i>
                <span className="text-[9px] font-black uppercase">{COLLATERAL_DATA[key].label}</span>
              </button>
            ))}
          </div>

          {selectedCollateral === 'OTHER' && (
            <input 
              type="text" 
              value={otherDesc}
              onChange={(e) => setOtherDesc(e.target.value)}
              placeholder="Specify item (e.g. Fridge, TV, Solar Panel)"
              className="w-full bg-gray-50 dark:bg-slate-900 dark:text-white border-2 border-emerald-100 dark:border-emerald-900 p-4 rounded-2xl text-[11px] font-bold outline-none focus:border-emerald-500 transition-all animate-slideDown"
            />
          )}
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400 dark:text-gray-500">Step 2: Capital Details</label>
          <div className="space-y-3">
            <div className="relative">
              <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-emerald-800 dark:text-emerald-400">K</span>
              <input 
                type="number" 
                value={amount} 
                onChange={(e) => {
                  setAmount(e.target.value);
                  setError(null);
                }} 
                className={`w-full bg-gray-50 dark:bg-slate-900 dark:text-white border-2 border-gray-100 dark:border-slate-700 p-5 pl-10 rounded-2xl text-xl font-black outline-none focus:border-emerald-500 transition-all`} 
                placeholder="0.00" 
              />
            </div>
            <input 
              type="text" 
              value={purpose} 
              onChange={(e) => setPurpose(e.target.value)} 
              className="w-full bg-gray-50 dark:bg-slate-900 dark:text-white border-2 border-gray-100 dark:border-slate-700 p-5 rounded-2xl text-xs font-bold outline-none focus:border-emerald-500" 
              placeholder="Purpose of Loan" 
            />
          </div>
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase text-gray-400 dark:text-gray-500">Step 3: Identity Verification</label>
          <div 
            onClick={() => fileInputRef.current?.click()} 
            className="group relative h-28 rounded-3xl border-2 border-dashed border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-900 flex flex-col items-center justify-center cursor-pointer hover:border-emerald-500 transition-all overflow-hidden"
          >
            {previewUrl ? (
              <img src={previewUrl} className="w-full h-full object-cover" alt="Verification" />
            ) : (
              <>
                <i className="fas fa-camera text-xl text-gray-300 group-hover:text-emerald-500 mb-1"></i>
                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Verify Identity</span>
              </>
            )}
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
          </div>
        </div>

        {error && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{error}</p>}

        <button 
          type="submit" 
          disabled={isLoading || isAnalyzing} 
          className="w-full bg-emerald-800 text-white py-6 rounded-[2rem] font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 disabled:opacity-50"
        >
          {isAnalyzing ? "Verifying..." : isLoading ? "Submitting..." : "Apply Now"}
        </button>
      </form>
    </div>
  );
};

export default LoanForm;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, AuditLog, Transaction, OutgoingEmail } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import LegalDocumentModal from './components/LegalDocumentModal';
import OperationalManual from './components/OperationalManual';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const APP_VERSION = "1.0.6-Simulation";

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [outgoingEmails, setOutgoingEmails] = useState<OutgoingEmail[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [updateAvailable, setUpdateAvailable] = useState(false);

  const [activeLegalDoc, setActiveLegalDoc] = useState<{ loan: Loan; type: 'AGREEMENT' | 'LETTER_OF_SALE' } | null>(null);
  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');
  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'USERS' | 'SIMULATE' | 'LOGS' | 'COMMS'>('MONITOR');

  const [adjAmount, setAdjAmount] = useState('');
  const [adjReason, setAdjReason] = useState('');
  const [simName, setSimName] = useState('');
  const [simPrincipal, setSimPrincipal] = useState('');

  useEffect(() => {
    const root = document.documentElement;
    const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;
    if (effectiveTheme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
    localStorage.setItem('theme-mode', themeMode);
  }, [themeMode]);

  useEffect(() => {
    const handleUpdate = () => setUpdateAvailable(true);
    window.addEventListener('pwa-update-available', handleUpdate);
    return () => window.removeEventListener('pwa-update-available', handleUpdate);
  }, []);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setAuditLogs(stats.auditLogs);
        setOutgoingEmails(stats.outgoingEmails);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Refresh failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginError(null);
    setLoginSequence('AUTHENTICATING');
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();

    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    const role: UserRole = adminEmails.includes(email) ? 'ADMIN' : 'BORROWER';

    const response = await apiService.authenticate(email);
    const userData: User = response.user || {
      id: Math.random().toString(36).substr(2, 9),
      name: (formData.get('name') as string) || (role === 'ADMIN' ? 'Kwacha Admin' : "Client"),
      email: email,
      nrc: (formData.get('nrc') as string) || 'N/A',
      phone: (formData.get('phone') as string) || 'N/A',
      address: (formData.get('address') as string) || 'N/A',
      operator: 'Airtel',
      role: role,
      joinedAt: new Date().toISOString(),
      walletBalance: 0
    };

    await apiService.syncUser(userData);
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 600));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 600));

    setCurrentUser(userData);
    localStorage.setItem('kwachatime_user', JSON.stringify(userData));
    setLoginSequence('IDLE');
  };

  const handleManualStatusUpdate = async (loanId: string, status: Loan['status']) => {
    setIsProcessing(true);
    try {
      if (status === 'DISBURSED') {
        await apiService.disburseLoan(loanId);
      } else {
        await apiService.updateLoanStatus(loanId, status);
      }
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  const handleSimulation = async () => {
    if (!simName || !simPrincipal) return;
    setIsProcessing(true);
    await apiService.simulateLoan({
      name: simName,
      principal: parseFloat(simPrincipal),
      disbursedDate: new Date().toISOString(),
      dueDate: new Date(Date.now() + 14 * 86400000).toISOString()
    });
    setSimName(''); setSimPrincipal('');
    await refreshData();
    setIsProcessing(false);
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-[80vh] p-4">
          <div className="w-full max-w-md bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-slate-800 text-center">
            <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2rem] flex items-center justify-center mx-auto mb-6">
               <i className="fas fa-landmark text-3xl"></i>
            </div>
            <h2 className="text-3xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Vault Entry</h2>
            {loginSequence !== 'IDLE' ? (
              <div className="py-12 flex flex-col items-center gap-6">
                <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-xs font-black uppercase tracking-widest text-emerald-600">{loginSequence}</p>
              </div>
            ) : (
              <form onSubmit={handleInitialLogin} className="space-y-4 mt-8">
                <input name="email" type="email" placeholder="Email Address" required className="w-full bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                <input name="name" placeholder="Full Legal Name" required className="w-full bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                <div className="grid grid-cols-2 gap-4">
                  <input name="nrc" placeholder="NRC (000000/00/0)" required className="w-full bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs" />
                  <input name="phone" placeholder="Phone" required className="w-full bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs" />
                </div>
                <input name="address" placeholder="Residential Address" required className="w-full bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                <button className="w-full py-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest">Enter Secure Vault</button>
              </form>
            )}
            <p className="mt-8 text-[9px] font-black text-gray-300 uppercase tracking-widest">v{APP_VERSION}</p>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={() => setThemeMode(themeMode === 'light' ? 'dark' : 'light')}>

      {activeLegalDoc && (
        <LegalDocumentModal 
          user={allUsers.find(u => u.id === activeLegalDoc.loan.userId) || currentUser}
          loan={activeLegalDoc.loan}
          type={activeLegalDoc.type}
          onClose={() => setActiveLegalDoc(null)}
        />
      )}

      {isAdmin ? (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 animate-fadeIn">
          <div className="lg:col-span-1 space-y-4">
            <div className="bg-slate-900 text-white p-8 rounded-[3rem] mb-6">
               <p className="text-[10px] font-black uppercase text-emerald-400 mb-1">Vault Status</p>
               <p className="text-2xl font-black">{formatCurrency(vaultBalance)}</p>
            </div>
            {[
              { id: 'MONITOR', icon: 'fa-chart-pie', label: 'Monitor' },
              { id: 'PENDING', icon: 'fa-shield-halved', label: 'Approvals' },
              { id: 'USERS', icon: 'fa-users-line', label: 'Ledger' },
              { id: 'SIMULATE', icon: 'fa-vial-circle-check', label: 'Simulation' },
              { id: 'LOGS', icon: 'fa-list-check', label: 'Audit Logs' }
            ].map(tab => (
              <button 
