                 <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">Build {APP_VERSION}</p>
              </div>
           </div>

           <div className="lg:col-span-2 space-y-10">
              <div className="bg-emerald-950 text-white p-10 rounded-[4rem] shadow-2xl relative overflow-hidden">
                 <p className="text-[11px] font-black uppercase text-emerald-500 mb-3">Ledger Balance</p>
                 <p className="text-5xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
              </div>

              <div className="space-y-6">
                 <h3 className="text-xs font-black uppercase text-gray-400 pl-4 tracking-widest">Active Requests</h3>
                 {allLoans.map(loan => (
                    <div key={loan.id} className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] shadow-xl border-2 border-gray-50 dark:border-slate-800">
                       <div className="flex justify-between items-start">
                          <div>
                             <p className="text-[9px] font-black uppercase text-gray-400">ID: {loan.id}</p>
                             <h4 className="text-2xl font-black">{formatCurrency(loan.principal)}</h4>
                             <p className="text-[9px] font-bold text-emerald-600 mt-1 uppercase">Item: {loan.collateralDescription}</p>
                          </div>
                          <div className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-600'}`}>
                             {loan.status}
                          </div>
                       </div>
                    </div>
                 ))}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: data.principal,
                   purpose: data.purpose,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 86400000).toISOString(),
                   collateralType: data.collateralType,
                   collateralDescription: data.collateralDescription
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
      <CurrencyConverter />
    </Layout>
  );
};

