                      <input name="phone" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Residential Address</label>
                      <input name="address" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Employment / Business</label>
                      <input name="employment" className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Emergency Contact (Next of Kin)</label>
                      <input name="nok_name" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                </div>
                <button className="w-full py-6 bg-emerald-800 text-white rounded-[2.5rem] font-black uppercase tracking-widest mt-6 shadow-2xl transition-all active:scale-95">Verify & Enter Vault</button>
              </form>
