                          <p className="text-[10px] text-emerald-600 font-bold uppercase">NRC: {u.nrc} • {u.phone}</p>
                          <p className="text-[9px] text-gray-400 italic mt-1">{u.address}</p>
                        </div>
                        <div className="text-right">
                           <p className="text-[9px] font-black text-gray-400 uppercase">Trust Score</p>
                           <p className="text-xl font-black text-emerald-800">{u.trustScore || 50}%</p>
                        </div>
                      </div>
                    ))}
                 </div>
              </div>
            )}
          </div>
        </div>
      ) : (
        /* Borrower Dashboard */
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
           <div className="lg:col-span-1 space-y-12">
              <Roadmap />
              <OfficeLocator />
              <div className="text-center p-10 bg-white dark:bg-slate-900 rounded-[3rem] shadow-xl">
                 <p className="text-[10px] font-black uppercase text-gray-400 mb-2">Legal Compliance</p>
                 <p className="text-[11px] font-medium leading-relaxed text-gray-500">
                   All applications are processed in accordance with the Zambian Banking and Financial Services Act.
                 </p>
              </div>
           </div>

           <div className="lg:col-span-2 space-y-12">
              <div className="bg-emerald-950 text-white p-12 rounded-[4.5rem] shadow-2xl relative overflow-hidden flex justify-between items-end border border-emerald-900">
                 <div>
                    <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-widest">Digital Ledger Balance</p>
                    <p className="text-6xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 </div>
                 <div className="w-16 h-16 bg-white/10 rounded-3xl flex items-center justify-center text-3xl">
                    <i className="fas fa-money-bill-transfer"></i>
                 </div>
              </div>

              <div className="space-y-6">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 pl-6 tracking-[0.3em]">Active Financial Timeline</h3>
                 {allLoans.length === 0 ? (
                   <div className="p-20 text-center bg-gray-50 dark:bg-slate-900 rounded-[3.5rem] text-gray-300 font-black uppercase tracking-widest border-2 border-dashed">No Active Loans</div>
                 ) : (
                   allLoans.map(loan => (
                    <div key={loan.id} className="p-10 bg-white dark:bg-slate-900 rounded-[4rem] shadow-xl border-2 border-gray-50 dark:border-slate-800 animate-slideUp">
                       <div className="flex justify-between items-start">
                          <div>
                             <p className="text-[10px] font-black uppercase text-gray-400 mb-1">ID: {loan.id}</p>
                             <h4 className="text-3xl font-black">{formatCurrency(loan.principal)}</h4>
                             <div className="flex gap-4 mt-3">
                                <span className="px-3 py-1 bg-emerald-50 text-emerald-800 rounded-lg text-[9px] font-black uppercase">Collateral: {loan.collateralDescription}</span>
                                <span className="px-3 py-1 bg-emerald-50 text-emerald-800 rounded-lg text-[9px] font-black uppercase">Term: {loan.tenure}</span>
                             </div>
                          </div>
                          <div className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase shadow-lg text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-700'}`}>
                             {loan.status}
                          </div>
                       </div>
                    </div>
                   ))
                 )}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: data.principal,
                   purpose: data.purpose,
                   tenure: data.tenure,
                   repaymentMethod: data.repaymentMethod,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 86400000).toISOString(),
                   collateralType: data.collateralType,
                   collateralDescription: data.collateralDescription,
                   collateralSerial: data.collateralSerial,
                   collateralCondition: data.collateralCondition,
                   collateralLocation: data.collateralLocation,
                   hasAgreedToOwnership: data.hasAgreedToOwnership,
                   hasAgreedToVerification: data.hasAgreedToVerification
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
      <CurrencyConverter />
    </Layout>
  );
};

export default App;

import { User, Loan, Transaction, AppNotification, AuditLog, Location, TravelMode, MobileOperator, OutgoingEmail, StatusUpdate } from './types';

class VirtualBackend {
  private users: User[] = [];
  private loans: Loan[] = [];
  private transactions: Transaction[] = [];
  private auditLogs: AuditLog[] = [];
  private notifications: AppNotification[] = [];
  private outgoingEmails: OutgoingEmail[] = [];
  private vaultBalance: number = 750000;

  constructor() {
    this.loadFromStorage();
  }

  private loadFromStorage() {
    const data = localStorage.getItem('kwachatime_db');
    if (data) {
      try {
        const parsed = JSON.parse(data);
        this.users = parsed.users || [];
        this.loans = parsed.loans || [];
        this.transactions = parsed.transactions || [];
        this.auditLogs = parsed.auditLogs || [];
        this.notifications = parsed.notifications || [];
        this.outgoingEmails = parsed.outgoingEmails || [];
