import { User, Loan, Transaction, AppNotification, AuditLog, Location, TravelMode, MobileOperator, OutgoingEmail, StatusUpdate } from './types';

class VirtualBackend {
  private users: User[] = [];
  private loans: Loan[] = [];
  private transactions: Transaction[] = [];
  private auditLogs: AuditLog[] = [];
  private notifications: AppNotification[] = [];
  private outgoingEmails: OutgoingEmail[] = [];
  private vaultBalance: number = 750000;

  constructor() {
    this.loadFromStorage();
  }

  private loadFromStorage() {
    const data = localStorage.getItem('kwachatime_db');
    if (data) {
      try {
        const parsed = JSON.parse(data);
        this.users = parsed.users || [];
        this.loans = parsed.loans || [];
        this.transactions = parsed.transactions || [];
        this.auditLogs = parsed.auditLogs || [];
        this.notifications = parsed.notifications || [];
        this.outgoingEmails = parsed.outgoingEmails || [];
        this.vaultBalance = parsed.vaultBalance ?? 750000;
      } catch (e) {
        console.error("Failed to parse storage", e);
      }
    }
  }

  private saveToStorage() {
    const data = {
      users: this.users,
      loans: this.loans,
      transactions: this.transactions,
      auditLogs: this.auditLogs,
      notifications: this.notifications,
      outgoingEmails: this.outgoingEmails,
      vaultBalance: this.vaultBalance
    };
    localStorage.setItem('kwachatime_db', JSON.stringify(data));
  }

  public createAuditLog(userId: string, userName: string, action: string, category: AuditLog['category'], details: string, severity: AuditLog['severity'] = 'LOW') {
    const log: AuditLog = {
      id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
      userId,
      userName,
      action,
      category,
      details,
      timestamp: new Date().toISOString(),
      severity
    };
    this.auditLogs.unshift(log);
    this.saveToStorage();
  }

  async logEmail(email: OutgoingEmail) {
    this.outgoingEmails.unshift(email);
    this.saveToStorage();
  }

  async login(email: string): Promise<{ status: number; user?: User }> {
    let user = this.users.find(u => u.email === email);
    if (user) {
      this.createAuditLog(user.id, user.name, 'USER_LOGIN', 'SECURITY', `Record-keeping session opened for ${email}`, 'LOW');
    }
    return { status: 200, user };
  }

  async register(userData: User): Promise<{ status: number; user: User }> {
    const existingIndex = this.users.findIndex(u => u.email === userData.email);
    const userToSave = { 
      ...userData, 
      walletBalance: userData.walletBalance ?? 0, 
      trustScore: 50,
      joinedAt: userData.joinedAt || new Date().toISOString()
    };

    if (existingIndex > -1) {
      this.users[existingIndex] = { ...this.users[existingIndex], ...userToSave };
    } else {
      this.users.push(userToSave);
      this.createAuditLog(userToSave.id, userToSave.name, 'USER_REGISTERED', 'IDENTITY', `Permanent record created for ${userToSave.name}`, 'MEDIUM');
    }

    this.saveToStorage();
    return { status: 200, user: userToSave };
  }

  async submitLoan(loan: Loan): Promise<{ status: number; loan: Loan }> {
    const history: StatusUpdate[] = [{
      status: 'PENDING',
      timestamp: new Date().toISOString(),
      message: 'Physical appraisal pending. User directed to office.'
    }];
    const loanWithHistory = { ...loan, statusHistory: history };
    this.loans.push(loanWithHistory);
    this.createAuditLog(loan.userId, loan.userName, 'LOAN_REQUEST', 'FINANCE', `Loan ${loan.id} filed for record. Amount: ${loan.principal}. Collateral: ${loan.collateralDescription}`, 'MEDIUM');
    this.saveToStorage();
    return { status: 201, loan: loanWithHistory };
  }

  async updateLoanStatus(loanId: string, status: Loan['status']): Promise<{ status: number; loan?: Loan }> {
    const loan = this.loans.find(l => l.id === loanId);
    if (loan) {
      loan.status = status;
      if (!loan.statusHistory) loan.statusHistory = [];
      loan.statusHistory.push({
        status: status,
        timestamp: new Date().toISOString(),
        message: `Management updated record to ${status}`
      });
      this.saveToStorage();
      return { status: 200, loan };
    }
    return { status: 404 };
  }

  async adjustVault(amount: number, reason: string): Promise<{ status: number }> {
    this.vaultBalance += amount;
    this.createAuditLog('ADMIN', 'SYSTEM', 'VAULT_ADJUST', 'FINANCE', `Vault adjusted by ${amount}. Reason: ${reason}`, 'HIGH');
    this.saveToStorage();
    return { status: 200 };
  }

  async disburse(loanId: string): Promise<{ status: number; transactionId?: string }> {
    const loan = this.loans.find(l => l.id === loanId);
    if (!loan) return { status: 404 };

    const user = this.users.find(u => u.id === loan.userId);
    if (!user) return { status: 404 };

    loan.status = 'DISBURSED';
    loan.disbursedAt = new Date().toISOString();
    user.walletBalance = (user.walletBalance || 0) + loan.principal;
    this.vaultBalance -= loan.principal;

    this.createAuditLog(user.id, user.name, 'LOAN_DISBURSED', 'FINANCE', `Loan ${loanId} disbursed physically. Wallet increased by ${loan.principal}`, 'HIGH');
    this.saveToStorage();
    return { status: 200 };
  }

  async repay(loanId: string, userId: string, amount: number): Promise<{ status: number }> {
    const loan = this.loans.find(l => l.id === loanId);
    const user = this.users.find(u => u.id === userId);
    if (!loan || !user) return { status: 404 };

    loan.status = 'REPAID';
    user.walletBalance = Math.max(0, (user.walletBalance || 0) - amount);
    this.vaultBalance += amount;

    if (!loan.statusHistory) loan.statusHistory = [];
    loan.statusHistory.push({
      status: 'REPAID',
      timestamp: new Date().toISOString(),
      message: 'Loan successfully closed. Collateral released.'
    });

    this.createAuditLog(userId, user.name, 'LOAN_REPAID', 'FINANCE', `Loan ${loanId} fully repaid. Amount: ${amount}`, 'MEDIUM');
    this.saveToStorage();
    return { status: 200 };
  }

  async simulateLoan(data: { name: string, principal: number, disbursedDate: string, dueDate: string }): Promise<{ status: number }> {
    const simLoan: Loan = {
      id: `SIM-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
      userId: 'SIM-USER',
      userName: data.name,
      principal: data.principal,
      purpose: 'Simulation Stress Test',
      tenure: '14 Days',
      repaymentMethod: 'CASH',
      status: 'APPROVED',
      createdAt: data.disbursedDate,
      dueDate: data.dueDate,
      collateralType: 'PHONE',
      collateralDescription: 'Simulated Test Device',
      hasAgreedToOwnership: true,
      hasAgreedToVerification: true,
      statusHistory: [{
        status: 'APPROVED',
        timestamp: data.disbursedDate,
        message: 'Simulation model generated.'
      }]
    };
    this.loans.push(simLoan);
    this.saveToStorage();
    return { status: 200 };
  }

  /**
   * Added missing method to update user location to fix apiService error.
   */
  async updateLocation(userId: string, location: Location): Promise<{ status: number }> {
    const user = this.users.find(u => u.id === userId);
    if (user) {
      user.currentLocation = location;
      this.saveToStorage();
      return { status: 200 };
    }
    return { status: 404 };
  }

  /**
   * Added missing method to set travel status to fix apiService error.
   */
  async setTravelStatus(loanId: string, status: boolean, mode?: TravelMode, eta?: string): Promise<{ status: number }> {
    this.createAuditLog('SYSTEM', 'SYSTEM', 'TRAVEL_UPDATE', 'SYSTEM', `Loan ${loanId} travel status: ${status}, Mode: ${mode}, ETA: ${eta}`, 'LOW');
    return { status: 200 };
  }

  /**
   * Added missing method for Mobile Money withdrawal to fix apiService error.
   */
  async withdrawToMoMo(userId: string, amount: number, operator: MobileOperator): Promise<{ status: number }> {
    const user = this.users.find(u => u.id === userId);
    if (!user) return { status: 404 };
    if ((user.walletBalance || 0) < amount) return { status: 400 };

    user.walletBalance = (user.walletBalance || 0) - amount;
    this.vaultBalance += amount;
    this.createAuditLog(userId, user.name, 'WITHDRAWAL_MOMO', 'FINANCE', `Withdrew ${amount} to MoMo (${operator})`, 'MEDIUM');
    this.saveToStorage();
    return { status: 200 };
  }

  /**
   * Added missing method for Mobile Money deposit to fix apiService error.
   */
  async depositFromMoMo(userId: string, amount: number): Promise<{ status: number }> {
    const user = this.users.find(u => u.id === userId);
    if (!user) return { status: 404 };

    user.walletBalance = (user.walletBalance || 0) + amount;
    this.vaultBalance -= amount;
    this.createAuditLog(userId, user.name, 'DEPOSIT_MOMO', 'FINANCE', `Deposited ${amount} from MoMo`, 'MEDIUM');
    this.saveToStorage();
    return { status: 200 };
  }

  getDashboardStats() {
    return {
      vaultBalance: this.vaultBalance,
      loans: [...this.loans],
      users: [...this.users],
      transactions: [...this.transactions],
      auditLogs: [...this.auditLogs],
      outgoingEmails: [...this.outgoingEmails]
    };
  }
}

export const backend = new VirtualBackend();

import React, { useState, useRef } from 'react';
import { CollateralType, RepaymentMethod } from '../types';
import { analyzeSafetyPhoto } from '../services/geminiService';

interface LoanFormProps {
  onSubmit: (loanData: any) => void;
  isLoading: boolean;
}

const COLLATERAL_DATA: Record<CollateralType, { label: string; icon: string }> = {
  PHONE: { label: 'Phone', icon: 'fa-mobile-screen' },
  LAPTOP: { label: 'PC / Laptop', icon: 'fa-laptop' },
  CAR: { label: 'Vehicle', icon: 'fa-car' },
  APPLIANCE: { label: 'Appliance', icon: 'fa-plug' },
  LAND: { label: 'Land/Property', icon: 'fa-map-location' },
  OTHER: { label: 'Other', icon: 'fa-ellipsis' },
  NONE: { label: 'None', icon: 'fa-ban' }
};

const LoanForm: React.FC<LoanFormProps> = ({ onSubmit, isLoading }) => {
  const [step, setStep] = useState(1);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [formData, setFormData] = useState({
    principal: '',
    purpose: '',
    tenure: '14 Days',
    repaymentMethod: 'CASH' as RepaymentMethod,
    collateralType: 'NONE' as CollateralType,
    collateralDescription: '',
    collateralSerial: '',
    collateralCondition: '',
    collateralLocation: '',
    hasAgreedToOwnership: false,
    hasAgreedToVerification: false
  });

  const [selfieBase64, setSelfieBase64] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setError(null);
      setIsAnalyzing(true);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        // Verify image quality and content safety via AI
        const result = await analyzeSafetyPhoto(base64);
        if (result.isValid) {
          setSelfieBase64(base64);
        } else {
          setError(result.reason || "Photo rejected. Please ensure your face is clearly visible.");
          setSelfieBase64(null);
          setPreviewUrl(null);
        }
        setIsAnalyzing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const nextStep = () => {
    if (step === 1 && (!formData.principal || !formData.purpose)) {
      setError("Please enter loan amount and purpose.");
      return;
    }
    if (step === 2 && (formData.collateralType === 'NONE' || !formData.collateralDescription)) {
      setError("Please provide complete collateral details.");
      return;
    }
    setError(null);
    setStep(step + 1);
  };

  const prevStep = () => setStep(step - 1);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selfieBase64) {
      setError("A verification selfie is required for our records.");
      return;
    }
    if (!formData.hasAgreedToOwnership || !formData.hasAgreedToVerification) {
      setError("You must agree to the legal declarations.");
      return;
    }
    onSubmit({ ...formData, borrowerPhoto: selfieBase64 });
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl p-10 border border-gray-100 dark:border-slate-700 w-full max-w-2xl mx-auto animate-fadeIn transition-colors">

      <div className="mb-10 p-5 bg-orange-50 dark:bg-orange-950/30 border-2 border-orange-200 dark:border-orange-800 rounded-[2.5rem] flex gap-5">
        <div className="w-12 h-12 bg-orange-500 text-white rounded-2xl flex items-center justify-center shrink-0 shadow-lg">
          <i className="fas fa-handshake-angle text-xl"></i>
        </div>
        <div>
          <p className="text-[11px] font-black uppercase text-orange-900 dark:text-orange-400 mb-1">Physical Payout Alert</p>
          <p className="text-[12px] text-orange-800 dark:text-orange-300 font-medium leading-relaxed">
            KwachaTime strictly operates via physical hand-to-hand disbursements at our office. No digital transfers for first-time loans.
          </p>
        </div>
      </div>

      <div className="flex justify-between items-center mb-10">
        <h2 className="text-2xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Application Form</h2>
        <div className="flex gap-1">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className={`h-1.5 w-8 rounded-full ${step >= i ? 'bg-emerald-600' : 'bg-gray-100 dark:bg-slate-700'}`}></div>
          ))}
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">

        {step === 1 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 1: Requirements</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Amount (ZMW)</label>
                <input 
                  type="number" 
                  value={formData.principal}
                  onChange={e => setFormData({...formData, principal: e.target.value})}
                  placeholder="0.00"
                  className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Repayment Period</label>
                <select 
                  value={formData.tenure}
                  onChange={e => setFormData({...formData, tenure: e.target.value})}
                  className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold appearance-none"
                >
                  <option>14 Days</option>
                  <option>30 Days</option>
                  <option>60 Days</option>
                </select>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Loan Purpose</label>
              <textarea 
                value={formData.purpose}
                onChange={e => setFormData({...formData, purpose: e.target.value})}
                placeholder="Reason for borrowing..."
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold h-32"
              />
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 2: Collateral Registry</h3>
            <div className="grid grid-cols-3 md:grid-cols-4 gap-4">
              {(Object.keys(COLLATERAL_DATA) as CollateralType[]).filter(k => k !== 'NONE').map(key => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setFormData({...formData, collateralType: key})}
                  className={`flex flex-col items-center justify-center p-4 rounded-3xl border-2 transition-all ${formData.collateralType === key ? 'bg-emerald-800 border-emerald-800 text-white shadow-xl scale-105' : 'bg-gray-50 dark:bg-slate-900 border-gray-100 dark:border-slate-700 text-gray-400'}`}
                >
                  <i className={`fas ${COLLATERAL_DATA[key].icon} text-xl mb-2`}></i>
                  <span className="text-[9px] font-black uppercase text-center">{COLLATERAL_DATA[key].label}</span>
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input 
                placeholder="Description (e.g. iPhone 15 Pro)"
                value={formData.collateralDescription}
                onChange={e => setFormData({...formData, collateralDescription: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs"
              />
              <input 
                placeholder="Serial Number / IMEI"
                value={formData.collateralSerial}
                onChange={e => setFormData({...formData, collateralSerial: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs"
              />
              <input 
                placeholder="Condition of Item"
                value={formData.collateralCondition}
                onChange={e => setFormData({...formData, collateralCondition: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs"
              />
              <input 
                placeholder="Location of Item"
                value={formData.collateralLocation}
                onChange={e => setFormData({...formData, collateralLocation: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs"
              />
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 3: Photo Records</h3>
            <div className="space-y-4">
              <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Record Selfie</label>
              <div 
                onClick={() => !isAnalyzing && fileInputRef.current?.click()}
                className={`h-56 rounded-[2.5rem] border-4 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all overflow-hidden ${isAnalyzing ? 'border-emerald-500 bg-emerald-50' : 'border-gray-100 dark:border-slate-700 bg-gray-50 dark:bg-slate-900 hover:border-emerald-500'}`}
              >
                {isAnalyzing ? (
                  <div className="flex flex-col items-center">
                    <div className="w-10 h-10 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <p className="text-[10px] font-black uppercase text-emerald-600">Verifying Photo Quality...</p>
                  </div>
                ) : previewUrl ? (
                  <img src={previewUrl} className="w-full h-full object-cover" alt="Selfie" />
                ) : (
                  <>
                    <i className="fas fa-camera text-4xl text-gray-200 mb-4"></i>
                    <p className="text-[10px] font-black uppercase text-gray-400">Click to capture your photo</p>
                  </>
                )}
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Repayment Plan</label>
              <div className="grid grid-cols-3 gap-3">
                {['CASH', 'BANK_TRANSFER', 'MOBILE_MONEY'].map(m => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setFormData({...formData, repaymentMethod: m as RepaymentMethod})}
                    className={`p-4 rounded-2xl border-2 text-[9px] font-black uppercase ${formData.repaymentMethod === m ? 'bg-emerald-800 border-emerald-800 text-white' : 'bg-gray-50 dark:bg-slate-900 border-transparent text-gray-400'}`}
                  >
                    {m.replace('_', ' ')}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {step === 4 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 4: Legal Finalization</h3>
            <div className="space-y-4">
              <label className="flex items-start gap-4 p-5 bg-gray-50 dark:bg-slate-900 rounded-3xl cursor-pointer hover:bg-emerald-50 transition-colors">
                <input 
                  type="checkbox" 
                  checked={formData.hasAgreedToOwnership}
                  onChange={e => setFormData({...formData, hasAgreedToOwnership: e.target.checked})}
                  className="mt-1 w-5 h-5 accent-emerald-600"
                />
                <span className="text-[11px] font-medium text-gray-600 dark:text-gray-400 leading-tight">
                  I confirm that I am the sole owner of the collateral described and I pledge it as security for this loan request.
                </span>
              </label>

              <label className="flex items-start gap-4 p-5 bg-gray-50 dark:bg-slate-900 rounded-3xl cursor-pointer hover:bg-emerald-50 transition-colors">
                <input 
                  type="checkbox" 
                  checked={formData.hasAgreedToVerification}
                  onChange={e => setFormData({...formData, hasAgreedToVerification: e.target.checked})}
                  className="mt-1 w-5 h-5 accent-emerald-600"
                />
                <span className="text-[11px] font-medium text-gray-600 dark:text-gray-400 leading-tight">
                  I authorize KwachaTime to verify the ownership of my collateral and perform a credit check for the permanent registry.
                </span>
              </label>
            </div>
          </div>
        )}

        {error && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{error}</p>}

        <div className="flex gap-4">
          {step > 1 && (
            <button 
              type="button"
              onClick={prevStep}
              className="flex-1 py-6 bg-gray-100 dark:bg-slate-700 text-gray-400 rounded-[2rem] font-black uppercase tracking-widest transition-all"
            >
              Back
            </button>
          )}

          {step < 4 ? (
            <button 
              type="button"
              onClick={nextStep}
              className="flex-[2] py-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl transition-all"
            >
              Next
            </button>
          ) : (
            <button 
              type="submit"
              disabled={isLoading || isAnalyzing}
              className="flex-[2] py-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 disabled:opacity-50"
            >
              {isLoading ? "Submitting..." : "Apply Now"}
            </button>
          )}
        </div>
      </form>
    </div>
  );
};

