            <div className="w-24 h-24 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-inner">
               <i className="fas fa-landmark text-4xl"></i>
            </div>
            <h2 className="text-4xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter mb-4">Vault Entrance</h2>
            <p className="text-[11px] font-black uppercase text-emerald-600 tracking-widest mb-10">Secure Financial Records</p>

            {loginSequence !== 'IDLE' ? (
              <div className="py-20 flex flex-col items-center gap-8">
                <div className="w-20 h-20 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-xs font-black uppercase tracking-widest text-emerald-600 animate-pulse">{loginSequence}...</p>
              </div>
            ) : (
              <form onSubmit={handleInitialLogin} className="space-y-6 text-left">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Email</label>
                      <input name="email" type="email" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Full Legal Name</label>
                      <input name="name" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">NRC Number</label>
                      <input name="nrc" required placeholder="000000/00/0" className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
