              { id: 'USERS', icon: 'fa-address-book', label: 'Client Registry' },
              { id: 'SIMULATE', icon: 'fa-vial-circle-check', label: 'Simulation' },
              { id: 'LOGS', icon: 'fa-list-check', label: 'Audit Trail' }
            ].map(tab => (
              <button 
                key={tab.id} 
                onClick={() => setActiveAdminTab(tab.id as any)}
                className={`w-full flex items-center gap-5 p-6 rounded-[2rem] text-[11px] font-black uppercase transition-all ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white shadow-xl scale-105' : 'bg-white dark:bg-slate-900 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800'}`}
              >
                <i className={`fas ${tab.icon} w-6 text-lg`}></i>
                {tab.label}
              </button>
            ))}
          </div>

          <div className="lg:col-span-3 space-y-8">
            {activeAdminTab === 'SIMULATE' && (
              <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-xl border-4 border-indigo-50 dark:border-indigo-900/20">
                 <h3 className="text-2xl font-black uppercase text-indigo-600 mb-10">Modeling Engine</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                    <input type="text" placeholder="Subject Name" value={simName} onChange={(e) => setSimName(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                    <input type="number" placeholder="Principal ZMW" value={simPrincipal} onChange={(e) => setSimPrincipal(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                 </div>
                 <button onClick={() => apiService.simulateLoan({ name: simName, principal: parseFloat(simPrincipal), disbursedDate: new Date().toISOString(), dueDate: new Date(Date.now() + 14 * 86400000).toISOString() }).then(() => { setSimName(''); setSimPrincipal(''); refreshData(); })} className="w-full py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase shadow-xl mb-12">Inject Simulation Model</button>

                 <div className="space-y-6">
                    <h4 className="text-[11px] font-black uppercase text-gray-400 tracking-widest border-b pb-2">Active Models</h4>
                    {allLoans.filter(l => l.userId === 'SIM-USER').map(loan => (
                      <div key={loan.id} className="p-8 bg-gray-50 dark:bg-slate-800 rounded-[2.5rem] flex justify-between items-center group">
                        <div>
                          <p className="font-black text-lg">{loan.userName}</p>
                          <p className="text-[10px] text-indigo-600 font-bold uppercase">{formatCurrency(loan.principal)} Model</p>
                          <span className={`mt-2 px-3 py-1 rounded-lg text-[9px] font-black uppercase inline-block ${loan.status === 'REPAID' ? 'bg-emerald-100 text-emerald-700' : 'bg-indigo-100 text-indigo-700'}`}>{loan.status}</span>
                        </div>
                        <div className="flex gap-2">
                           <button onClick={() => setActiveLegalDoc({ user: allUsers.find(u => u.id === 'SIM-USER'), loan, type: 'AGREEMENT' })} className="px-5 py-3 bg-white dark:bg-slate-900 rounded-2xl text-[9px] font-black uppercase border">Agmt</button>
                           <button onClick={() => setActiveLegalDoc({ user: allUsers.find(u => u.id === 'SIM-USER'), loan, type: 'LETTER_OF_SALE' })} className="px-5 py-3 bg-white dark:bg-slate-900 rounded-2xl text-[9px] font-black uppercase border">Sale</button>
                           {loan.status !== 'REPAID' && (
                              <button onClick={() => handleRepaySim(loan.id, loan.principal * 1.1)} className="px-5 py-3 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg">Test Repay</button>
                           )}
                        </div>
                      </div>
                    ))}
                 </div>
              </div>
            )}

            {activeAdminTab === 'PENDING' && (
              <div className="space-y-6">
                {allLoans.filter(l => l.status === 'PENDING').map(loan => {
                  const borrower = allUsers.find(u => u.id === loan.userId);
                  return (
                    <div key={loan.id} className="bg-white dark:bg-slate-900 p-10 rounded-[4rem] shadow-xl border border-gray-50 dark:border-slate-800">
                       <div className="flex justify-between items-start mb-8">
                          <div>
                            <p className="text-[10px] font-black uppercase text-emerald-600 mb-2">Ref: {loan.id}</p>
                            <h4 className="text-2xl font-black">{loan.userName}</h4>
                            <p className="text-3xl font-black mt-2 text-emerald-900 dark:text-emerald-400">{formatCurrency(loan.principal)}</p>
                          </div>
                          <div className="flex flex-col gap-3">
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'CREDENTIAL_REPORT' })} className="px-6 py-3 bg-blue-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg flex items-center gap-2">
                               <i className="fas fa-id-card"></i> Verify Credentials
                             </button>
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'AGREEMENT' })} className="px-6 py-3 bg-slate-900 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg">Agreement</button>
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'LETTER_OF_SALE' })} className="px-6 py-3 bg-orange-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg">Sale Letter</button>
                          </div>
                       </div>
                       <div className="flex gap-4">
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'APPROVED')} className="flex-1 py-5 bg-emerald-800 text-white rounded-3xl font-black uppercase text-[11px] shadow-lg">Approve Payout</button>
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'REJECTED')} className="flex-1 py-5 bg-red-800 text-white rounded-3xl font-black uppercase text-[11px] shadow-lg">Reject</button>
                       </div>
                    </div>
                  );
                })}
              </div>
            )}

            {activeAdminTab === 'USERS' && (
              <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-xl">
                 <h3 className="text-2xl font-black uppercase mb-10">Client Registry</h3>
                 <div className="space-y-4">
                    {allUsers.filter(u => u.id !== 'SIM-USER').map(u => (
                      <div key={u.id} className="p-8 bg-gray-50 dark:bg-slate-800 rounded-[2.5rem] flex justify-between items-center border border-gray-100 dark:border-slate-700">
                        <div>
                          <p className="text-xl font-black">{u.name}</p>
                          <p className="text-[10px] text-emerald-600 font-bold uppercase mb-2">NRC: {u.nrc}</p>
                          <p className="text-[9px] text-gray-400 italic">{u.address}</p>
                        </div>
                        <div className="flex items-center gap-4">
                           <button 
                             onClick={() => {
                               const loan = allLoans.find(l => l.userId === u.id);
                               setActiveLegalDoc({ user: u, loan, type: 'CREDENTIAL_REPORT' });
                             }}
                             className="px-4 py-3 bg-white dark:bg-slate-900 border rounded-2xl text-[9px] font-black uppercase hover:bg-emerald-50 transition-all flex items-center gap-2"
                           >
                             <i className="fas fa-file-pdf"></i> Download Profile
                           </button>
                           <p className="text-2xl font-black text-emerald-800">{formatCurrency(u.walletBalance || 0)}</p>
                        </div>
                      </div>
                    ))}
                 </div>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
           <div className="lg:col-span-1 space-y-12">
              <Roadmap />
              <OfficeLocator />
           </div>

           <div className="lg:col-span-2 space-y-12">
              <div className="bg-emerald-950 text-white p-12 rounded-[4.5rem] shadow-2xl relative overflow-hidden flex justify-between items-end border border-emerald-900">
                 <div>
                    <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-widest">Digital Ledger</p>
                    <p className="text-6xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 </div>
                 <div className="w-16 h-16 bg-white/10 rounded-3xl flex items-center justify-center text-3xl">
                    <i className="fas fa-coins"></i>
                 </div>
              </div>

              <div className="space-y-6">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 pl-6 tracking-widest">Financial Timeline</h3>
                 {allLoans.length === 0 ? (
                   <div className="p-32 text-center bg-gray-50 dark:bg-slate-900 rounded-[4rem] text-gray-300 font-black uppercase tracking-widest border-2 border-dashed">No Active Records</div>
                 ) : (
                   allLoans.map(loan => (
                    <div key={loan.id} className="p-10 bg-white dark:bg-slate-900 rounded-[4rem] shadow-xl border-2 border-gray-50 dark:border-slate-800 animate-slideUp">
                       <div className="flex justify-between items-start">
                          <div>
                             <p className="text-[10px] font-black uppercase text-gray-400 mb-1">ID: {loan.id}</p>
                             <h4 className="text-3xl font-black">{formatCurrency(loan.principal)}</h4>
                             <p className="px-3 py-1 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-lg text-[9px] font-black uppercase mt-3 inline-block">{loan.collateralDescription}</p>
                          </div>
                          <div className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-700'}`}>
                             {loan.status}
                          </div>
                       </div>
                    </div>
                   ))
                 )}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: parseFloat(data.principal),
                   purpose: data.purpose,
                   tenure: data.tenure,
                   repaymentMethod: data.repaymentMethod,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 86400000).toISOString(),
                   collateralType: data.collateralType,
                   collateralDescription: data.collateralDescription,
                   collateralSerial: data.collateralSerial,
                   collateralCondition: data.collateralCondition,
                   collateralLocation: data.collateralLocation,
                   hasAgreedToOwnership: data.hasAgreedToOwnership,
                   hasAgreedToVerification: data.hasAgreedToVerification,
                   borrowerPhoto: data.borrowerPhoto
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
      <CurrencyConverter />
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, Loan, UserRole, ThemeMode, AuditLog, Transaction, OutgoingEmail } from './types';
import Layout from './components/Layout';
import LoanForm from './components/LoanForm';
import Roadmap from './components/Roadmap';
import OfficeLocator from './components/OfficeLocator';
import CurrencyConverter from './components/CurrencyConverter';
import OnboardingTour from './components/OnboardingTour';
import LegalDocumentModal from './components/LegalDocumentModal';
import OperationalManual from './components/OperationalManual';
import { formatCurrency } from './utils/loanCalculator';
import { apiService } from './services/apiService';

const APP_VERSION = "1.2.0-Formalities-Stable";

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allLoans, setAllLoans] = useState<Loan[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [outgoingEmails, setOutgoingEmails] = useState<OutgoingEmail[]>([]);
  const [vaultBalance, setVaultBalance] = useState<number>(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [updateAvailable, setUpdateAvailable] = useState(false);

  const [activeLegalDoc, setActiveLegalDoc] = useState<{ user?: User; loan?: Loan; type: 'AGREEMENT' | 'LETTER_OF_SALE' | 'CREDENTIAL_REPORT' } | null>(null);
  const [loginSequence, setLoginSequence] = useState<'IDLE' | 'AUTHENTICATING' | 'CLOCK' | 'CURRENCY'>('IDLE');
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem('theme-mode') as ThemeMode) || 'system');
  const [activeAdminTab, setActiveAdminTab] = useState<'MONITOR' | 'PENDING' | 'USERS' | 'SIMULATE' | 'LOGS'>('MONITOR');

  const [simName, setSimName] = useState('');
  const [simPrincipal, setSimPrincipal] = useState('');

  useEffect(() => {
    const root = document.documentElement;
    const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    const effectiveTheme = themeMode === 'system' ? systemTheme : themeMode;
    if (effectiveTheme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
    localStorage.setItem('theme-mode', themeMode);
  }, [themeMode]);

  useEffect(() => {
    const handleUpdate = () => setUpdateAvailable(true);
    window.addEventListener('pwa-update-available', handleUpdate);
    return () => window.removeEventListener('pwa-update-available', handleUpdate);
  }, []);

  const isAdmin = useMemo(() => currentUser?.role === 'ADMIN' || currentUser?.role === 'DEVELOPER', [currentUser]);

  const refreshData = useCallback(async () => {
    if (!currentUser) return;
    try {
      const stats = await apiService.getAdminData();
      const updatedSelf = stats.users.find(u => u.id === currentUser.id);
      if (updatedSelf) setCurrentUser(updatedSelf);

      if (isAdmin) {
        setAllLoans(stats.loans);
        setAllUsers(stats.users);
        setVaultBalance(stats.vaultBalance);
        setAuditLogs(stats.auditLogs);
        setOutgoingEmails(stats.outgoingEmails);
      } else {
        setAllLoans(stats.loans.filter(l => l.userId === currentUser.id));
      }
    } catch (e) {
      console.error("Refresh failed", e);
    }
  }, [currentUser, isAdmin]);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('kwachatime_user');
  };

  const handleInitialLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginSequence('AUTHENTICATING');
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string).toLowerCase().trim();

    const adminEmails = ['ocmwila@networkit.info', 'naphtali.tre@gmail.com', 'admin@kwachatime.com'];
    const role: UserRole = adminEmails.includes(email) ? 'ADMIN' : 'BORROWER';

    const response = await apiService.authenticate(email);
    const userData: User = response.user || {
      id: Math.random().toString(36).substr(2, 9),
      name: (formData.get('name') as string),
      email: email,
      nrc: (formData.get('nrc') as string),
      dob: (formData.get('dob') as string),
      phone: (formData.get('phone') as string),
      address: (formData.get('address') as string),
      employment: (formData.get('employment') as string),
      incomeSource: (formData.get('incomeSource') as string),
      nextOfKinName: (formData.get('nok_name') as string),
      nextOfKinPhone: (formData.get('nok_phone') as string),
      operator: 'Airtel',
      role: role,
      joinedAt: new Date().toISOString(),
      walletBalance: 0
    };

    await apiService.syncUser(userData);
    setLoginSequence('CLOCK');
    await new Promise(r => setTimeout(r, 600));
    setLoginSequence('CURRENCY');
    await new Promise(r => setTimeout(r, 600));

    setCurrentUser(userData);
    localStorage.setItem('kwachatime_user', JSON.stringify(userData));
    setLoginSequence('IDLE');
  };

  const handleManualStatusUpdate = async (loanId: string, status: Loan['status']) => {
    setIsProcessing(true);
    try {
      if (status === 'DISBURSED') {
        await apiService.disburseLoan(loanId);
      } else {
        await apiService.updateLoanStatus(loanId, status);
      }
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-screen p-4 py-20">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-2xl border border-gray-100 dark:border-slate-800 text-center">
            <div className="w-24 h-24 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-inner">
               <i className="fas fa-landmark text-4xl"></i>
            </div>
            <h2 className="text-4xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter mb-4">Vault Entrance</h2>
            <p className="text-[11px] font-black uppercase text-emerald-600 tracking-widest mb-10 italic">Zambian Micro-Lending Portal</p>

            {loginSequence !== 'IDLE' ? (
              <div className="py-20 flex flex-col items-center gap-8">
                <div className="w-20 h-20 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-xs font-black uppercase tracking-widest text-emerald-600 animate-pulse">{loginSequence}...</p>
              </div>
            ) : (
              <form onSubmit={handleInitialLogin} className="space-y-6 text-left">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Email Address</label>
                      <input name="email" type="text" placeholder="Enter email" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Full Legal Name</label>
                      <input name="name" type="text" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">NRC (ID Number)</label>
                      <input name="nrc" type="text" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Birth Date</label>
                      <input name="dob" type="text" placeholder="DD/MM/YYYY" className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Active Phone</label>
                      <input name="phone" type="text" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Residential Address</label>
                      <input name="address" type="text" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Current Employment</label>
                      <input name="employment" type="text" className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Next of Kin Name</label>
                      <input name="nok_name" type="text" required className="w-full bg-gray-50 dark:bg-slate-800 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold" />
                   </div>
                </div>
                <button className="w-full py-6 bg-emerald-800 text-white rounded-[2.5rem] font-black uppercase tracking-widest mt-6 shadow-2xl transition-all active:scale-95">Complete Formalities & Enter</button>
              </form>
            )}
            <p className="mt-12 text-[9px] font-black text-gray-300 uppercase tracking-widest">v{APP_VERSION}</p>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={() => setThemeMode(themeMode === 'light' ? 'dark' : 'light')}>

      {activeLegalDoc && (
        <LegalDocumentModal 
          user={activeLegalDoc.user || currentUser}
          loan={activeLegalDoc.loan}
          type={activeLegalDoc.type}
          onClose={() => setActiveLegalDoc(null)}
        />
      )}

      {isAdmin ? (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 animate-fadeIn">
          <div className="lg:col-span-1 space-y-4">
            <div className="bg-slate-900 text-white p-8 rounded-[3.5rem] mb-6 shadow-xl">
               <p className="text-[10px] font-black uppercase text-emerald-400 mb-1">Portfolio Liquidity</p>
               <p className="text-3xl font-black">{formatCurrency(vaultBalance)}</p>
            </div>
            {[
              { id: 'MONITOR', icon: 'fa-chart-line', label: 'Monitor' },
              { id: 'PENDING', icon: 'fa-shield-halved', label: 'Approvals' },
              { id: 'USERS', icon: 'fa-address-book', label: 'Client Registry' },
              { id: 'SIMULATE', icon: 'fa-vial-circle-check', label: 'Simulation' },
              { id: 'LOGS', icon: 'fa-list-check', label: 'Audit Trail' }
            ].map(tab => (
              <button 
                key={tab.id} 
                onClick={() => setActiveAdminTab(tab.id as any)}
                className={`w-full flex items-center gap-5 p-6 rounded-[2rem] text-[11px] font-black uppercase transition-all ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white shadow-xl scale-105' : 'bg-white dark:bg-slate-900 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800'}`}
              >
                <i className={`fas ${tab.icon} w-6 text-lg`}></i>
                {tab.label}
              </button>
            ))}
          </div>

          <div className="lg:col-span-3 space-y-8">
            {activeAdminTab === 'USERS' && (
              <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-xl">
                 <div className="flex justify-between items-center mb-10">
                   <h3 className="text-2xl font-black uppercase">Client Credential Ledger</h3>
                   <i className="fas fa-file-pdf text-emerald-100 dark:text-slate-800 text-4xl"></i>
                 </div>
                 <div className="space-y-4">
                    {allUsers.filter(u => u.id !== 'SIM-USER').map(u => {
                      const latestLoan = allLoans.find(l => l.userId === u.id);
                      return (
                        <div key={u.id} className="p-8 bg-gray-50 dark:bg-slate-800 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-center border border-gray-100 dark:border-slate-700 gap-6">
                          <div className="flex items-center gap-6 w-full">
                            <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center overflow-hidden border-2 border-white dark:border-slate-700">
                               {latestLoan?.borrowerPhoto ? (
                                 <img src={latestLoan.borrowerPhoto} className="w-full h-full object-cover" />
                               ) : (
                                 <i className="fas fa-user text-emerald-800 dark:text-emerald-400"></i>
                               )}
                            </div>
                            <div>
                              <p className="text-xl font-black">{u.name}</p>
                              <p className="text-[10px] text-emerald-600 font-bold uppercase">NRC: {u.nrc} • Phone: {u.phone}</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-4 w-full md:w-auto justify-end">
                             <button 
                               onClick={() => setActiveLegalDoc({ user: u, loan: latestLoan, type: 'CREDENTIAL_REPORT' })}
                               className="px-6 py-4 bg-emerald-800 text-white rounded-2xl text-[9px] font-black uppercase hover:bg-emerald-950 transition-all flex items-center gap-3 shadow-lg whitespace-nowrap"
                             >
                               <i className="fas fa-id-card"></i> Export KYC PDF
                             </button>
                          </div>
                        </div>
                      );
                    })}
                    {allUsers.filter(u => u.id !== 'SIM-USER').length === 0 && (
                      <div className="py-20 text-center text-gray-300 font-black uppercase tracking-widest">No clients registered in ledger</div>
                    )}
                 </div>
              </div>
            )}

            {activeAdminTab === 'PENDING' && (
              <div className="space-y-6">
                {allLoans.filter(l => l.status === 'PENDING').map(loan => {
                  const borrower = allUsers.find(u => u.id === loan.userId);
                  return (
                    <div key={loan.id} className="bg-white dark:bg-slate-900 p-10 rounded-[4rem] shadow-xl border border-gray-50 dark:border-slate-800">
                       <div className="flex justify-between items-start mb-8">
                          <div className="flex gap-6 items-start">
                            <div className="w-20 h-20 bg-gray-100 dark:bg-slate-800 rounded-2xl overflow-hidden border-2 border-emerald-50 shadow-inner">
                               {loan.borrowerPhoto ? <img src={loan.borrowerPhoto} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-gray-300"><i className="fas fa-camera"></i></div>}
                            </div>
                            <div>
                              <p className="text-[10px] font-black uppercase text-emerald-600 mb-2">Request ID: {loan.id}</p>
                              <h4 className="text-2xl font-black">{loan.userName}</h4>
                              <p className="text-3xl font-black mt-2 text-emerald-900 dark:text-emerald-400">{formatCurrency(loan.principal)}</p>
                            </div>
                          </div>
                          <div className="flex flex-col gap-3">
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'CREDENTIAL_REPORT' })} className="px-6 py-3 bg-blue-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg flex items-center gap-2">
                               <i className="fas fa-id-card"></i> View KYC
                             </button>
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'AGREEMENT' })} className="px-6 py-3 bg-slate-900 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg">Draft Agreement</button>
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'LETTER_OF_SALE' })} className="px-6 py-3 bg-orange-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg">Sale Letter</button>
                          </div>
                       </div>
                       <div className="flex gap-4">
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'APPROVED')} className="flex-1 py-5 bg-emerald-800 text-white rounded-3xl font-black uppercase text-[11px] shadow-lg">Approve Payout</button>
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'REJECTED')} className="flex-1 py-5 bg-red-800 text-white rounded-3xl font-black uppercase text-[11px] shadow-lg">Reject Request</button>
                       </div>
                    </div>
                  );
                })}
              </div>
            )}

            {activeAdminTab === 'SIMULATE' && (
              <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-xl border-4 border-indigo-50 dark:border-indigo-900/20">
                 <h3 className="text-2xl font-black uppercase text-indigo-600 mb-10">Simulation Stress Engine</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                    <input type="text" placeholder="Scenario Subject" value={simName} onChange={(e) => setSimName(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                    <input type="number" placeholder="Principal ZMW" value={simPrincipal} onChange={(e) => setSimPrincipal(e.target.value)} className="bg-gray-50 dark:bg-slate-800 p-6 rounded-3xl outline-none font-bold" />
                 </div>
                 <button onClick={() => apiService.simulateLoan({ name: simName, principal: parseFloat(simPrincipal), disbursedDate: new Date().toISOString(), dueDate: new Date(Date.now() + 14 * 86400000).toISOString() }).then(() => { setSimName(''); setSimPrincipal(''); refreshData(); })} className="w-full py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase shadow-xl mb-12">Inject Scenario Model</button>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
           <div className="lg:col-span-1 space-y-12">
              <Roadmap />
              <OfficeLocator />
           </div>

           <div className="lg:col-span-2 space-y-12">
              <div className="bg-emerald-950 text-white p-12 rounded-[4.5rem] shadow-2xl relative overflow-hidden flex justify-between items-end border border-emerald-900">
                 <div>
                    <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-widest">Active Credit Record</p>
                    <p className="text-6xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 </div>
                 <div className="w-16 h-16 bg-white/10 rounded-3xl flex items-center justify-center text-3xl">
                    <i className="fas fa-coins"></i>
                 </div>
              </div>

              <div className="space-y-6">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 pl-6 tracking-widest">Financial History</h3>
                 {allLoans.length === 0 ? (
                   <div className="p-32 text-center bg-gray-50 dark:bg-slate-900 rounded-[4rem] text-gray-300 font-black uppercase tracking-widest border-2 border-dashed">No Active Records</div>
                 ) : (
                   allLoans.map(loan => (
                    <div key={loan.id} className="p-10 bg-white dark:bg-slate-900 rounded-[4rem] shadow-xl border-2 border-gray-50 dark:border-slate-800 animate-slideUp">
                       <div className="flex justify-between items-start">
                          <div>
                             <p className="text-[10px] font-black uppercase text-gray-400 mb-1">REQ: {loan.id}</p>
                             <h4 className="text-3xl font-black">{formatCurrency(loan.principal)}</h4>
                             <p className="px-3 py-1 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-lg text-[9px] font-black uppercase mt-3 inline-block">{loan.collateralDescription}</p>
                          </div>
                          <div className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-700'}`}>
                             {loan.status}
                          </div>
                       </div>
                    </div>
                   ))
                 )}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: parseFloat(data.principal),
                   purpose: data.purpose,
                   tenure: data.tenure,
                   repaymentMethod: data.repaymentMethod,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 86400000).toISOString(),
                   collateralType: data.collateralType,
                   collateralDescription: data.collateralDescription,
                   collateralSerial: data.collateralSerial,
                   collateralCondition: data.collateralCondition,
                   collateralLocation: data.collateralLocation,
                   hasAgreedToOwnership: data.hasAgreedToOwnership,
                   hasAgreedToVerification: data.hasAgreedToVerification,
                   borrowerPhoto: data.borrowerPhoto
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
      <CurrencyConverter />
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { generateLoanAgreement, generateLetterOfSale, generateBorrowerReport } from '../services/geminiService';
import { User, Loan } from '../types';

interface LegalDocumentModalProps {
  user: User;
  loan?: Loan;
  type: 'AGREEMENT' | 'LETTER_OF_SALE' | 'CREDENTIAL_REPORT';
  onClose: () => void;
}

const LegalDocumentModal: React.FC<LegalDocumentModalProps> = ({ user, loan, type, onClose }) => {
  const [content, setContent] = useState<string>('');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const loadDoc = async () => {
      setIsLoading(true);
      let doc = '';
      if (type === 'CREDENTIAL_REPORT') {
        doc = await generateBorrowerReport(user);
      } else if (loan) {
        doc = type === 'AGREEMENT' 
          ? await generateLoanAgreement(user, loan)
          : await generateLetterOfSale(user, loan);
      }
      setContent(doc || '');
      setIsLoading(false);
    };
    loadDoc();
  }, [user, loan, type]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 z-[7000] flex items-center justify-center p-4 bg-emerald-950/90 backdrop-blur-xl animate-fadeIn no-print">
      <div className="bg-white w-full max-w-4xl h-[90vh] rounded-[3.5rem] overflow-hidden shadow-2xl flex flex-col transition-all">

        {/* Header */}
        <div className="p-8 border-b flex justify-between items-center bg-gray-50">
          <div>
            <h3 className="text-2xl font-black text-emerald-900 uppercase tracking-tighter">
              {type === 'AGREEMENT' ? 'Loan Agreement' : type === 'LETTER_OF_SALE' ? 'Letter of Sale' : 'Identity Credentials'}
            </h3>
            <p className="text-[10px] font-black uppercase text-emerald-600 tracking-widest">
              {type === 'CREDENTIAL_REPORT' ? `System Record ID: ${user.id}` : `Registry Ref: ${loan?.id}/${type.slice(0,3)}`}
            </p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={handlePrint}
              disabled={isLoading}
              className="px-8 py-4 bg-emerald-800 text-white rounded-2xl font-black uppercase text-[10px] shadow-xl hover:bg-emerald-950 transition-all flex items-center gap-3"
            >
              <i className="fas fa-print"></i> Print / Save PDF
            </button>
            <button 
              onClick={onClose}
              className="w-12 h-12 flex items-center justify-center bg-white border rounded-2xl text-gray-400 hover:text-red-500 transition-all"
            >
              <i className="fas fa-times"></i>
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-grow overflow-y-auto p-12 bg-white flex justify-center">
          <div className="w-full max-w-[210mm] min-h-[297mm] p-[20mm] bg-white border border-gray-100 shadow-sm relative document-view">
             {isLoading ? (
               <div className="flex flex-col items-center justify-center h-full py-20 space-y-6">
                 <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                 <p className="text-[10px] font-black uppercase text-emerald-600 animate-pulse">Drafting Legal Document...</p>
               </div>
             ) : (
               <div className="legal-content-styled">
                 {type === 'CREDENTIAL_REPORT' && loan?.borrowerPhoto && (
                   <div className="mb-10 flex flex-col items-center border-b pb-10">
                     <p className="text-[10px] font-black uppercase text-gray-400 mb-4 tracking-widest">Verification Image</p>
                     <img src={loan.borrowerPhoto} className="w-48 h-48 object-cover rounded-3xl shadow-xl border-4 border-emerald-50" alt="Selfie" />
                   </div>
                 )}
                 <div dangerouslySetInnerHTML={{ __html: content }} />
               </div>
             )}

             {/* Watermark */}
             {!isLoading && (
               <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] rotate-45 select-none">
                 <span className="text-[120px] font-black uppercase">Internal Record</span>
               </div>
             )}
          </div>
        </div>
      </div>

      <style>{`
        .legal-content-styled {
          font-family: 'Times New Roman', serif;
          line-height: 1.5;
          color: #1a202c;
          font-size: 13px;
        }
        .legal-content-styled h1, .legal-content-styled h2 {
          font-family: 'Inter', sans-serif;
          font-weight: 900;
          text-transform: uppercase;
          border-bottom: 2px solid #064e3b;
          margin-bottom: 0.75rem;
          margin-top: 1.5rem;
          color: #064e3b;
        }
        @media print {
          body * { visibility: hidden; }
          .document-view, .document-view * { visibility: visible; }
          .document-view {
            position: absolute;
            left: 0;
            top: 0;
            width: 100% !important;
            height: auto !important;
            border: none;
            box-shadow: none;
            padding: 0;
            margin: 0;
          }
          .no-print { display: none !important; }
        }
      `}</style>
    </div>
  );
};

export default LegalDocumentModal;

import React, { useState } from 'react';
import { CollateralType, RepaymentMethod } from '../types';

interface LoanFormProps {
  onSubmit: (loanData: any) => void;
  isLoading: boolean;
}

const COLLATERAL_DATA: Record<CollateralType, { label: string; icon: string }> = {
  PHONE: { label: 'Phone', icon: 'fa-mobile-screen' },
  LAPTOP: { label: 'PC / Laptop', icon: 'fa-laptop' },
  CAR: { label: 'Vehicle', icon: 'fa-car' },
  APPLIANCE: { label: 'Appliance', icon: 'fa-plug' },
  LAND: { label: 'Land/Property', icon: 'fa-map-location' },
  OTHER: { label: 'Other', icon: 'fa-ellipsis' },
  NONE: { label: 'None', icon: 'fa-ban' }
};

const LoanForm: React.FC<LoanFormProps> = ({ onSubmit, isLoading }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    principal: '',
    purpose: '',
    tenure: '14 Days',
    repaymentMethod: 'CASH' as RepaymentMethod,
    collateralType: 'NONE' as CollateralType,
    collateralDescription: '',
    collateralSerial: '',
    collateralCondition: '',
    collateralLocation: '',
    hasAgreedToOwnership: false,
    hasAgreedToVerification: false
  });

  const [error, setError] = useState<string | null>(null);

  const nextStep = () => {
    if (step === 1 && (!formData.principal || !formData.purpose)) {
      setError("Please enter loan amount and purpose.");
      return;
    }
    if (step === 2 && (formData.collateralType === 'NONE' || !formData.collateralDescription)) {
      setError("Please provide complete collateral details.");
      return;
    }
    setError(null);
    setStep(step + 1);
  };

  const prevStep = () => setStep(step - 1);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.hasAgreedToOwnership || !formData.hasAgreedToVerification) {
      setError("You must agree to the legal declarations.");
      return;
    }
    onSubmit(formData);
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl p-10 border border-gray-100 dark:border-slate-700 w-full max-w-2xl mx-auto animate-fadeIn transition-colors">

      {/* Information Box - Text set to white for readability */}
      <div className="mb-10 p-5 bg-orange-600 dark:bg-orange-900/50 border-2 border-orange-200 dark:border-orange-800 rounded-[2.5rem] flex gap-5">
        <div className="w-12 h-12 bg-orange-500 text-white rounded-2xl flex items-center justify-center shrink-0 shadow-lg">
          <i className="fas fa-handshake-angle text-xl"></i>
        </div>
        <div>
          <p className="text-[11px] font-black uppercase text-white mb-1">Physical Payout Alert</p>
          <p className="text-[12px] text-white font-medium leading-relaxed">
            KwachaTime strictly operates via physical hand-to-hand disbursements at our office. No digital transfers for first-time loans.
          </p>
        </div>
      </div>

      <div className="flex justify-between items-center mb-10">
        <h2 className="text-2xl font-black text-emerald-950 dark:text-white uppercase tracking-tighter">Application Form</h2>
        <div className="flex gap-1">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className={`h-1.5 w-8 rounded-full ${step >= i ? 'bg-emerald-600' : 'bg-gray-100 dark:bg-slate-700'}`}></div>
          ))}
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">

        {step === 1 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 1: Requirements</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Amount (ZMW)</label>
                <input 
                  type="number" 
                  value={formData.principal}
                  onChange={e => setFormData({...formData, principal: e.target.value})}
                  placeholder="0.00"
                  className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-gray-900 dark:text-white"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Repayment Period</label>
                <select 
                  value={formData.tenure}
                  onChange={e => setFormData({...formData, tenure: e.target.value})}
                  className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold appearance-none text-gray-900 dark:text-white"
                >
                  <option>14 Days</option>
                  <option>30 Days</option>
                  <option>60 Days</option>
                </select>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Loan Purpose</label>
              <textarea 
                value={formData.purpose}
                onChange={e => setFormData({...formData, purpose: e.target.value})}
                placeholder="Reason for borrowing..."
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold h-32 text-gray-900 dark:text-white"
              />
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 2: Collateral Registry</h3>
            <div className="grid grid-cols-3 md:grid-cols-4 gap-4">
              {(Object.keys(COLLATERAL_DATA) as CollateralType[]).filter(k => k !== 'NONE').map(key => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setFormData({...formData, collateralType: key})}
                  className={`flex flex-col items-center justify-center p-4 rounded-3xl border-2 transition-all ${formData.collateralType === key ? 'bg-emerald-800 border-emerald-800 text-white shadow-xl scale-105' : 'bg-gray-50 dark:bg-slate-900 border-gray-100 dark:border-slate-700 text-gray-400'}`}
                >
                  <i className={`fas ${COLLATERAL_DATA[key].icon} text-xl mb-2`}></i>
                  <span className="text-[9px] font-black uppercase text-center">{COLLATERAL_DATA[key].label}</span>
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input 
                placeholder="Description (e.g. iPhone 15 Pro)"
                value={formData.collateralDescription}
                onChange={e => setFormData({...formData, collateralDescription: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs text-gray-900 dark:text-white"
              />
              <input 
                placeholder="Serial Number / IMEI"
                value={formData.collateralSerial}
                onChange={e => setFormData({...formData, collateralSerial: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs text-gray-900 dark:text-white"
              />
              <input 
                placeholder="Condition of Item"
                value={formData.collateralCondition}
                onChange={e => setFormData({...formData, collateralCondition: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs text-gray-900 dark:text-white"
              />
              <input 
                placeholder="Location of Item"
                value={formData.collateralLocation}
                onChange={e => setFormData({...formData, collateralLocation: e.target.value})}
                className="w-full bg-gray-50 dark:bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-xs text-gray-900 dark:text-white"
              />
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 3: Repayment Settings</h3>

            <div className="space-y-2">
              <label className="text-[10px] font-bold uppercase ml-4 text-gray-500">Repayment Plan</label>
              <div className="grid grid-cols-3 gap-3">
                {['CASH', 'BANK_TRANSFER', 'MOBILE_MONEY'].map(m => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setFormData({...formData, repaymentMethod: m as RepaymentMethod})}
                    className={`p-4 rounded-2xl border-2 text-[9px] font-black uppercase ${formData.repaymentMethod === m ? 'bg-emerald-800 border-emerald-800 text-white' : 'bg-gray-50 dark:bg-slate-900 border-transparent text-gray-400'}`}
                  >
                    {m.replace('_', ' ')}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {step === 4 && (
          <div className="space-y-6 animate-fadeIn">
            <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Section 4: Legal Finalization</h3>
            <div className="space-y-4">
              <label className="flex items-start gap-4 p-5 bg-gray-50 dark:bg-slate-900 rounded-3xl cursor-pointer hover:bg-emerald-50 transition-colors">
                <input 
                  type="checkbox" 
                  checked={formData.hasAgreedToOwnership}
                  onChange={e => setFormData({...formData, hasAgreedToOwnership: e.target.checked})}
                  className="mt-1 w-5 h-5 accent-emerald-600"
                />
                <span className="text-[11px] font-medium text-gray-600 dark:text-gray-400 leading-tight">
                  I confirm that I am the sole owner of the collateral described and I pledge it as security for this loan request.
                </span>
              </label>

              <label className="flex items-start gap-4 p-5 bg-gray-50 dark:bg-slate-900 rounded-3xl cursor-pointer hover:bg-emerald-50 transition-colors">
                <input 
                  type="checkbox" 
                  checked={formData.hasAgreedToVerification}
                  onChange={e => setFormData({...formData, hasAgreedToVerification: e.target.checked})}
                  className="mt-1 w-5 h-5 accent-emerald-600"
                />
                <span className="text-[11px] font-medium text-gray-600 dark:text-gray-400 leading-tight">
                  I authorize KwachaTime to verify the ownership of my collateral and perform a credit check for the permanent registry.
                </span>
              </label>
            </div>
          </div>
        )}

        {error && <p className="text-red-500 text-[10px] font-black text-center uppercase animate-shake">{error}</p>}

        <div className="flex gap-4">
          {step > 1 && (
            <button 
              type="button"
              onClick={prevStep}
              className="flex-1 py-6 bg-gray-100 dark:bg-slate-700 text-gray-400 rounded-[2rem] font-black uppercase tracking-widest transition-all"
            >
              Back
            </button>
          )}

          {step < 4 ? (
            <button 
              type="button"
              onClick={nextStep}
              className="flex-[2] py-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl transition-all"
            >
              Next
            </button>
          ) : (
            <button 
              type="submit"
              disabled={isLoading}
              className="flex-[2] py-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 disabled:opacity-50"
            >
              {isLoading ? "Submitting..." : "Apply Now"}
            </button>
          )}
        </div>
      </form>
    </div>
  );
};

