              <div className="space-y-6">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 pl-6 tracking-widest">Financial History</h3>
                 {allLoans.length === 0 ? (
                   <div className="p-32 text-center bg-gray-50 dark:bg-slate-900 rounded-[4rem] text-gray-300 font-black uppercase tracking-widest border-2 border-dashed">No Active Records</div>
