            {loginSequence !== 'IDLE' ? (
              <div className="py-20 flex flex-col items-center gap-8">
                <div className="w-20 h-20 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-xs font-black uppercase tracking-widest text-emerald-600 animate-pulse">{loginSequence}...</p>
              </div>
            ) : (
              <form onSubmit={handleInitialLogin} className="space-y-6 text-left">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Email Address</label>
                      <input name="email" type="text" placeholder="Enter email" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Full Legal Name</label>
                      <input name="name" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">NRC (ID Number)</label>
                      <input name="nrc" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Birth Date</label>
                      <input name="dob" type="text" placeholder="DD/MM/YYYY" className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Active Phone</label>
                      <input name="phone" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Residential Address</label>
                      <input name="address" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Current Employment</label>
                      <input name="employment" type="text" className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Next of Kin Name</label>
                      <input name="nok_name" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500" />
                   </div>
                </div>
                <button className="w-full py-6 bg-emerald-800 text-white rounded-[2.5rem] font-black uppercase tracking-widest mt-6 shadow-2xl transition-all active:scale-95">Complete Formalities & Enter</button>
              </form>
            )}
            <p className="mt-12 text-[9px] font-black text-gray-300 uppercase tracking-widest">v{APP_VERSION}</p>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout} themeMode={themeMode} onToggleTheme={() => setThemeMode(themeMode === 'light' ? 'dark' : 'light')}>

      {activeLegalDoc && (
        <LegalDocumentModal 
          user={activeLegalDoc.user || currentUser}
          loan={activeLegalDoc.loan}
          type={activeLegalDoc.type}
          onClose={() => setActiveLegalDoc(null)}
        />
