                 <div>
                    <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-widest">Active Credit Record</p>
                    <p className="text-6xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 </div>
                 <div className="w-16 h-16 bg-white/10 rounded-3xl flex items-center justify-center text-3xl">
                    <i className="fas fa-coins"></i>
                 </div>
              </div>

              <div className="space-y-6">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 pl-6 tracking-widest">Financial History</h3>
                 {allLoans.length === 0 ? (
                   <div className="p-32 text-center bg-gray-50 dark:bg-slate-900 rounded-[4rem] text-gray-300 font-black uppercase tracking-widest border-2 border-dashed">No Active Records</div>
                 ) : (
                   allLoans.map(loan => (
                    <div key={loan.id} className="p-10 bg-white dark:bg-slate-900 rounded-[4rem] shadow-xl border-2 border-gray-50 dark:border-slate-800 animate-slideUp">
                       <div className="flex justify-between items-start">
                          <div>
                             <p className="text-[10px] font-black uppercase text-gray-400 mb-1">REQ: {loan.id}</p>
                             <h4 className="text-3xl font-black">{formatCurrency(loan.principal)}</h4>
                             <p className="px-3 py-1 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-lg text-[9px] font-black uppercase mt-3 inline-block">{loan.collateralDescription}</p>
                          </div>
                          <div className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-700'}`}>
