                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Active Phone</label>
                      <input name="phone" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500 shadow-inner" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Residential Address</label>
                      <input name="address" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500 shadow-inner" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Current Employment</label>
                      <input name="employment" type="text" className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500 shadow-inner" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Next of Kin Name</label>
                      <input name="nok_name" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500 shadow-inner" />
                   </div>
                </div>
                <button className="w-full py-6 bg-emerald-800 text-white rounded-[2.5rem] font-black uppercase tracking-widest mt-6 shadow-2xl transition-all active:scale-95">Complete Formalities & Enter</button>
              </form>
            )}
            <p className="mt-12 text-[9px] font-black text-gray-300 uppercase tracking-widest">v{APP_VERSION}</p>
          </div>
        </div>
      </Layout>
    );
  }

