           <div className="lg:col-span-2 space-y-12">
              <div className="bg-emerald-950 text-white p-12 rounded-[4.5rem] shadow-2xl relative overflow-hidden flex justify-between items-end border border-emerald-900">
                 <div>
                    <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-widest">Active Credit Record</p>
                    <p className="text-6xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 </div>
                 <div className="w-16 h-16 bg-white/10 rounded-3xl flex items-center justify-center text-3xl">
                    <i className="fas fa-coins"></i>
                 </div>
              </div>

              <div className="space-y-6">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 pl-6 tracking-widest">Financial History</h3>
                 {allLoans.length === 0 ? (
                   <div className="p-32 text-center bg-gray-50 dark:bg-slate-900 rounded-[4rem] text-gray-300 font-black uppercase tracking-widest border-2 border-dashed">No Active Records</div>
                 ) : (
                   allLoans.map(loan => (
                    <div key={loan.id} className="p-10 bg-white dark:bg-slate-900 rounded-[4rem] shadow-xl border-2 border-gray-50 dark:border-slate-800 animate-slideUp">
                       <div className="flex justify-between items-start">
                          <div>
                             <p className="text-[10px] font-black uppercase text-gray-400 mb-1">REQ: {loan.id}</p>
                             <h4 className="text-3xl font-black">{formatCurrency(loan.principal)}</h4>
                             <p className="px-3 py-1 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-lg text-[9px] font-black uppercase mt-3 inline-block">{loan.collateralDescription}</p>
                          </div>
                          <div className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-700'}`}>
                             {loan.status}
                          </div>
                       </div>
                    </div>
                   ))
                 )}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: parseFloat(data.principal),
                   purpose: data.purpose,
                   tenure: data.tenure,
                   repaymentMethod: data.repaymentMethod,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 86400000).toISOString(),
                   collateralType: data.collateralType,
                   collateralDescription: data.collateralDescription,
                   collateralSerial: data.collateralSerial,
                   collateralCondition: data.collateralCondition,
                   collateralLocation: data.collateralLocation,
                   hasAgreedToOwnership: data.hasAgreedToOwnership,
                   hasAgreedToVerification: data.hasAgreedToVerification
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
      <CurrencyConverter />
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { User, Loan } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAppIcon = async () => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: 'A professional app icon for a Zambian money lending app named "KwachaTime". The design should feature a minimalist fusion of a modern clock face and a Zambian Kwacha symbol (a large "K"). Primary colors: deep emerald green (#064e3b) and vibrant orange (#f97316). The style should be vector-based, clean, and modern with a slight 3D depth, centered on a rounded square background.',
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("Icon generation failed", error);
    return null;
  }
};

export const generateLoanStatusEmail = async (user: User, loan: Loan, status: string, reason?: string) => {
  try {
    const ai = getAI();
    const prompt = `
      Act as the Automated Communications Officer for KwachaTime Micro-Lending (Lusaka, Zambia).
      Craft a professional email to a borrower regarding their loan status.
      Recipient Name: ${user.name}, Loan ID: ${loan.id}, Status: ${status}.
      Return ONLY JSON with "subject" and "body" (HTML).
    `;
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            subject: { type: Type.STRING },
            body: { type: Type.STRING },
          },
          required: ["subject", "body"],
        },
      },
    });
    return JSON.parse(response.text || '{"subject": "Loan Update", "body": "Update on your loan."}');
  } catch (error) {
    return { subject: "Loan Update", body: "Your status has changed." };
  }
};

