    setIsProcessing(true);
    try {
      if (status === 'DISBURSED') {
        await apiService.disburseLoan(loanId);
      } else {
        await apiService.updateLoanStatus(loanId, status);
      }
      await refreshData();
    } catch (e) {} finally {
      setIsProcessing(false);
    }
  };

  if (!currentUser) {
    return (
      <Layout>
        <div className="flex items-center justify-center min-h-screen p-4 py-20">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-2xl border border-gray-100 dark:border-slate-800 text-center transition-all">
