            {loginSequence !== 'IDLE' ? (
              <div className="py-20 flex flex-col items-center gap-8">
                <div className="w-20 h-20 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-xs font-black uppercase tracking-widest text-emerald-600 animate-pulse">{loginSequence}...</p>
              </div>
            ) : (
              <form onSubmit={handleInitialLogin} className="space-y-6 text-left">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Email Address</label>
                      <input name="email" type="text" placeholder="Enter email" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500 shadow-inner" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Full Legal Name</label>
                      <input name="name" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500 shadow-inner" />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase text-gray-400 ml-4">NRC (ID Number)</label>
                      <input name="nrc" type="text" required className="w-full bg-slate-900 p-5 rounded-3xl outline-none border-2 border-transparent focus:border-emerald-500 font-bold text-white placeholder:text-gray-500 shadow-inner" />
                   </div>
                   <div className="space-y-1">
