            {[
              { id: 'MONITOR', icon: 'fa-chart-line', label: 'Monitor' },
              { id: 'PENDING', icon: 'fa-shield-halved', label: 'Approvals' },
              { id: 'USERS', icon: 'fa-address-book', label: 'Client Registry' },
              { id: 'SIMULATE', icon: 'fa-vial-circle-check', label: 'Simulation' },
              { id: 'BRANDING', icon: 'fa-palette', label: 'Branding' },
              { id: 'LOGS', icon: 'fa-list-check', label: 'Audit Trail' }
            ].map(tab => (
              <button 
                key={tab.id} 
                onClick={() => setActiveAdminTab(tab.id as any)}
                className={`w-full flex items-center gap-5 p-6 rounded-[2rem] text-[11px] font-black uppercase transition-all ${activeAdminTab === tab.id ? 'bg-emerald-800 text-white shadow-xl scale-105' : 'bg-white dark:bg-slate-900 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800'}`}
              >
                <i className={`fas ${tab.icon} w-6 text-lg`}></i>
                {tab.label}
              </button>
            ))}
          </div>

          <div className="lg:col-span-3 space-y-8">
            {activeAdminTab === 'USERS' && (
              <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-xl">
                 <div className="flex justify-between items-center mb-10">
                   <h3 className="text-2xl font-black uppercase">Client Credential Ledger (2026)</h3>
                   <i className="fas fa-file-pdf text-emerald-100 dark:text-slate-800 text-4xl"></i>
                 </div>
                 <div className="space-y-4">
                    {allUsers.filter(u => u.id !== 'SIM-USER').map(u => {
                      const latestLoan = allLoans.find(l => l.userId === u.id);
                      return (
                        <div key={u.id} className="p-8 bg-gray-50 dark:bg-slate-800 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-center border border-gray-100 dark:border-slate-700 gap-6">
                          <div className="flex items-center gap-6 w-full">
                            <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center border-2 border-white dark:border-slate-700">
                               <i className="fas fa-user text-emerald-800 dark:text-emerald-400"></i>
                            </div>
                            <div>
                              <p className="text-xl font-black">{u.name}</p>
                              <p className="text-[10px] text-emerald-600 font-bold uppercase">NRC: {u.nrc} • Phone: {u.phone}</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-4 w-full md:w-auto justify-end">
                             <button 
                               onClick={() => setActiveLegalDoc({ user: u, loan: latestLoan, type: 'CREDENTIAL_REPORT' })}
                               className="px-6 py-4 bg-emerald-800 text-white rounded-2xl text-[9px] font-black uppercase hover:bg-emerald-950 transition-all flex items-center gap-3 shadow-lg whitespace-nowrap"
                             >
                               <i className="fas fa-id-card"></i> Export KYC PDF
                             </button>
                          </div>
                        </div>
                      );
                    })}
                    {allUsers.filter(u => u.id !== 'SIM-USER').length === 0 && (
                      <div className="py-20 text-center text-gray-300 font-black uppercase tracking-widest">No clients registered in ledger</div>
                    )}
                 </div>
              </div>
            )}

            {activeAdminTab === 'BRANDING' && (
              <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-xl border-4 border-emerald-50 dark:border-emerald-900/20">
                <div className="flex justify-between items-start mb-10">
                  <div>
                    <h3 className="text-2xl font-black uppercase text-emerald-600">Visual Identity System</h3>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Generated by KwachaTime AI Creative Engine (2026)</p>
                  </div>
                  <i className="fas fa-palette text-emerald-100 text-5xl"></i>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                  <div className="space-y-6">
                    <p className="text-xs text-gray-500 font-medium leading-relaxed">
                      Use this engine to generate high-resolution branding assets for the KwachaTime PWA and official stationery. The AI fuses "Time" and "Kwacha" concepts into a cohesive brand mark.
                    </p>
                    <button 
                      onClick={handleGenerateIcon}
                      disabled={isGeneratingIcon}
                      className="w-full py-6 bg-emerald-800 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl transition-all active:scale-95 disabled:opacity-50 flex items-center justify-center gap-3"
                    >
                      {isGeneratingIcon ? (
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                      ) : (
                        <><i className="fas fa-wand-magic-sparkles"></i> Generate App Icon</>
                      )}
                    </button>
                  </div>

                  <div className="flex flex-col items-center justify-center p-8 bg-gray-50 dark:bg-slate-800 rounded-[3rem] border-2 border-dashed border-gray-200 dark:border-slate-700 min-h-[300px]">
                    {generatedIcon ? (
                      <div className="text-center animate-fadeIn">
                        <img src={generatedIcon} alt="Generated App Icon" className="w-48 h-48 rounded-[2.5rem] shadow-2xl mb-6 mx-auto border-4 border-white" />
                        <p className="text-[10px] font-black uppercase text-emerald-600">Official Brand Mark v1.0</p>
                        <a href={generatedIcon} download="KwachaTime-AppIcon.png" className="mt-4 inline-block text-[9px] font-black uppercase text-gray-400 hover:text-emerald-600 transition-all underline">Download PNG Asset</a>
                      </div>
                    ) : (
                      <div className="text-center">
                        <i className="fas fa-image text-4xl text-gray-200 mb-4"></i>
                        <p className="text-[10px] font-black uppercase text-gray-300">Preview Area Empty</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}

            {activeAdminTab === 'PENDING' && (
              <div className="space-y-6">
                {allLoans.filter(l => l.status === 'PENDING').map(loan => {
                  const borrower = allUsers.find(u => u.id === loan.userId);
                  return (
                    <div key={loan.id} className="bg-white dark:bg-slate-900 p-10 rounded-[4rem] shadow-xl border border-gray-50 dark:border-slate-800">
                       <div className="flex justify-between items-start mb-8">
                          <div className="flex gap-6 items-start">
                            <div className="w-20 h-20 bg-gray-100 dark:bg-slate-800 rounded-2xl flex items-center justify-center border-2 border-emerald-50 shadow-inner">
                               <i className="fas fa-file-invoice-dollar text-3xl text-gray-300"></i>
                            </div>
                            <div>
                              <p className="text-[10px] font-black uppercase text-emerald-600 mb-2">Request ID: {loan.id}</p>
                              <h4 className="text-2xl font-black">{loan.userName}</h4>
                              <p className="text-3xl font-black mt-2 text-emerald-900 dark:text-emerald-400">{formatCurrency(loan.principal)}</p>
                            </div>
                          </div>
                          <div className="flex flex-col gap-3">
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'CREDENTIAL_REPORT' })} className="px-6 py-3 bg-blue-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg flex items-center gap-2">
                               <i className="fas fa-id-card"></i> View KYC
                             </button>
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'AGREEMENT' })} className="px-6 py-3 bg-slate-900 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg">Draft Agreement</button>
                             <button onClick={() => setActiveLegalDoc({ user: borrower, loan, type: 'LETTER_OF_SALE' })} className="px-6 py-3 bg-orange-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-lg">Sale Letter</button>
                          </div>
                       </div>
                       <div className="flex gap-4">
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'APPROVED')} className="flex-1 py-5 bg-emerald-800 text-white rounded-3xl font-black uppercase text-[11px] shadow-lg">Approve Payout</button>
                          <button onClick={() => handleManualStatusUpdate(loan.id, 'REJECTED')} className="flex-1 py-5 bg-red-800 text-white rounded-3xl font-black uppercase text-[11px] shadow-lg">Reject Request</button>
                       </div>
                    </div>
                  );
                })}
              </div>
            )}

            {activeAdminTab === 'SIMULATE' && (
              <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-xl border-4 border-indigo-50 dark:border-indigo-900/20">
                 <h3 className="text-2xl font-black uppercase text-indigo-600 mb-10">Simulation Stress Engine</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                    <input type="text" placeholder="Scenario Subject" value={simName} onChange={(e) => setSimName(e.target.value)} className="bg-slate-900 p-6 rounded-3xl outline-none font-bold text-white placeholder:text-gray-500 shadow-inner" />
                    <input type="number" placeholder="Principal ZMW" value={simPrincipal} onChange={(e) => setSimPrincipal(e.target.value)} className="bg-slate-900 p-6 rounded-3xl outline-none font-bold text-white placeholder:text-gray-500 shadow-inner" />
                 </div>
                 <button onClick={() => apiService.simulateLoan({ name: simName, principal: parseFloat(simPrincipal), disbursedDate: new Date().toISOString(), dueDate: new Date(Date.now() + 14 * 86400000).toISOString() }).then(() => { setSimName(''); setSimPrincipal(''); refreshData(); })} className="w-full py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase shadow-xl mb-12 transition-all active:scale-95">Inject Scenario Model</button>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
           <div className="lg:col-span-1 space-y-12">
              <Roadmap />
              <OfficeLocator />
           </div>

           <div className="lg:col-span-2 space-y-12">
              <div className="bg-emerald-950 text-white p-12 rounded-[4.5rem] shadow-2xl relative overflow-hidden flex justify-between items-end border border-emerald-900">
                 <div>
                    <p className="text-[11px] font-black uppercase text-emerald-500 mb-3 tracking-widest">Active Credit Record (2026)</p>
                    <p className="text-6xl font-black tracking-tighter">{formatCurrency(currentUser.walletBalance || 0)}</p>
                 </div>
                 <div className="w-16 h-16 bg-white/10 rounded-3xl flex items-center justify-center text-3xl">
                    <i className="fas fa-coins"></i>
                 </div>
              </div>

              <div className="space-y-6">
                 <h3 className="text-[10px] font-black uppercase text-gray-400 pl-6 tracking-widest">Financial History</h3>
                 {allLoans.length === 0 ? (
                   <div className="p-32 text-center bg-gray-50 dark:bg-slate-900 rounded-[4rem] text-gray-300 font-black uppercase tracking-widest border-2 border-dashed">No Active Records</div>
                 ) : (
                   allLoans.map(loan => (
                    <div key={loan.id} className="p-10 bg-white dark:bg-slate-900 rounded-[4rem] shadow-xl border-2 border-gray-50 dark:border-slate-800 animate-slideUp">
                       <div className="flex justify-between items-start">
                          <div>
                             <p className="text-[10px] font-black uppercase text-gray-400 mb-1">REQ: {loan.id}</p>
                             <h4 className="text-3xl font-black">{formatCurrency(loan.principal)}</h4>
                             <p className="px-3 py-1 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-400 rounded-lg text-[9px] font-black uppercase mt-3 inline-block">{loan.collateralDescription}</p>
                          </div>
                          <div className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg text-white ${loan.status === 'PENDING' ? 'bg-orange-500' : 'bg-emerald-700'}`}>
                             {loan.status}
                          </div>
                       </div>
                    </div>
                   ))
                 )}
              </div>

              <LoanForm onSubmit={async (data) => {
                const loan: Loan = {
                   id: `RQ-${Math.random().toString(36).substr(2, 4).toUpperCase()}`,
                   userId: currentUser.id,
                   userName: currentUser.name,
                   principal: parseFloat(data.principal),
                   purpose: data.purpose,
                   tenure: data.tenure,
                   repaymentMethod: data.repaymentMethod,
                   status: 'PENDING',
                   createdAt: new Date().toISOString(),
                   dueDate: new Date(Date.now() + 14 * 86400000).toISOString(),
                   collateralType: data.collateralType,
                   collateralDescription: data.collateralDescription,
                   collateralSerial: data.collateralSerial,
                   collateralCondition: data.collateralCondition,
                   collateralLocation: data.collateralLocation,
                   hasAgreedToOwnership: data.hasAgreedToOwnership,
                   hasAgreedToVerification: data.hasAgreedToVerification
                };
                await apiService.submitLoanRequest(loan);
                refreshData();
              }} isLoading={false} />
           </div>
        </div>
      )}
      <CurrencyConverter />
    </Layout>
  );
};

export default App;
